window.__D("tolt-1",[[20,"(שייך לפסוק ארדה נא וגו')"],[20,"⟦יג,ג⟧<b>פתח<\/b> אליהו אנת הוא חד ולא בחושבן אנת הוא דאפיקת עשר תיקונין כו'. להבין ענין זה למה נק' י\"ס בשם תקונין. צריך להקדים ביאור ענין מהות הנפש. כי הנה הנפש מצד עצמה היא אור פשוט בלי התחלקות שכל ומדות והשכל והמדות שלה הן בחי' לבושין לנפש שהנפש יש לה שכל ומדות אבל אינן מהות ועצמיות הנפש (ומ\"ש בתניא שהנפש עצמה מתחלקת לשכל ומדות שהם נקראים עצמיות הנפש אין זה אלא לגבי מחדו\"מ שהן לבושין נפרדין ממש ממהות הנפש שהן בחי' בי\"ע שע\"ז אמר לבושין תקינת לון כו' דאינון בי\"ע אבל השכל והמדות עם היות שהן בחי' לבושין אינן לבושין נפרדין ממש אלא כמו בחי' כלים דאצי' דאיהו וגרמוהי חד כו' ולכן נקראין בשם עצמיות ולא עצמיות ממש) אלא שהן נקראין בשם תיקונין שהנפש מתתקנת ומתלבשת בהן. וכמו שת\"א ע\"פ לא ילבש גבר שמלת אשה לא יתקן גבר בתיקוני אתתא. וענין תקון הוא מלשון תכשיט שמתקשט בו ומתפעל ממנו והרי מתאחד עם תכשיט זה כאלו הוא מגופו ממש."],[20,"וכמו הנפש עם הגוף שעם היות שהגוף הוא לבוש לנפש מ\"מ הרי הנפש מתפעלת ממקרי הגוף שכשהגוף נוקף אצבעו מרגשת הנפש וכן מה שעולה ברצון הנפש לפעול איזה פעולה באברים האברים נשמעים לרצון זה תיכף ומיד כשעולה ברצונו לעשות הפעולה. הרגל להלוך בו כו'. בלי שום קדימת התפשטות והמשכת המחשבה מהמוח ברגל שא\"כ היה איזה שיהוי זמן מה והרי אינו שוהה אפילו רגע אלא מיד שעולה ברצונו כו'. אך אין זה אלא מפני שהגוף מתאחד עם הנפש והנפש פועלת בו כרצונה כאילו היה עצמותה ומהותה ממש ואף שהגוף הוא לבוש הנפש מ\"מ הוא מתאחד עם הנפש."],[20,"וכמו\"כ יובן עד\"ז ענין השכל והמדות של הנפש שהן ג\"כ רק בחי' תקונין ולבושין שהנפש מתתקנת ומתלבשת בהן והן כלי הנפש שבהן ועל ידן פועלת הנפש כגרזן ⟦יג,ד⟧ביד החוצב בו. לאהוב במדת האהבה ולהשכיל בחכמה כו' שכל זה וכיוצא בזה הוא רק פעולת הנפש והתפשטותה שאינן אלא ממנה לזולתה אבל הנפש מצד עצמה היא למע' מכל הבחי' הללו. שהרי השכל והמדות הם מקבלים שינויים כי במדות יש קטנות וגדלות שהקטן אוהב דברים קטנים כו'."],[20,"והשכל כל זמן שמזקינים כו'. ולא שייך כ\"ז בעצמיות הנפש ומהותה שהיא אינה בעלת שינויים כלל. ואינה מקבלת שינויים ממקרי הגוף שאינה מתלבשת בעצמותה בגוף אלא הארותיה וכחותיה שהן המתפשטות בגוף ומתלבשות בו הן מקבלים שנויים מצד הגוף המקבל בקטן כך ובזקן כך כו'. וגם השכל והמדות אינן רק הארות הנפש וכחותיה המתפשטות בגוף ואינן עצמיות הנפש ומהותה. אלא שהנפש פועלת ומתפשטת בכחות והארות הללו ומ\"מ אינן לבושין נפרדים ממש כמו מחדו\"מ שהן הארות וכחות המלבישים ממש את הנפש (כמו לבוש המכסה כו') אבל השכל והמדות הן הארות מעצמיות הנפש ואינן לבושין ממש אלא תקונין שעצמותה מתתקנת ומתנאה בהן כמו תקון התכשיט שהוא המיפה את האדם שמתקשט בו ומתנאה:"],[20,"<b>ועד\"ז<\/b> יובן גם למעלה בי\"ס שנק' תקונין (והיינו חכמה ומדות דאצי' דאיהו וגרמוהי חד כו'. אבל בי\"ע הן בחי' לבושין ממש ועליהם אמר לבושין תקינת לון כו'). כי הנה אנת הוא חכים פי' אנת הוא היינו אא\"ס חכים שנמשך בבחי' חכמה ע\"ד במקום שאתה מוצא גדולתו כו' ועדיין אינו חכים בחכמה ידיעא אלא שנק' חכים לפי שהוא מקור החכמה וממנו המשכת חכמה בבי\"ע הגם שאין ערוך חכמה דבריאה כו' וכ\"ש דעשיי' כו' להיות נק' בשם חכים ע\"ש זה. הנה הענין יובן עד\"מ ממה שארז\"ל אין לך כל עשב כו' וגבוה מעל גבוה כו'."],[20,"והרי התפוח הגשמי יש בו מתיקות וחיך אוכל יטעם האם נאמר שיש בכח הצומח אשר בארץ טעם ומתיקות ג\"כ ופשיטא במזל שאינו מערך ומהות זה כלל. אלא ⟦יד,א⟧הענין הוא שהמתיקות נמשך מחסד ומרירו מגבורה והרי הם ענינים רוחניים רק שבהשתלשלות וסדר ירידת המדרגות מדרגה אחר מדרגה נתגשמו עד שנמשך מבחי' חסד מתיקות כו'. עם היות שאין ערוך אליו מ\"מ הוא ממזגו ותכונתו וכמו שרואין כמה מיני עריבות ומתיקות ברוחניות כמו תענוג של דבר חכמה הוא ג\"כ מתיקות וכן תענוג של ניגון שהוא מן הקול היוצא מן הלב בחי' המדות."],[20,"ולכן בכמה ירידות והשתלשלות נעשה מתיקות גשמי ממש הגם שההפרש וההבדל רב ביניהם. וכך הוא הענין בבחי' חכמה שיש בה ג\"כ גבוה מעל גבוה. והגם שחכמה דבריאה אינה מערך ולא מהות חכמה הנראית ונגלית בעשייה מ\"מ הוא מקור ושרש להיות ממנה התהוות בחי' חכמה דעשי' הנגלית כו'."],[20,"וכך היא חכמה דאצי' עם היות שהוא בחי' חכים ולא בחכמה ידיעא. מ\"מ היא בחי' מקור דמקור כו'. אבל להיות אנת הוא חכים דהיינו המשכת אור א\"ס בחכמה הנה החכמה ממש מאין תמצא ולכן היא בחי' ענוותנותו ית' שהוא ירידה גדולה לפניו ית' וזהו לשון אצי' בלה\"ק שהוא ל' ירידה והשפלה ממדרגתו העליונה להשפיל א\"ע כאלו הוא במדרגה פחותה וכמו ואצלתי מן הרוח דגבי משה דלפי שאמר מאין לי בשר שהיתה מדרגתו במעלה העליונה ולא הי' יכול להשפיל א\"ע בהמשכת בשר גשמי לכך אמר לו הקדוש ב\"ה אספה לי שבעים איש שהם במדרגה הפחותה היינו שלא יהיו מתגשמי' ממש אלא ואצלתי מן הרוח אשר עליך ושמתי עליהם פי' שאוריד ואמשיך בחי' שלך שיהי' למטה ממדרגתך."],[20,"ושמתי עליהם שיהי' יניקה גם להם ממדרגה זו אבל לא שיהיו עולים במעלת ומדרגת משה עצמו כו'. וכמו\"כ למעלה ענין אצי' הוא בחי' ירידה להיות התלבשות אור א\"ס בחכמה כו' ולכן נק' ע\"ס דאצי' עשר תקונין שהן בחי' לבושין לאור א\"ס ולא עצמיות כו' ומכל מקום אינן לבושין ממש אלא תקונין משום דאיהו וגרמוהי חד כו'. משא\"כ בי\"ע כנ\"ל:"],[20,"<b>וזהו<\/b> אנת הוא חד ולא בחושבן שאינו נמנה בכלל הי\"ס (וקאי על כ\"ע הממוצע בין המאציל לנאצלים) שאין ערוך אליו כלל כי התהוות חכמה מהכתר היא מאין ממש ולא כסדר השתלשלות שהן בחי' התהוות יש מיש כו'. והנה בכל העולמות אבי\"ע יש בחי' כתר הממוצע. כי מלכות דאצילות נעשה כתר לבריאה."],[20,"ומלכות דבריאה כתר ליצירה. אך ההפרש בין כתר דאצילות לכתר שבכל העולמות כי התהוות אצילות הוא ע\"י צמצום אור א\"ס להיות מקום פנוי וחלל ממש כו' והתהוות בי\"ע היינו ע\"י פרסא המפסיק בין אצי' לבריאה ובין בריאה ליצירה כו' ולא מקום פנוי."],[20,"וההפרש שבין פרסא למקום פנוי יובן בהקדם ענין הצמצום באור א\"ס. כי הנה אור א\"ס היינו אור וגילוי להיות איזה התפשטות והתהוות מקור וחיות ואור א\"ס שבעצמותו היינו בחי' זו שיש בו אור להיות מאיר ומתפשט להוות ולהחיות."],[20,"וזהו קודם שנברא העולם היה הוא ושמו בלבד דהיינו הוא א\"ס בעצמו. ושמו הוא אור א\"ס שבעצמותו שהוא רק בחי' שמו שהוא בחי' הגילוי דהיינו מה שיכול להיות מתגלה ומתפשט כמו זיו השמש מהשמש שהזיו הוא האור שיש בשמש להאיר על הארץ והשמש עצמו היינו גוף השמש עצמו והנה האור היוצא מהשמש נק' בשם אור כמו שכתוב ויקרא אלקים לאור יום שהיום נק' אור ע\"ש התפשטות האור והזיו מה שמאיר ביום משא\"כ עצמיות השמש נקרא מאור. וכמ\"ש את שני המארת הגדלים כו'. וכך הוא באור א\"ס שהאור נקרא הגילוי שמתפשט ממנו התהוות האור וחיות כו' וא\"ס בעצמו הוא בחי' המאור שהוא מקור האור וממנו נמשך האור:"],[20,"⟦יד,ב⟧<b>והנה<\/b> הצמצום היה באור א\"ס דהיינו שהאור נכלל במאור כי לפי שאין העולמות יכולים לקבל גילוי אוא\"ס כמו שהוא בעצמותו. והיו בטלים במציאות ממש כו' לכך צמצם האור שיוכלל במאור (להיות רק בכח ולא בפועל) ויתעלם בו שלא יהיה גילוי האור רק המאור (אבל במאור שהוא א\"ס עצמו לא שייך צמצום ח\"ו ולא העלם ואדרבה המאור הוא בהתגלות ולכן אפילו תנוקות יודעים שיש שם אלוה מצוי כו' אף שאין בהם השגה ותפיסה איך ומה לפי שאין בהם גילוי האור שמ\"מ המאור עצמו הוא נמצא למטה כמו למעלה) ולכן נק' צמצום זה מקום פנוי וחלל כו' פי' שהוא חלל וריק מן האור שאין בו אור והתגלות כלל אלא נשאר בכח במאור וכמשל הנפש שבבואה לגוף נראה גילוי החיות שבה שמחיה את הגוף אבל קודם בואה לגוף אע\"פ שיש בה כח החיות להחיות את הגוף בהתלבשותה בו מ\"מ הרי החיות ההוא בכח ולא בפועל כ\"ז שלא נתלבשה עדיין בגוף להחיותו ולהוציא גילוי החיות מכח אל הפועל ומההעלם אל הגילוי."],[20,"וכן איש חכם שכשהחכמה שלו היא בבחי' התפשטות לזולתו או אפילו לעצמו דהיינו בשעה שעוסק בה אזי היא בבחי' גילוי שנראית ונגלית חכמתו לזולתו או לעצמו אבל בעידנא דלא עסיק הרי חכמתו רק בכח הנפש דהיינו שיש בכחו להשכיל אם יעסוק בהשכלה אבל לא באה לידי גילוי מכח אל הפועל וכן כח הראי' שבעין שאף שאם יסתום העין יש לו כח הראי' בשלימות מ\"מ לא בא לידי גילוי להיות העין רואה ממש עד שיפקח עיניו וכן כח ההילוך שברגל וכיוצא בזה בשאר החושים שבכל האברים כו'."],[20,"ועד\"ז יובן למעלה בבחי' הצמצום באוא\"ס שהאור והגילוי נתצמצם ונתעלם להיות רק בכח המאור ולא בפועל. וה\"ז נק' מקום פנוי וחלל לגבי האור שלא נשאר אור וגילוי. ואף שבאמת אינו מקום פנוי לגמרי ח\"ו שהרי המאור ממלא את כל החלל. שבמאור עצמו לא שייך צמצום והעלם ח\"ו והאור הוא בכח כו'. אעפ\"כ לפי שהמשיל האריז\"ל את הגילוי וחיות הנמשך מא\"ס והתהוות ע\"ס חכמה בינה כו' בשם אורות שהם כמו אור וזיו היוצא משמש ומאיר כו'. לכך קרא להצמצום מה שנכלל האור במאור בשם מקום פנוי שהוא התעלמות האור והתעלמות זו היא העדר האור עד שאינו עולה בשם כלל להיות נק' בשם חכמה ואפי' חכים ולא בחכמה ידיעא כו' (שאינו ניכר מורגש אפי' בכח) עד אחר כמה ירידות והשתלשלות המדרגות עקודים נקודים כו' שבחי' עינים היא מקור בחי' כלים להיות עולה בשם התהוות בחי' חכים ולא בחכמה ידיעא כו' דהיינו שאז נעשה בחי' כח התהוות איזו בחי' להיות מקור דמקור לבחי' חכמה כו' (וכל ענין צמצום זה להיות ירידת והשתלשלות עיגולים ויושר ופרסא דא\"ק להיות עקודים נקודים כו' הכל בכלל כתר דאצי' שהוא הממוצע להיות התהוות בחי' אצי' ע\"ס חכמה כו'):"],[20,"<b>אך<\/b> ענין הפרסא שבין אצי' לבריאה ובין בריאה כו' הוא עד\"מ כמו הרב שרוצה להסביר שכל גדול לתלמידו שאין התלמיד יכול לקבלו וצריך להמשילו בדרך משל וחידה וכמו משלי שלמה לשמרך מאשה זרה שהיא משל להנמשל שמדבר בע\"ז שהיא זרה מדברי תורה כו' וכן כיוצא בזה שאר ענינים כמו מה שמביאין משל מדברים פשוטים גשמיים לדברים העומדים ברומו של עולם כו'."],[20,"והנה המשל הזה הוא מענינים אחרים שלא מענין השכל שרוצה ללמד עליו רק לפי שבו ועל ידו יובן השכל לכן הוא מפסיקו בדברים אחרים. וזהו ענין פרסא המפסיק בין אצי' לבריאה שהוא בחי' מסך מבדיל לדבר מענינים אחרים שלא מענין אצי' ששם ⟦יד,ג⟧החכמה היא באופן אחר ומהות אחר שאינה מערך אופן ומהות חכמה שבעולם הבריאה ואין בבריאה יכולת לקבל הארת חכמה כמו שהיא באצי' רק שע\"י הפרסא המפסקת יהיה הארת בחי' חכמה בבריאה ג\"כ לפי מזגה ותכונתה כדי שיובן השכל להתלמיד מן המשל ומתחדש שם בחי' חכ' ג\"כ."],[20,"ולכן נק' בריאה ג\"כ יש מאין לפי שהיא מבחי' פרסא שהי' אור של תולדה דהיינו שנולד ונתחדש אור חכמה בבריאה כמו עד\"מ השכל שמתחדש אצל התלמיד מן המשל שאמר לו שהמשל הוא בענין אחר והוא מבין מזה דעת רבו והרי שכל זה הוא חדש אצלו שמתחדש ע\"י המשל. וכך אור זה דבריאה הוא אור חדש שמתחדש ע\"י הפרסא."],[20,"והנה המשכיל יבין שהתעלמות השכל של הרב בדרך המשל שאומר להתלמיד הוא שכל חכמתו בעצמות' הוא מלובש במשל זה ולא בכח לבד אלא בפו\"מ. רק לפי שהענין שהחכמה מלובשת בו הוא שלא מענין השכלת חכמתו בעצמו אלא יצא ללמד שלא כענינו לכך השכלת הרב בענין שמרמז בו אין ההשכלה ההיא נראית ונגלית להתלמיד אלא עפ\"י המשל שהוא ענין אחר וממנו מתחדש לו השכל עד שנק' אצלו שכל חדש אבל מ\"מ השכל החדש הזה במהותו ועצמותו כבר היה לעולמים ומרומז הכל במשל."],[20,"וכך הוא ענין התעלמות והתלבשות חכמה כו' דאצי' בבחי' פרסא להיות התהוות בחי' חכ' כו' דבריאה. שחכ' דאצי' היא במהותה ועצמותה בפו\"מ המתלבשת בבחי' הפרסא וגורמת התהוות חכמה דבריאה כו' הרי חכמה דבריאה אע\"פ שהיא אור חדש מ\"מ כבר יש לה איזה ערך ויחוס עם חכמה דאצי'. משא\"כ בחי' צמצום אוא\"ס להיות אצי' היינו התעלמות האור והעדרו עד שאינו עולה בשם כלל כנ\"ל ולכן נק' חד ולא בחושבן:"],[20,"<b>אך<\/b> אנת הוא דאפיקת עשר תקונין כו' שמ\"מ אינן בחי' נפרד לגמרי אף שאין להם ערך ויחס אליו כו' מ\"מ מאחר שהאור נכלל במאור כו'. וגם אח\"כ המשכת קו\"ח כו' הרי הכל מתאחדים עמו."],[20,"ואפי' לאנהגא בהון עלמין. עלמין הם בחי' כלים. ת' אלף עלמין דכסופין כו' דבאצי' איהו וחיוהי חד אפי' בבחי' כלים. וכמשל דבר גשמי הנתפס במחשבה שמחשבתו מקפת אפי' גשמי כאבן דומם הגם שאין המשל דומה לנמשל לא מני' כו'. מ\"מ קצת מן הקצת יכול המשכיל להתבונן ולהשכיל ע\"ד הנמשל מן המשל הזה כי כשם שיש כח ויכולת במחשבה להקיף את הדבר הגשמי בתוכו עם היותו דבר נפרד ממנו ממש ואין ערוך אליו מ\"מ יש כח המחבר להיות דבר הגשמי מוקף במחשבה שבמוח. כך למעלה יש כח ויכולת לחבר את האורות וכלים ושם למעלה הם מחוברים להיות הכל אחדות א' ולא יפרדו. מה שא\"א לצייר זה במוח שכלנו בעולם הנפרד ובחי' כלים דאצי' הם ת' אלף עלמין דכסופין כו' תליסר אלף עלמין כו' שהן מבחי' נימין ושערות כו' ועד\"ז התחלקות המחשבה לכמה מיני מחשבות עד אין מספר כו':"],[20,"<b>חד<\/b> אריך וחד קציר וחד בינוני הנה חסד נק' אריך לפי שהוא מתפשט מלמעלה מעלה למטה מטה כמו מים היורדים ממקום גבוה למקום נמוך. וגבורות שהן ממטה למעלה נק' קציר שהוא מקצר ומגביל השפעת החסד שיהי' לפי ההעלאה שממטה למעלה:"],[20,"<b>וזהו<\/b> ארדה נא ואראה הכצעקתה כו'. ר\"ל אראה אם הכצעקתה הבאה אלי ממטה למעלה ארדה נא מלמעלה למטה שיהיו שוין ההעלאה וההמשכה אך לפי שההמשכה מלמעלה למטה היא בחי' או\"י ובחי' חסדים לכך נאמר ארדה נא תחלה ואח\"כ אראה כו'. ובינוני הוא רחמנות בחי' ממוצע בין החסד שהוא שלא ⟦יד,ד⟧להבחין כלל אע\"פ שאינו הגון ובין גבורות לדון אם הוא הגון ורחמנות הוא ממוצע שמצד עצמו אינו ראוי מ\"מ צריך לרחם כו':"],[21,"<b>ארדה נא וגו'.<\/b> הנה הכצעקתה הוא לשון נקבה וכן הבאה. ועשו לשון נקבה ולשון זכר. וגם להבין מהו ארדה נא ואראה הלא משמים הביט ה'. אך פי' הכצעקתה היינו הצעקה העולה מבחי' מדת הדין שהיא בחי' מדת מלכות שנק' דין דינא דמלכותא דינא רק שהוא דינא רפיא מלך במשפט יעמיד ארץ וז\"ש הכצעקתה הבאה וכמ\"ש בערב היא באה."],[21,"ורחל באה. וביאור הענין הנה מתחלה יש להקדים לשון השגור בדחז\"ל גלוי וידוע לפני מי שאמר והיה העולם. גלוי וידוע דייקא. כי הנה הפילוסופים נלאו להשיג ענין ההשגחה פרטית כמו אין אדם נוקף אצבעו מלמטה אא\"כ מכריזין עליו מלמעלה דקשה להם כיון שהוא ית' יחיד ומיוחד אחד האמת וא\"כ איך יתכן ידיעת הש\"י הפרטים וההשגחה פרטי' לתת דעתו על ענינים רבים שהרי זה בחי' רבוי."],[21,"וחז\"ל כיוונו לתרץ זה בדבור אחד באמרם גלוי וידוע לפני כו' שאין ידיעתו ית' כדמיון ידיעת האדם איזו דבר שדעתו השיג הדבר ומתחלה לא ידעו וכשיודע הדבר הרי דעתו מלובשת בידיעה זו ומחשבה זו שנותן דעתו להשיגה וקודם ידיעתו היה דעתו פנוי וה\"ז בחי' שינוי והתפעלות משא\"כ למעלה ידיעתו ית' שיודע כל העולמות ופרטיהן אין הענין שדעתו מתלבשת ונתפסת בזה אלא ע\"ד גלוי וידוע שהכל גלוי וידוע לפניו ית' ממילא וא\"צ להיות נתפס ומתלבש בהדבר לידע (במכש\"כ ממה שמחיה ומהווה הדבר שלא ע\"י התלבשות בהדבר כ\"א על ידי היותו סוכ\"ע. וכ\"ש וק\"ו שידיעת הדבר ופרטיו א\"צ להיות ע\"י התלבשות ותפיסה בהדבר כו') וכיון שהוא גלוי וידוע אין שייך כלל קושייתם שהוא בחי' רבוי כי זה אינו רק במין ידיעת האדם שא\"א לו לידע דבר כ\"א ע\"י שדעתו ומחשבתו מתלבשים בידיעת הדבר. וזהו כי לא מחשבותי מחשבותיכם כו' כי הוא גלוי וידוע כו' (והמשכיל יבין דקות הדברים ולאו כל מוחא סביל דא). והנה כתיב (זכרי' סי' ד') שבעה אלה עיני ה' המה משוטטים בכל הארץ וכתיב (ד\"ה ב' י\"ו ט') כי ה' עיניו משוטטות בכל הארץ. ויש להבין דענין משוטטים ומשוטטות משמע שנמשך לראות ולעיין הדבר על ידי ראיה זו והרי זה כמו בחי' התלבשות בהדבר הנראה וידוע וזה לכאורה הפך ממ\"ש בפי' גלוי וידוע. אך הענין כי נודע שבע\"ס יש אורות וכלים כי בחי' חו\"ג זהו בחי' כלי אבל האור הוא הארה מא\"ס ב\"ה דלאו מכל אינון מדות איהו כלל רק שהאור מתלבש בהכלי שהוא חו\"ג ושאר המדות שהן נקראים בחינת כלים שהם מגבילים את האור ובהן ועל ידם נמשך האור להיות מחיה נבראים בע\"ג להיות התהוות מיכאל וגבריאל מחנה מיכאל מקבלים מבחי' חסד וגבריאל מבחי' גבורה שא\"א להיות המשכה זו מהאור עצמו כ\"א ע\"י הכלים. כמו שא\"א להיות השפעת כסף וזהב מהנשמה אא\"כ מלובשת בגוף ונותנת הנשמה צדקה לעני ע\"י היד הגשמי."],[21,"והנה כמו כן ע\"י הכלים דע\"ס הוא ג\"כ בחי' העלאת הזכות וחוב של כל נברא כי ע\"י שהאדם עובר עבירה קונה לו קטיגור אחד נעשה פגם וכתם באותו המלאך הממונה ע\"ז כי יש מלאכים שמקבלים ממדה זו ויש ממדה זו כנ\"ל בענין מיכאל וגבריאל כו' ומלאך זה מעלה הדבר למלאך גבוה ממנו עד שמתעלה בכלים דע\"ס דמלכות דאצי' המתלבשים בבי\"ע ובתוך הכלי מלובש האור מא\"ס ב\"ה."],[21,"ונמצא ע\"י הכלים מתעלה להאור א\"ס ב\"ה המלובש בהכלים דע\"ס. ולכן נאמר ע\"ז עיניו משוטטות שהוא בחי' הכלים דע\"ס. ⟦טו,א⟧וגם המלאכים המקבלים מהם נק' מארי דעיינין ויש מארי דאודנין."],[21,"והם משוטטים בכל הארץ כמאמר דע מה למעלה ממך עין רואה כו' ובהכלים שייך לומר משוטטים בבחינת התלבשות בהדבר. ובהם וע\"י מתעלה הדבר בבחי' האור המלובש בתוכן מא\"ס ב\"ה והוא ע\"ד גלוי וידוע שידיעה זו שבכלים דע\"ס שעל ידי עיניו משוטטים היא בחי' גלוי וידוע לאור א\"ס ב\"ה המלובש בהכלים כיון שהאור באמת לאו מכל אינון מדות איהו כלל אע\"פ שמלובש בהכלי כו'."],[21,"וזהו תירוץ לקושיית הפילוסופים שאין ידיעה והשגחה זו גורם בחי' רבוי כי ההשגחה ע\"ד עיניו משוטטות הוא ע\"י הכלים כנ\"ל אבל הידיעה בא\"ס ב\"ה המלובש בהכלים מה שיודע ורואה מה שעיניו משוטטות הנה ידיעתו יתברך זו היא בבחי' גלוי וידוע כו':"],[21,"הגה\"ה(ועיין בפרדס שער פ\"ח ושער ד' פ\"ט מענין זה ובזוהר פקודי רנ\"ב ע\"א ואלין עיני ה' כולהו נטלי אשגחותא כו' עיי\"ש וברע\"מ פ' שופטים ד' ער\"ה סע\"א. ויש להבין כיון דפי' עיני ה' הם הכלים דע\"ס דאבי\"ע והמלאכים. א\"כ איך שייך שהבורא ית' יצטרך לידע את כל הנבראים ע\"י אמצעות הע\"ס והרי היוצר עין הלא יביט בעצמו דבשלמא לענין ההשפעה והמשכת החיות בהנבראים הוצרך להיות ע\"י הכלים דע\"ס שאל\"כ לא יוכלו הנבראי' לקבל משא\"כ לענין ידיעת השי\"ת שיודע את כל הנבראי' אין שייך לומר כן ח\"ו וא\"כ למה צ\"ל בחי' העינים שהם הכלים משוטטים כו' דהא בודאי הכל גלוי וידוע לפניו ית' בעצמו ביתר שאת שלא ע\"י אמצעו'הכלי' כלל:) <b>אך<\/b> הענין כמ\"ש כי אל דעות ה' שיש ב' בחי' בדעת דעת עליון וד\"ת. ד\"ע הוא בחי' מקיף וסוכ\"ע היינו כי יש בחי' דעת שיודע ורואה הכל רק שהדעת הוא בבחי' מקיף דהיינו שאינו מתפשט בהמדו' להיות התפעלות מהדבר שהוא יודע או רואה וכענין שנאמר לא הביט און ביעקב שאין הפי' שלא הביט כלל אלא כמ\"ש וירא און ולא התבונן וכמ\"ש אם צדקת מה תתן לו וע\"ז נאמר טהור עינים מראות ברע שאין ראיתו הרע עושה רושם והתפעלות כלל כי שממית בידים תתפש ומשם מקור הסליחה והרחמים שאין מגיע שם שום פגם והוא למעלה מהכלים דע\"ס. רק הפגם והשכר והעונש הוא נמשך ע\"י הדעת המתפשט ונמשך במדות ונק' דעת תחתון והוא המתלבש בבחי' ממכ\"ע היינו בכלים דע\"ס דאבי\"ע ולכן ידיעה זו היא ע\"י בחי' עיני ה' שהם הכלים והמדות שעי\"ז נמשך ההתפעלות שכר ועונש שהפגם מגיע בהכלים דייקא משא\"כ ע\"י הידיעה שבדעת העליון שלא ע\"י הכלים דע\"ס אע\"פ שהכל גלוי וידוע לא נמשך מזה התפעלות כו'."],[21,"ותדע שכן הוא מענין ידיעה ובחירה שאין הידיעה שהשי\"ת יודע שזה יהיה צדיק או רשע מכרחת את הבחירה כלל. ואיך הוא. אלא לפי שידיעה זו שהש\"י יודע הכל מקודם אשר נעשה זהו בבחי' דעת עליון שלא ע\"י הכלים דע\"ס דהא עיני ה' משוטטים לראות המעשה שכבר נעשה שזה נראה לבחי' המלאכים והכלים דבי\"ע שנעשה עי\"ז פגם וכתם בהמלאך כו' וכנ\"ל משא\"כ הידיעה שהקב\"ה יודע העתיד ומעשה האדם קודם שנעשה אינו על ידם כלל כ\"א ידיעה זו היא במקום גבוה מאד בחי' דעת עליון ולהיות דעת זה בחי' מקיף אינו מכריח את הבחירה שאין האדם מתפעל מזה כמו שלא נמשך מדעת זה התפעלות אפי' בהמדות עליונים חו\"ג להיות מזה שכר ועונש כנ\"ל."],[21,"ושיהי' שכר ועונש זהו דוקא ע\"י דעת תחתון שע\"י הכלים והעינים. ועיין בפרדס ש\"ד פ\"ט בענין ידיעה ובחירה שכ' כי יש חילוק בידיעה קודם שיחטא האדם ⟦טו,ב⟧אעפ\"י שעתיד לחטוא. לאחר שחטא כו' ע\"ש."],[21,"ולפמ\"ש יובן כי הידיעה קודם שיחטא זהו בבחי' דעת עליון וכנ\"ל. וז\"ש בפ' שמות וירא אלקים את בנ\"י וידע אלקים פי' לא שנתחדש' הידיעה אלא שמקודם היה בדעת עליון שלא נמשך מזה התפעלות להיות עונש לפרעה ושכר לישראל וע\"י וירא אלהים ע\"י בחי' עיני ה' לראות המעשה כשכבר נעשה בפועל עי\"ז וידע אלקים שנמשך בחי' הדעת תחתון המתפשט במדות להיות שכר ועונש."],[21,"והנה השגחה זו מבחי' דעת עליון ע\"ז נאמר עין ה' אל יראיו וכתיב עין בעין נראה כדפי' באד\"ר דף ק\"ל ע\"א וע\"ש דיוסף הצדיק זכה לזה וזהו בן פורת עלי עין וזכה לזה ע\"י ויכלכל יוסף וזהו טוב עין הוא יבורך כי נתן מלחמו לדל ע\"ש. ומזה יובן דבעון סדום שפגמו בזה ע\"כ נמנע מהם גלוי בחי' עליונה זו הממתיק כל הדינים בחי' ורב חסד כו':"],[21,"(ע\"כ הגה\"ה):"],[21,"<b>והנה<\/b> בזוהר בסבא דמשפטים דק\"ז ע\"א פי' מ\"ש עיניו משוטטות אלין נוקבין ומ\"ש המה משוטטים אלין דכורין וכ\"ה בזוהר ויחי דרמ\"א סע\"א דפי' משוטטים הם בתקוני שכינתא לתתא כו' היינו כי יש מלאכים שהם מז\"א ויש מלאכים שהם ממלכות כמ\"ש הרח\"ו עמ\"ש בזוהר ר\"פ שמות דף ד' ע\"א בענין איש וביתו באו וז\"ל נ\"ב ת\"ת ומלכות ור\"ל המלאכים שמן הז\"א והמלאכים שמן המל' עכ\"ל המק\"מ שם."],[21,"והמלאכים שהם בתקוני שכינתא היא בחי' מלכות דאצי' נק' נוקבין וכמש\"ש בזוהר ד' רמ\"ז ע\"א בפי' בנות צעדה למיהוי עלי שור. בנות צעדה. צעדות מיבעי לי' אלא ההוא עין דכתיב לעילא ומאן איהו עין משפט כו' ואיהו עין צעדה ופסעת למיטל בנות לתקונהא והיינו בנות צעדה ולא בנים פי' שההשגחה הנמשכת ע\"י הע\"ס דמלכות דאצי' שהיא בחי' עין משפט ע\"ש מלך במשפט יעמיד ארץ הוא נמשך ומתלבש בהמלאכים הנקראים בנות שהם בחי' נוקבין."],[21,"וזהו בנות צעדה שהמל' צועדת על הבנות עלי שור לראות ולהשגיח מעשה התחתונים וע\"ז נאמר עיניו משוטטות לשון נוקבא. וזהו ענין הכצעקתה הבאה אלי. לשון נקבה שהיא בחי' מלכות שנק' דינא דמלכותא והוא העלאת הפגם ע\"י המלאכים שמבחי' מל' והכלים דע\"ס דבחי' מל' הבאה אלי לאא\"ס ב\"ה המלובש בע\"ס דאצי'."],[21,"ועז\"נ ארדה נא ואראה ע\"י מדת החסד וכנודע שז\"א רובו חסדים אנפוי דמלכא נהירין שהוא מ\"ש עיני ה' הם משוטטים ל' זכר שהם בחי' דכורין שהוא בחי' חסד ואראה הכצעקתה כו' שאולי ע\"י מדת החסד ימצא להם זכות."],[21,"וכמבואר באדר\"ז דרצ\"ג ע\"ב שבחי' ההשגחה ע\"י בחי' עיניו משוטטות ל' נוקבא הוא בחי' דין וההשגחה שע\"י בחי' עיני ה' המה משוטטים הוא בחי' רחמים כו' ע\"ש. והענין שהוא עד\"מ כמ\"ש ושפטו העדה והצילו העדה. עדה שופטת ועדה מצלת. לפי שבכל דבר יוכל ללמד זכות וחובה וע\"כ ארז\"ל פסילנא לי' לצורבא מרבנן לדינא דחביב עלי כגופאי ואין אדם רואה חוב לעצמו הרי אע\"פ שהוא חייב באמת אינו רואה עליו חובה שמחמת קירוב הדעת והחביבות מוצא מקום ללמד זכות משא\"כ למי שאינו חביב עליו כ\"כ הי' מלמד חובה וכמ\"ש וכל יצר מחשבות לבו רק רע כו' ועי\"ז נמשך ויאמר ה' אמחה את האדם כו' הרי מחמת זה שיצר מחשבות לבו רק רע נמשך ללמד חובה ואח\"כ בפ' נח כתיב ויאמר ה' אל לבו לא אוסיף לקלל עוד את האדמה בעבור האדם כי יצר לב האדם רע מנעוריו הרי שמסברא זו עצמה שיצר לב האדם רע מצא ללמד זכות שלא יוסיף לקלל את האדמה בעבור האדם והיינו לפי שהי' התגלות מדת החסד ע\"י וירח ה' את ריח הניחוח שבקרבן שהקריב נח המשיך גילוי מדת החסד ללמד זכות בזו הסברא עצמה שנמשך תחלה ללמד חובה ע\"י מדה\"ד. וזהו ענין החילוק בין ב' בחינות השגחות הנ\"ל ⟦טו,ג⟧(ועמ\"ש במ\"א ע\"פ לעשות הישר בעיני ה' אלקיך). וזהו פי' ארדה נא. כי צעקתה היא הבאה מלמטה למעלה שהוא בחי' גבורות ואו\"ח ולזה נאמר ארדה נא לשון ירידה הוא מלמעלה למטה דהיינו בחי' או\"י שהוא בחי' חסד להשגיח במדת החסד ללמד זכות. ואראה הכצעקתה הבאה אלי עשו דהיינו אם עוונם גדול מנשוא כ\"כ עד שגם ע\"פ החסד לא יוכל למצוא זכות אז כלה. ואם לא. פי' אולי ע\"י החסד יוכל ללמד זכות כו'. וז\"ש במדרש ארדה נא ממדה\"ר למדה\"ד ובזוהר דק\"ה ע\"ב ארדה נא מדרגא דרחמי לדרגא דדינא ר\"ל להמשיך רחמים ממדה\"ר אל בחי' מדה\"ד ואראה כו'."],[21,"והנה רש\"י פי' בחומש ארדה נא למד לדיינים שלא יפסקו דיני נפשות אלא בראיה. והענין דאיתא בת\"ז ואלין עשר ספירן אינון אזלין כסדרן חד אריך וחד קציר וחד בינוני. פי' כי ע\"ס נחלקי' לג' קוין קו הימין חח\"נ נק' חד אריך כי ⟦טו,ד⟧החסד נמשך ומתפשט יותר ולכן גמ\"ח בין לעניים בין לעשירים הרי שהחסד מתפשט יותר מהרחמים שעל העשיר אין שייך רחמנות כ\"א על העני. וקו השמאל בג\"ה נק' חד קציר שאינו נמשך כ\"א למי שהגון ביותר. וקו האמצעי נק' בינוני שמרחם על מי שנופל רחמנות."],[21,"והנה יש ראיה ושמיעה הראיה נמשך מבחי' חכמה קו הימין ושמיעה מבינה קו השמאל. וכנודע מענין ראובן ושמעון ולכן הראי' היא מלמעלה למטה והשמיעה ממטה למעלה שהאותיות מתעלים ונכנסים לאוזן השומע ולזה ג\"כ הראי' נשפלת למטה יותר מהשמיעה שרואה דבר גשמי משא\"כ השמיעה היא רק קול ודבור כי הראי' היא מבחי' חד אריך וכנודע שיסוד אבא אריך כו'. וזהו מ\"ש ארדה נא ואראה כי הכצעקתה הבאה זהו כמו בחי' שמיעה שמבחי' בינה ולכן היא הבאה מלמטה למעלה והוא בחי' קו השמאל אבל ארדה נא ואראה בבחי' ראיה שהוא בחי' חסדים כו':"],[22,"(ענין שדה המכפלה)"],[22,"⟦טו,ג⟧<b>יגלה<\/b> לן טעמיה כו'. הנה מילוי ה' היא בה' אחרת והיא בחי' כפילא כנודע מענין מערת המכפלה שהיא ה' אחרונה דשם ב\"ן כו'. והענין יובן בהקדים להבין ענין האכילה כי הנה עיקר האכילה להיות כי מן המאכל נעשה חלב ודם והדם הוא הנפש וחיות האדם שמקבל הכבד הדם מן המאכל ושולח ללב ולמוח דתלת שליטין אינון בעלמא כבדא ולבא ומוחא כו'."],[22,"ועי\"ז מתעלה המאכל שנעשה ממנו לב ומוח האדם ועי\"ז מתחזק לבו ומוחו בעבודת ה' שבלבו בהתלהבו' כרשפי אש שנעשה בכח האכילה שבלא אכילה הי' מתחלש כו'. וגם מוחו נעשה חזק להתבונן בגדולת ה' כו' וזהו ענין בירור שמן המאכל נעשה אדם. אך כ\"ז הוא בימות החול אבל בשבת בורר אסור אלא האכילה היא יותר עליונה בבחי' המשכה מלמעלה וקראת לשבת ענג. אז תתענג על הוי\"ה. כי הנה כתיב אחור וקדם צרתני אחור למע\"ב כו' שהמאכל כמו שהוא למטה בירידתו בשבה\"כ הנה האדם הוא בבחי' קדם שהמאכל הוא מתברר ע\"י האדם אבל בשרשו למעלה הוא מעולם התהו לפני מלך מלך לבנ\"י אלא שאח\"כ וימלך וימת."],[22,"וימת וימלך כו'. אך מ\"מ נראה ששרשו יותר גבוה מהאדם שהרי המאכל הוא המחי' את האדם. והאדם הוא מקבל החיות מן המאכל לפי שהוא בבחי' אחור למע\"ב כו' ובשבת שהוא זמן עליית העולמות מתעלה המאכל כמו שהוא בשרשו ונמשך ממנו חיות להנפש מלמעלה למטה ע\"י י\"ב לחמים כו' וזהו ענין צדיק אוכל לשובע נפשו כי יש ב' אכילות הא' הוא לשובע נפשו."],[22,"והב' הוא ובטן רשעים תחסר. לשובע נפשו הוא חיות הנפש הבאה מלמעלה. ובטן רשעים כו' היינו כי רשעים הם החיצונים וע\"י האכילה מבררים מהם חיל בלע ויקיאנו כי בכל מאכל יש תאוה שהוא שרש הקליפה וע\"י שנכלל בגוף האדם ונעשה ממנו דם הנשלח ללב ומוח מתהפך לטוב בקדושה ע\"י חיזוק הלב ומוח בעבודת ה' ועי\"ז לוקח ממנו החיות שבזלעו\"ז וזהו ובטן רשעים תחסר שנחסר החיות שבלעו. ומבטנו יורישנו אל."],[22,"והנה האכילה שבחול שהיא בבחי' בירור הוא להיות ובטן רשעים תחסר. אבל האכילה שבשבת היא המשכה מלמעלה לשובע נפשו מחמת המאכל כמו שהוא בשרשו למעלה קודם שנפל בשבה\"כ שאין בו בירור."],[22,"וכמ\"ש בזוהר פרש שבתכם לא קאמר שמה שנעשה מלמטה למעלה ע\"י בירור כמו בימות החול יש בו פרש שהוא פסולת שהמובחר שולח ללב ולמוח והפסולת יורד למטה בקרביים ⟦טו,ד⟧ובני מעיים כו' וזהו הבירור אבל בשבת שהוא נעשה מלמעלה למטה אין בו פסולת כלל כי הפסולת הוא מעה\"ד טו\"ר ולמטה נעשה טו\"ר בכל הבחי' ע\"י אכילת אדה\"ר מעה\"ד טו\"ר וגם בכל אדם יש תערובת טו\"ר כו' רק שאינו שוה בכל נפש יש שטוב שלו מרובה כו' וכן יש שטוב שלו הוא בבחי' זו כו' אבל בשבת אז תתענג על ה' למעלה מעה\"ד ולא יגורך רע כלל. רק ביו\"ט כתיב פרש חגיכם לפי שביו\"ט יש בו קצת בירור שהרי הותרה בו מלאכת אוכל נפש כאפיה ובישול כו' ואינו אסור רק קצירה וזריעה וחרישה כו' ולפי שהותרו קצת מלאכות באוכל נפש יש בו בירור ושייך פסולת והתקון הוא למחדי למסכני. כי שעת שמחה היא לשמח את הכל וכמ\"ש ושמחת בחגך אתה והלוי והגר כו' לפי שהשמחה היא בחי' המתקת הדינין וצריך לשמח את כולם שיהיו כולם נכללים בבחי' שמחה."],[22,"וכנודע ממי שהוא בשעת שמחה שאז רוצה שיהיו כולם שמחים שבזה נמתק הדין מאחר שמשוה את כולם. אבל מאן דלא יהיב למסכני כו' אין הדין נמתק ונשאר הפרש ולכן העונש הוא מדה כנגד מדה שנותנין לו הפרש כי הוא גרם שישאר פסולת הפרש בעבור שלא המתיק הדין. וזהו ביו\"ט אבל בשבת אע\"ג דלא יהיב למסכני אין עונשו רב כי בשבת אין פרש כלל לפי שהוא רק בחי' המשכה שמלמעלה דלא יגורך רע כלל."],[22,"והנה המשכה זו היא בב' בחי' כפילא וקלישא. פי' קלישא היא המשכת יודי\"ן ווי\"ן שמיו\"ד נעשה וי\"ו שהיו\"ד עצמה נמשכה ונעשית וי\"ו. כי לפי שהיו\"ד הוא בחי' צמצום לכן יכול להיות ממנה המשכה בבחי' וי\"ו מן היו\"ד עצמה אבל הה' שהיא התפשטות אורך ורוחב."],[22,"ואין התפשטו' אורך ורוחב שלמעלה יכולה להתגלות למטה כמו שהוא למעלה בבחי' אורך ורוחב עד אין קץ כו' אלא ההמשכה היא בבחי' ה' אחרת למטה והיא בחי' המילוי של ה' דהיינו כח הה' שהי' בהעלם למעלה. כי לעולם המילוי הוא מה שבהעלם ומה שבהעלם למעלה יצא מההעלם אל הגילוי למטה."],[22,"והיינו בחי' כפיל' שהיא בחי' מילוי ההי\"ן כנודע מענין המכפלה. אך כ\"ז הוא שאנו מקבלים ההשפעה ע\"י י\"ב לחמים בזמן הזה אבל לע\"ל יגלה לן טעמיה דבתריסר נהמי כו' ואזי לא יהיה בחי' כפילא כו' רק הה' עצמה שלמעלה יהי' לה גילוי למטה ג\"כ ע\"י כי יגלה לן טעמיה כו' וכמ\"ש ביום ההוא יהיה כו':"],[22,"⟦טז,א⟧<b>שייך<\/b> לפסוק ואברהם זקן בא בימים"],[22,"<b>להבין<\/b> ענין משארז\"ל יפה שעה אחת בתשובה ומע\"ט בעוה\"ז מכל חיי עוה\"ב. וצריך להבין והלא תכלית תשובה ומע\"ט הוא שמהם נעשו לבושין לנשמה שתוכל ליהנות מזיו השכינה בעוה\"ב כמאמר הזוהר ע\"פ ואברהם זקן בא בימים באינון יומין עילאין כו' ווי ליה לההוא גברא דגרע יומין לעילא דכד בעיין לאלבשא ליה באינון יומין יומא דפגם חסרא ליה מההוא לבושא כנ\"ל."],[22,"והענין דהנה ענין זיו השכינה בעוה\"ב אינו כמו התפשטות חיות אלקות בתוך העולמות. כמ\"ש ואתה מחיה את כולם שהחיות אלקות המתלבש תוך עלמין אינו מושג ונראה. כמשל התפשטות החיות של הנשמה תוך הגוף בהתחלקות האברים ובודאי בהחיות רוחני לא שייך כלל שיהיה בו ג\"כ התחלקות החיות לחלקים כי אין ברוחניות שום תמונה וציור."],[22,"והנה התפעלות החיות באברים ניכר ונראה. אבל מהות ועצמות החיות אינו נראה וניכר כלל. כמו כן חיות אלקות המחיה כל העולמות בע\"ג ותכלית בודאי אין בהחיות הרוחני בחי' גבול ותכלית ד\"מ חיות המחיה את עיגול כדור השמים בודאי לא יתכן לומר שגם החיות הרוחני הוא בתמונת עיגול כנ\"ל רק שהתפשטות החיות הוא לפי תמונת כלי המקבל החיות ואע\"פ שהחיות מתלבש לתוכו מ\"מ החיות עצמו אינו בגדר מקום וגבול:"],[22,"<b>ובזה<\/b> יובן דכתיב מכה\"כ ותרגומו זיו יקריה שהוא רק זיו והתפשטות הארה בלבד. וכתיב את השמים ואת הארץ אני מלא. והענין ששניהם אמת כנ\"ל וזשארז\"ל במקום שאתה מוצא גדולתו של הקב\"ה שם אתה מוצא ענותנותו כו'. דהיינו לא כמו שהעולם סוברים שגדולת הבורא נק' מה שהוא ית' מחיה כל העולמות שאדרבה זו היא ירידה אצלו ית' שמשפיל עצמו ומתלבש תוך כ\"ע להחיותם ולקיימם."],[22,"ומ\"ש ואתה מחיה את כלם אינו שבח בבחי' גדולתו ית' שלגדולתו אין חקר ולתבונתו אין מספר אלא השבח הוא בבחי' ענוה שלו שיוכל להשפיל עצמו וכו'. אבל ענין עוה\"ב שנהנין מזיו השכינה הוא השגת מהות ועצמות התפשטות החיות אלקות בבחי' גילוי:"],[22,"<b>ועתה<\/b> צריך להבין איך תוכל הנשמה שהיא בחינת נברא יש ודבר בפ\"ע להשיג מהות ועצמות אלקות שאינו בבחי' השגה וגבול ואף שהנשמה היא חלק אלוה ממעל הוא ד\"מ כענין טפת הזרע שנמשכה מן המוח שלא יתכן לומר שגם עודנה במוחו היתה טפת זרע גשמית שא\"כ הי' נחסר מהמוח כו'. אך שבאמת התחלת המשכתה מן המוח הוא כח רוחני לבד אלא שאח\"כ בהשתלשלות ירידתה דרך חוט השדרה נשתנית ונעשית טפה גשמית. כן עד\"מ הנשמה עיקר שרשה מבחי' אלקות ממש רק שנשתלשלה בירידתה להיות בחי' נברא יש ודבר בפ\"ע כו'."],[22,"וא\"כ איך תוכל להשיג מהות ועצמות אלקות. והענין דהנה כתיב ויבא משה בתוך הענן ויהי שם ארבעים יום וארבעים לילה לחם לא אכל כו'. והי' גופו הגשמי ניזון ממזון רוחני לבד כמ\"ש לחם אבירים אכל איש וכו' ממש כמו המלאכים ואיך יוכל להיות זה שגשמי יקבל מזון וחיות מרוחני שמובדלים זמ\"ז בתכלית. אך זהו ענין הענן שהיה משה ע\"ה מתכסה בו דהיינו שהיה הענן שרשו ממדרגת אלקות מאד נעלה. אך שנשתלשל ונתגשם להיות לבוש למשה ע\"ה שע\"י יוכל להשיג אלקות והיה לו למזון כמשל אדם הרואה ומסתכל באור צח דרך יריעה. כמו כן תורה ומצות מעשיות ששרשם מרצה\"ע מחכמתו ית' שהם מיוחדים בו ית' הוא חכים כו' שהם למעלה מזיו השכינה שהוא רק התפשטות החיות כו' ונשתלשלו ונתפשטו ונתלבשו בעניני זה העולם הגשמי כמו קלף של תפלין וצמר של ציצית וצדקה כו' כשאדם ⟦טז,ב⟧עוסק בתורה ובמצות נעשה לנשמתו לבושים שנתלבש בהם בגעה\"ע שע\"י תוכל הנשמה שהיא בחי' נברא להשיג זיו השכינה עצמות אלקות. וזהו יפה שעה אחת בתשובה ומע\"ט שהם שרשם מרצה\"ע ב\"ה. מכל חיי עוה\"ב שהוא רק זיו השכינה כידוע מ\"מ הם נקראים לבושים שע\"י תוכל להשיג זיו השכינה וד\"ל:"],[22,"<b>ועתה<\/b> צריך להבין ענין אוי\"ר שהם רק גדפין לבד להגביה עיקר הדבר שהם תורה ומע\"ט. ולהבין מהות האהבה מה היא. הנה בק\"ש צריך שימליכוהו למעלה ולמטה ולד' רוחות העולם. פי' דכתיב מכה\"כ ותרגומו זיו יקריה שהוא רק זיו והתפשטות והארה בלבד המתלבשת תוך כ\"ע וכתיב את השמים ואת הארץ אני מלא בבחי' עצמות אלקות שאינו נתפס תוך מדה וגבול. והענין ששניהם אמת כו'. כמשל בטול זיו השמש במקור השמש עצמה כידוע שבאמת עצמות אלקות מלא כל הארץ. אך מה שהוא מתפשט תוך כלי וגבול הוא בטל ונכלל במהו\"ע אלקות כו'."],[22,"והנה כשיתבונן אדם היטב בזה בפסוד\"ז ובק\"ש איך שבאמת הוא כן שהעולמות בטלים במקור חיותם רק מפני שהאדם הוא בכלי גשמי הגוף שהוא משכא דחויא שמתגדל ומתרבה מגשמיות המסתיר ומעלים שלא יוכל לראות בעיני ראי' חושית אזי יתעורר בלב תשוקה שיהי' קשור בהתבוננות זו כל היום ולא יפרד ממש כלל."],[22,"וזהו קבלת מ\"ש בפסוק ראשון ואהבת שיהי' הוי' אלקיך שיהא תמיד קשור בהתבוננות זו ביטול העולמות להמחי' ומהווה אותם רק מפני היות כי גופו הגשמי לא יוכל לקבל ביטול אמתי הנ\"ל יגמור בדעתו בק\"ש ענין לימוד התורה באמרו ודברת בם. דהיינו שנפשו האלקית בעסקו בתורה נעשה יחוד אמתי עם התורה ואורייתא וקוב\"ה כולא חד ממש כי אורייתא מח\"ע נפקת ונתלבשה בעניני זה העולם וכשאדם מלביש נפשו האלקית בעניני לימוד התורה שבזה העולם אזי גם שרש נפשו למעלה מתלבש ג\"כ בתורה שלמעלה עד רום המעלות ונעשה שם יחוד גמור. וזהו הקב\"ה יושב ושונה כנגדו כנ\"ל. וזהו ה' צלך פי' כמו צל."],[22,"והנה כתיב אני הוי' אלהיכם אשר הוצאתי אתכם מארץ מצרים. פי' שלא יאמר האדם בדרך שפלות האיך יגיע למדרגת היחוד בתורה ותפלה מאחר שהוא עדיין אינו סור מרע גמור כו' והוא עדיין בשלימות אצלו. זאת ישיב אל לבו שהשם הוא המוציא אותו מארץ מצרים. פי' שהוא מבדיל ומפריש בנפשו הטוב מן הרע הנפש אלקית מנה\"ב כשהוא עדיין לא עשה רע בפו\"מ."],[22,"ואפי' רשע גמור הוא ממשיך בנפשו האלקית בעסקו בתורה רק שעליו נאמר ולרשע אמר אלקים מה לך לספר חוקי. פי' שאין תועלת לנפשו האלקי' מפני שעליו נאמר ותשלך דברי אחריך שלא יוכל להמשיך בתוך פנימיותו וד\"ל:"],[22,"<b>והנה<\/b> בענין ברכות. ברוך אתה הוי' פי' ברוך הוא המשכה ורבוי שיהי' הוי' שהוא בחי' צמצום והתפשטות כו' יהי' בחי' אתה לנוכח התגלות כו'. אך להיות כי הגוף הוא המסתיר ומחשיך רק לע\"ל יהיה התגלות אלקות וראו כל בשר ויהי' בבחי' ביטול אבל עכשיו צריך להראות עכ\"פ ענין הביטול בחיצוניות בכריעה והשתחוא' בראש הכורע כורע בברוך. וענין רופא חולים וגואל ישראל ומברך השנים הם כלים לבחי' המשכה והתגלות אלקות כו' והכורע צריך שיראה איסר כנגד לבו. פי' עיקר המשכה יהי' במוח עד שיתפשט ג\"כ בלבו אפי' מעט היינו בחי' איסר (ועמ\"ש לקמן בפי' אוסרי לגפן) שהוא בחי' חפץ כדכתי' הודו על ארץ ושמים אפי' בבחי' זיו והתפשטות החיות המלובש תוך כ\"ע ותכלית הכוונה להיות לו דירה בתחתונים וסוף מעשה במחשבה תחלה נעוץ סופן בתחלתן ולכן ארז\"ל ארץ נבראת תחלה כו':"],[23,"⟦טז,ג⟧לשון אדמו\"ר נ\"ע בעצמו"],[23,"<b>עיין<\/b> ע\"ח שמ\"ט פ\"ה נמצא אלו לבושים הנז' פ' ויחי אין פי' שנעשו מחדש ע\"י תורה ומצות אמנם מתבררים כו'. וע' שכ\"ו ספ\"א רק להמשיך אור לתקנם כו' דוגמת גלות השכינה כו' ומ\"ש בשער ל\"ט שנר\"נ מתבררים ע\"י התפלות היינו בעלייתן מן הקליפות להיות מ\"נ בנוקבא דז\"א אבל ירידתן משם לעוה\"ז בגוף החומרי לקיים תומ\"צ מעשיות ולא תפלה לבדה דרבנן היא דוגמת גלות השכינה ואינו אלא לברר ולתקן הלבושים שלהם בעצמם ומשום הכי הוא חיוב יותר על הנפש רוח נשמה לברר ולתקן לבושיהם שאי אפשר על ידי אחרים (משא\"כ להעלות הנר\"נ מהקליפות למ\"נ לנוקבא דז\"א שנעשה ע\"י אחרים) כמ\"ש בגלגולים פ\"א ע\"ש. וכפי גודל אותה המצוה או זריזות כו' ומעלה אותה עד הנקבה העליונה כו'. וכ\"כ בע\"ח של\"ט דרוש י\"א סי' ז' או המצוה כו' וכ\"כ בפע\"ח ש\"א פ\"ו כי ע\"י המצות ותפלות כו'."],[23,"ומש\"ש ובפרט מן התפלות כי הם עיקר ושרש כו' והיינו כמ\"ש בע\"ח ש\"מ דרוש ג' שהתפלה בפנימית והמצוה בחיצוניות אע\"פ שיש בהן בחי' מוחין כו' ע\"ש והלכך זיוג זו\"נ הנעשה ע\"י מ\"נ מהמצות כמ\"ש בטעמי המצות בסוף ההקדמה הוא בחיצוניות במצות מעשיות."],[23,"ומ\"ש בע\"ח של\"ט דרוש א' וב' על ידי תפלה דוקא היינו מ\"ן עצמן דנוקבא שנפלו לקליפות בחטא אדה\"ר ולא הנשמות שהיו כבר באדה\"ר אלא אותן שלא נכללו בו והן בחי' בי\"ע שלפני החטא כמ\"ש בגלגולים פ\"ז אבל אותן שנכללו בו מהם ממשיכים רוב בנ\"א כמעט כולם כמ\"ש פי\"ד והיינו ע\"י הזיוג שהוא מצות פו\"ר כמש\"ש פ\"ב."],[23,"וע\"ש אחר ס\"פ ל\"ה בקשר החברים שכל נשמה בעלייתה מהקליפות צ\"ל לפחות מ' יום במלכות והיינו שעולה שם למ\"נ ע\"י מצות הזיוג ואף מי שאינו מתכוין למצוה יוכל להמשיך חיות מלמעלה כמ\"ש בלק\"ת ע\"פ כי לא על הלחם לבדו יחיה כו'. כמו שהלחם מחי' גם כשאוכל בלא ברכה כו' ע\"ש. הנה תקון וברור הוא ע\"י מ\"ד דוקא כי בהדכר לבדו יש בו כח לברר כמ\"ש בפע\"ח ש\"א פ\"ו וכן בירור הלבושים ע\"י המצות הוא במ\"ד דז\"א והיינו המשכת האור דלעילא והן הם ה\"ח דז\"א שכל רמ\"ח מ\"ע תלויים בהם כמ\"ש בטעמי מצות שם. וע' ע\"ח שכ\"ו (בע\"ח דפוס שקלאוו שער כ\"ה) פ\"א ופ\"ג שלבושים אלו הם צלם דאימא פנימי המלביש לנר\"נ וגם המקיף הנק' חשמל נתברר ונתקן מק\"נ להסמוכה לו וכמ\"ש שער מ\"ט ספ\"ב הטוב שלו נזדכך כו' ונתחבר עם החשמל הפנימי כו' ע\"ש."],[23,"וע\"ש שמ\"ב פ\"ד וזאת הבחי' נקרא חשמל שהוא צלם הבל דגרמי שבעור כו' ע\"ש. ומ\"ש בשער כ\"ו פ\"א שצלם הפנימי הוא הבל דגרמי והוא חותם ולבוש נה\"י דאו\"א כמ\"ש בפ\"ב שם שניהם אור א' הם זה פנימי וזה מקיף כמ\"ש בפ\"ב שם. ועיין ש' ל\"ט דרוש י\"ב וזה לבוש הנק' כו' וכן כו' ולבוש זה כו' העלאת מ\"נ כו' גדול כו' וע' שער החשמל פ\"א ונק' ק\"נ ונק' חשמל כו' ור\"ל כמש\"ש בס\"פ כל החשמלים הוא בחי' טוב שבק\"נ כו' וע' מק\"מ בראשית (דף ק\"ב סוף ע\"ב) שג' חשמלים נפלו בנגה ע\"י חטא אדה\"ר וע' שער החשמל פ\"א כפי כניסת הכלים דתבונה בפנים כן בחי' האור שלה מלובש מבחוץ כו' ע\"ש שכל התקון הוא לדחות החיצוני' ע\"י אור הבינה מבפנים ⟦טז,ד⟧ומבחוץ (וקרוב לומר שמבפנים הוא ע\"י מצות שבדבור ומבחוץ ע\"י מצות מעשיות שהחיצוני' נק' מקיף לגבי פנימי' כמ\"ש בע\"ח ספ\"ג גבי ח\"ש). והשתא א\"ש הא דשכר המצות הוא לבוש לנשמה מאחר שנמשך מאימא שהוא עוה\"ב וכמו הלחם שעליו יחי' האדם אף שגם בו מלובש מוצא פי הוי' אלא שבלחם ושארי מזונות נמשך מחיצוניות אימא שלמעלה מז\"א הנק' אדם כמ\"ש בכוונות עיוה\"כ. אך באמת הלבוש אינו העוה\"ב אלא שעי\"ז יוכל לסבול וליהנות מאור אימא שהוא עוה\"ב מאחר שמלובש בלבוש נה\"י שלה (פנימי ומקיף אור פנימי למזון ומקיף ללבוש) דכמו שהעליוני' כהמלאכים אינם יכולים לירד למטה לעוה\"ז בלי לבוש תחתון כך אין התחתונים יכולים לעלות למעלה בלי לבוש עליון כמ\"ש בזוהר פקודי (דף רכ\"ט ע\"א וע\"ב) וכ\"כ בהדיא בויקהל (דף ר\"י סע\"ב) ואלמלי ההוא לבושא לא יכלי למסבל כו' ומש\"ה מי שלבושיו חסרים לפי שלא תקן כל הרע ע\"י המצות צ\"ל בגיהנם לתקן הרע תחלה כמ\"ש בזוהר ויחי (דף רכ\"ד) ובלא\"ה א\"א להיות כלל בעוה\"ב בלבוש חסר כמו שא\"א למלאך לירד לעוה\"ז בלי לבוש שלם. ומ\"ש הסבא (דף צ\"ח ע\"ב) ענין התלבשות בנפש וכן התלבשות הנשמה ברוח (דף צ\"ט ע\"ב) היינו לירד למטה ממדריגותם כמ\"ש בזוהר הרקיע שם (דף פ\"ג ע\"א) בשם הרח\"ו ז\"ל. והנה געה\"ע הוא מבריאה. וא\"ש הא דתנן יפה שעה א' כו' מפני שהזיוג זו\"נ הוא באצי' והמצות ממשיכות מ\"ד דאצי' ושרשן ממו\"ס דא\"א המאיר י\"ג חיוורתא דגלגלתא שרש תרי\"ג מצות ואף מי שאין לו אלא נפש דעשי' ה\"ז מעלה מ\"ן למל' דיצי' במצותיו ושם הרוחות של הצדיקים מעלים המ\"נ שלו ושלהם עד מל' דבריאה ושם הנשמות של כל הצדיקים מעלים כל המ\"נ עד מל' דאצי' כמ\"ש בע\"ח של\"ט דרוש י\"א פ\"ז. כי אין שום בירור אלא באצי' כי היא בחי' חכמה דכללות ובחכמה אתברירו והבירור הוא ע\"י זיווג ואין זיווג להוליד נשמות בבי\"ע כמ\"ש בשער מ\"ד פ\"ד ופ\"ה."],[23,"ואף שממצות מעשיות לא נעשה לבוש אלא לנפש דעשי' מ\"מ הזיווג הוא באצי' כי לכן יורדים בחול כלים דזו\"נ דאצי' בזו\"נ דבי\"ע כדי לברר בירורים למטה כל ו' ימי המעשה (יורדת כלי זו\"נ דאצי' לעשי' הוא ליתן כח לנפש דעשי' להעלות מהקליפות כמ\"ש אשר שלט האדם באדם כו' רק שבסיוע התחתונים במצות שהיא אלקות שבנוגה וזה עולה שלא ע\"י נר\"נ דאדם אלא ע\"י בחי' אצי' ממש שבבי\"ע מעלים עד נוקבא דאצי' העליון ולכן ירדה אצי' בבי\"ע בימי החול וגם ליתן כח לנר\"נ דאדם להעלות מקליפות) כמ\"ש בע\"ח ש\"א פ\"י. ובשבת צ\"ע בעליות העולמות (ואפשר דר\"ל בבריאה יורדין יעקב ורחל בחול) ואפי' אוא\"ס ב\"ה נמשך שם כמ\"ש בע\"ח שמ\"ז פ\"ג ע\"ש (ובגלגולים פ\"ב שבחי' נפש דאצי' שבעשי' גדולה לאין קץ מנשמה דבריאה שבבריאה) וכן מ\"ש דציצית ביצירה ותפלין ש\"י בבריאה היינו שהתקון נעשה לדחות החצונים מג\"ת דיצי' וג\"ת דבריאה ע\"י המשכת האור דאצי' וכמו שבק\"ש נעשה זיוג או\"א דאצי' ונמשך בבריאה ולכך היא בישיבה משא\"כ בתפלת י\"ח ותדע מנט\"י שמתקנים ג\"ת דעשי' אף שהידים הם חג\"ת וכן הציצית להתעטף הראש עד החזה ותפלין ש\"י היא בחי' מוחין מקיפים וכולם מתקנים ג\"ת לבד דבי\"ע ואף שהם מצות ⟦יז,א⟧מעשיות מ\"מ ממשיכים מבחי' עשי' שבאצי' שהיא חיצוניות כמ\"ש בע\"ח ש\"מ דרוש ב' וציצי' קטן הוא בחי' עבור של חיצוניות והטלית יניקה ותש\"י מוחין דגדלות."],[23,"ועוד תדע מכוונות השמות בברכו' המצו' שהן בת\"ת דאצי' ולא דבי\"ע וכן במקרא שהוא בעשי' והכוונ' הוא בג' שמות ת\"ת דז\"א דאצי'. ולתורה ולנביאים בנ\"ה דז\"א דאצי'. ולכתובים ליסוד דז\"א דאצי' ולמשנה שהיא ביצי'."],[23,"והכונ' היא בשמות דכלי' אמצעי' דו\"ק דנוק' דז\"א דאצי' ולתלמוד הכונה בשמות דכלים חיצוני' דו\"ק דנוק' דז\"א דאצי' אף שהתלמוד בבריאה. והטעם מובן מ\"ש בפע\"ח דאיך אפשר דתושב\"כ בעשי' למטה משבע\"פ אלא כולם הם באצי' רק שהמקרא יורדת עד העשי' ומתלבשת שם."],[23,"והמשנה עד היצי' לבדה. והתלמוד עד הבריאה לבדה. והקבלה עד האצי' לבדה בלי לבוש. דהיינו למי שיודע להפשיטה מלבושיה עד בחי' אצי' א\"נ היא בחי' אצי' ממש שבעשי'. אך מאחר כי הכוונה בשם מ\"ה שהוא שם כלי פנימי דת\"ת דז\"א דאצי' והם אינם מלובשים בעשי' כלל מכלל שהן באצי' העליון ממש רק שהמקרא מלובשת בעשי' וקבלה אינה מלובשת כלל."],[23,"וכן המשנה והתלמוד הם באצי' העליון ומלובשים בבריאה ויצי' עליונה כי האדם כלול מכל העולמות ואף שהכוונה בעסק התורה היא בבריאה והתורה עצמה ביצי' וכן המצוה בלי כוונה בעשי' מ\"מ התלמוד עצמו הוא ביצי' שהוא בחי' רוח שבבריאה והמשנה עצמה בלי כוונה ביצי' שביצירה והכוונה נשמה לשתיהן כמ\"ש בע\"ח שער מ\"ט פ\"ה. ע\"ש היטב הדק דמוכח התם ג\"כ כמ\"ש שהתלמוד היא בבריאה עליונה אלא דהיינו דוקא כל מי שנשמתו בבריא' אבל לנפש דעשי' אפשר היא בריאה ממש שבעשי' וצ\"ע. אך זה אינו שאין לחלק בין נפש לנשמה אלא בכוונה שהנשמה כוונתה עולה למעלה יותר אבל לא בלימוד הפשוט עצמו בפשט התלמוד לבד:"],[24,"<b>ויצא יצחק לשוח בשדה כו'.<\/b> לבאר זה דהנה יש משנה וברייתא. וברייתא פי' המשנה כי המשנה הוא הכלל וברייתא היא הפרט של המשנה ואין בכלל אלא מה שבפרט. ולכאורה הברייתא היא למטה מן המשנה שנשתלשלה יותר למטה אבל האמת הוא שהברייתא גבוה יותר דסוף מעשה במחשבה תחלה. דהנה התורה נשתלשלה למטה אפי' בדבר שקר כגון זה אומר אני מצאתיה כו'."],[24,"ולפי הנראה היא ירידה למטה מאד ומ\"מ היא גבוה כי סוף מעשה כו'. וכמשל השפופרת הנכנס ראשון יוצא אחרון וכמו האדם שהוא סוף כל הנבראים והוא במעלה על כולם והכל נברא בעבורו ולכן נמצא העולם כולו באדם אחד להורות שהכל נברא בעבורו כי זה כל האדם."],[24,"וזהו מארז\"ל יפה שעה אחת כו'. דהנה בעה\"ב צדיקים יושבים כו' והוא רק בחי' אחוריים כמאמר וראית את אחורי כו' ⟦יז,ב⟧התענוג שמשיג האדם בעבודתו הוא בחינת אחוריים ופני אינו באפשרי להשיג כי לא יראני האדם וחי."],[24,"ועד\"ז גם הגלוי בג\"ע הוא רק בחי' זיו והארה לבד ולכן יפה שעה אחת כו' שהוא המעשה עצמה בלי תענוג ובלי שכל מכל חיי העוה\"ב דסוף מעשה במחשבה תחלה. וזהו גם כן ענין משנה וברייתא שהמשנה הוא כלל כמו ד' ציצית מעכבות וכן סוכה שהיא גבוה כו'."],[24,"ויש למצוא טעם לזה כענין תכלת דומה לים כו' וגבי סוכה יש טעם למען ידעו דורותיכם עד כ' אמה כו'. אבל הברייתא הוא פרט לבאר המשנה בכל דקדוקים ופרטים כמו סוכת גנב\"ך ורקב\"ש שאין טעם לדבר ונראה בחוש שהוא למעלה מהשכל והטעם וזהו אין בכלל אלא מה שבפרט שאין במשנה בכלל יותר מבפרט הברייתא ומה שלא נתגלה טעמה הוא יותר גבוה כי טעמי המצות לא נתגלו ולע\"ל אי\"ה יתגלו וזהו ר\"ש דריש טעמי דקראי שדרש שמה שנאמר בפסוק טעם של דבר לא זהו עיקר רק שיש טעם בזה גבוה יותר למעלה מהטעם. נמצא שבמצוה שאין משיג בה טעם הוא יותר גבוה ומה שמשיג טעם ותענוג הוא רק בחינת אחוריים ולא כמו שסוברים העולם שהעיקר הוא הלב שמשיג תענוג ועובד בהתלהבות ואינו כן האמת רק עיקר הוא המעשה בלי תענוג והלב אינו כ\"א סיוע בחינת גדפין."],[24,"והנה משנה נקרא עיר וברייתא בחי' שדה לשון בר חוץ לעיר ולכאורה העיר הוא עיקר שדרים בה בנ\"א. אך נראה מי הוא מחיה אותם. השדה שחוץ לעיר שמביאים משם התבוא'. כך הוא הברייתא מחיה המשנה ומבארת ההלכה יותר בפרט היאך לעשות כי התנאים מבלי עולם שמורים מתוך המשנה. וזהו ויצא יצחק לשוח בשדה הוא לשון דבור ושיחה ול' שחייה למטה מלשון ושח רום אנשים וכן כאשר יפרש השוחה לשחות (בישעיה כ\"ה) (ועמ\"ש בזה ע\"פ תבנה ותכונן עיר סיחון כו' ע\"ש) בשדה הוא בר. ולפנות ערב לפנות הערב והחשך. דהנה התורה נשתלשלה בחשך כמאמר במחשכים הושיבני זה תלמוד בבלי שנשתלשל למטה אפי' בשקר ולמה הוא כך כדי לפנות הערב והחשך ויהי אור כמאמר לעת ערב יהיה אור כמשל מי שרוצה לפנות איזה דבר צריך הוא לכנוס בתוכ' כדי לפנותה אבל לא שישאר בתוכה. גם מה שנשתלשלה התורה ונתלבשה בחשך טענות שקר הוא כדי לפנות החשך לאהפכא חשוכא לנהורא וכן העסק בתורה לדחות החשך והקושיות המסתיר על השכלת הדין האמת לאמתו ולמצא האמת גילוי רצון עליון ב\"ה וכמ\"ש ע\"פ והמשכילים יזהירו וגו' ע\"ש:"],[24,"<b>וזהו<\/b> ויצא יצחק לשוח. כי כדי לפנות הערב והחשך ולתקנו הוא ע\"י יצחק שהוא בחי' פחד ויראת ה' וכמאמר אם אין יראה אין חכמה כו'. (וע' בזוהר בראשית ד' כ\"א סע\"א). וזהו האומר אין לי אלא תורה אפי' תורה אין לו ונשאר בחשך אבל באמת כתיב ישת חשך סתרו שאף שהוא חשך מ\"מ הוא סתרו וזהו לפנות הערב והחשך ולעת ערב יהי אור והיינו ליבון הלכתא וגם זה פי' ברכו בתורה. (ועמ\"ש ע\"פ קול דודי וע\"פ ששים המה מלכות):"],[25,"⟦יז,א⟧<b>אלה תולדות יצחק וגו'.<\/b> כתיב שמאלו תחת לראשי וימינו תחבקני. שמאלו הוא בחי' יצחק ממטה למעלה. וימינו כו' הוא בחי' אברהם מלמעלה למטה. והנה מדת אברהם הוא הכנסת אורחים כו' ויצחק היה חופר בארות כו'. ולהבין זה הנה ⟦יז,ב⟧כתיב ואהבת. אשר לכאורה לא שייך בזה לשון צווי לאהוב כו'. אך הוא שבתחלה כתיב הוי' אחד כו'. ובהתבוננות ענין אחד איך שאין ערוך אליו כלל כו' הוי' אלקינו ואלקי אבותינו (שהוא בחי' צמצום) פי' שיתהווה בחי' אבותינו חו\"ב כו' אנת חכים כו' אשר ⟦יז,ג⟧אין ערוך כלל לגבי מהותו ית' אנת הוא חד כו' לכן צריך קודם בחי' אלקינו שהוא בחי' צמצום ואח\"כ ואלקי בחי' וא\"ו המשכה שיתהווה בחי' אבותינו ובהתבונן כ\"ז בוודאי כל איש ישראל יהיה חפצו ורצונו תמיד ליכלל בה' אחד ולא שירד למטה במקום חשך. אמנם זהו בחי' רצוא אבל צ\"ל אח\"כ בחי' שוב כדכתיב כיתרון האור מן החשך ורצונו ית' להיות לו דווקא דירה בתחתונים ולכן הצווי ואהבת הוא הפי' בהיפוך מלמעלה למטה."],[25,"וכמארז\"ל שיהא שם שמים מתאהב ע\"י. פי' להמשיך גילוי אור אלקותו מלמעלה למטה. וזהו מעשה אברהם הכנסת אורחים שנתן לערביים לאכול ואח\"כ אמר להם דעו למי מברכים כו' בכדי להיות גילוי אלקות למטה שגם הערביים יכירו גדולתו כו' כ\"ז הוא בחי' אברהם המשכה מלמעלה למטה. ויצחק הי' חופר בארות שהוא בחי' גילוי ממטה למעלה מהעלם לגילוי כמשל הבור אשר המים שם בהעלם וע\"י החפירה נגלו המים כו'."],[25,"והנה הגם שאברהם היה ג\"כ חופר בארות אבל כתיב ויסתמום פלשתים כו' ויצחק חפר אותן וקרא להם שמות כשמת אשר קרא להן אביו הראשון מלא והשני חסר לפי שע\"י חפירה דיצחק לא נפסק עוד נביעתם ונמשכים ונובעים הששה מדות שהן בחי' וי\"ו ע\"כ הוא שמות מלא בוי\"ו. אבל שמת דאברהם חסר וי\"ו לפי שסתמום פלשתים ויש לחיצונים יניקה מהם. לכן ע\"י חפירה דיצחק הוא שמות בוי\"ו (ועמ\"ש כה\"ג ע\"פ ששת ימים תאכל מצות כו' מלא וי\"ו) ולע\"ל כתיב כי אתה אבינו שעיקר הצחוק והשמחה יהיה מבחי' יצחק שהוא ממטה למעלה אשר בחי' זו אין קץ ותכלית כו' משא\"כ (אברהם) בבחי' ממעלה למטה יש לה גבול המשכה למטה ולכן באברהם כתיב ב\"פ אברהם אברהם הא' הוא המשכה שיתהווה בחי' חו\"ב דאצי' ואלקי אבותינו כנ\"ל. והמשכה ב' בבי\"ע. משא\"כ יצחק בחי' מלמטה למעלה בחי' אין קץ ותכלית והכל ירוממוך סלה. ומזה נתהווה עיקר הצחוק כי גמירי משמיא מיהב יהבי משקל לא שקלי כו' מיהב הוא בחי' השתלשלות מאין ליש כו'. אבל עבודת האדם הוא ההיפוך והוא להיות בטול היש לאין והוא בחי' יצחק צחוק ותענוג גדול כו':"],[25,"<b>והנה<\/b> כתיב באברהם קח נא את בנך כו' אשר אהבת את יצחק כו'. כי ידוע הטבע לאהוב ההיפוך כדכתיב מים קרים על נפש עיפה. וכמו\"כ להיפוך מי שקר לו מאד רוצה למים חמים."],[25,"ולכן אברהם שמדתו המשכה מלמעלה למטה אוהב ג\"כ ההיפוך בחי' יצחק מלמטה למעלה. היינו שבחי' יצחק הוא פחד יצחק שהוא בחי' יראה ובטול ולכן זה א\"א שימשיך אברהם למטה בחי' פחד יצחק הנ\"ל שבחינת בטול כזה א\"א לנבראים לקבל כי גם למעלה אמרו הושיט הקב\"ה אצבעו הקטנה ביניהם ושרפן ע\"י גילוי רב ומכ\"ש למטה בנבראים."],[25,"ולכן כתיב ויעקוד אותו על המזבח ממעל לעצים למעלה מבחינת עה\"ח ועה\"ד שם יוכל להתגלות בחי' פחד יצחק הנ\"ל. אמנם ביעקב כתיב ופחד יצחק היה לי. כי יעקב היה בחור שבאבות בחי' התכללות מבריח מן הקצה כו'. ולכן אמר אלקי אבי אברהם ופחד יצחק היה לי שהי' לו שני הבחינות בחי' אברהם כנ\"ל. וגם פחד יצחק היה יכול להמשיך למטה ג\"כ."],[25,"והנה לע\"ל כתיב כי אתה אבינו פי' כי עתה א\"א שבחי' פחד יצחק יהי' בבחי' אבינו שהיא המשכה למטה וכנ\"ל. אבל לע\"ל כשיהיה בלע המות לנצח ואת רוח הטומאה אעביר כו' אז יתגלה בחי' פחד יצחק למטה שיהי' הוא בחי' אבינו כדכתיב לבא בנקרת הצורים ובסעיפי הסלעים מפני פחד ה' שיתגלה בחי' פחד ובטול למטה וראו כל בשר."],[25,"וזהו אלה תולדות יצחק בן אברהם. אברהם הוליד את יצחק. ב\"פ אברהם וב\"פ יצחק. כנודע ממשל גשמי שהזכר יוכל להזריע בלא נקבה משא\"כ הנוקבא כו'. והגם שאמרו אשה מזרעת תחלה כו' היינו ג\"כ ע\"י התעוררות הדכר תוכל הנוקבא להזריע תחלה כו'."],[25,"וגם אח\"כ עיקר ההולדה מטפת הדכר שממנו הלובן ⟦יז,ד⟧והוא המברר הולד להיות הפסולת יוצא לחוץ. ומהבירור נעשה הולד כו'. כמו\"כ למעלה שיתהווה בחי' יצחק ממטלמ\"ע שבאמת אין ערוך אליו כלל הוא בא ע\"י בן אברהם פי' ע\"י ההארה הבאה מלמעלה למטה שיתהווה בכ\"א בחי' יצחק העלאת מ\"ן ממטה למעלה."],[25,"וזהו תולדות יצחק הוא בן אברהם כו'. ואח\"כ אברהם הוליד את יצחק. פי' שיהי' בחי' יצחק בבחי' הולדה כי באמת אין ערוך נברא לבורא ושיהי' ההעלאה בחי' בטול לאלקות בתכלית א\"א כ\"א ע\"י אברהם שהוא בחי' אב\"ר מ\"ה בחכמה אתברירו שהוא המברר להוליד בחי' יצחק להיות נתפס בחי' גילוי אלקות והפסולת יוצא לחוץ ע\"י טפת דכר שממנו יוצא לובן העליון כנ\"ל בחי' אברהם כו' וד\"ל:"],[26,"<b>מים רבים לא יוכלו לכבות את האהבה וגו' עד בוז יבוזו לו.<\/b> ובזוהר ח\"ג דנ\"ד ע\"ב מים רבים דא הוא נהר עלאה דמניה נפקין נהרין לכל עיבר כו'. והנה הנהרות נמשכים מן המעיינות שהמעיינות נובעים מן התהום ומהם נמשכים הנהרות וכמ\"ש השולח מעינים בנחלים והמעיינות נובעים מתחת לארץ אבל הנהרות נמשכים בגלוי ע\"פ כל הארץ לכך התורה שנמשלה למים כמ\"ש הוי כל צמא לכו למים יש בה בחי' מעיין והוא כמאמר חכים ולא בחכמה ידיעא שאינו מושג כלל כמשל המעיין שנובע מתחת לארץ ואינו ניכר ונגלה כ\"כ ויש בה בחי' נהרות וכמ\"ש ונהר יוצא מעדן להשקות את הגן כו' שזיו השכינה המתגלה בג\"ע בהשגת רזין דאורייתא נמשך מבחי' נהר היוצא מעדן כו' ונמשך ומתחלק לכמה בחי' נהרות והמשכות פרטיים לכל אחד כפי השגתו כו'."],[26,"ולכן נק' נהר לפי שבא ונמשך בגילוי להיות מושג לצדיקים וע\"ז נאמר מים רבים לא יוכלו לכבות את האהבה של כנס\"י להקב\"ה כי עם היות שזהו גילוי מדריגות עליונות מאד עכ\"ז לא ישקיטו את האהבה שהנפש לא תתמלא ותתרוה צמאונה ע\"י גילוי זה לבד וכמ\"ש מי לי בשמים ועמך לא חפצתי בארץ כי שמים וארץ הם ג\"ע העליון והתחתון שבו מתענגים הנשמות ע\"י נהר היוצא מעדן כו' ועכ\"ז מי לי בשמים כו' כי ג\"עהוא רק לפי שעה אבל עיקר הגילוי יהיה לע\"ל בתח\"ה וכמ\"ש ומעין יצא מבית ה' שזהו למעלה מעלה מבחי' נהר כו' והיינו ע\"י עסק התורה ומצות שעז\"נ ותרד העינה ותמלא כדה הם כ\"ד ספרין דאורייתא שהם נמשכים מבחי' המעיין בחי' חכים ולא בחכמה ידיעא שעיקר גילוי זה יהיה לע\"ל:"],[26,"<b>אך<\/b> הנה כדי להיות המשכה וגילוי זה ע\"י תומ\"צ מעשיות עז\"נ ותרד העינה ותמלא כדה שזהו ע\"י רבקה אמנו שהיא היא אשר ביכולתה להיות ותמלא כדה כו'. ולהבין מהו בחי' רבקה י\"ל תחלה ענין בחי' יצחק כי הנה יצחק הוא לשון צחוק ותענוג והוא גילוי תענוג העליון לצדיקים לע\"ל כמ\"ש לויתן זה יצרת לשחק בו."],[26,"ולכן יצחק הוא לשון עתיד כי הנה בחי' צחוק עשה לנו אלקים שבחי' גילוי תענוג זה נמשך ע\"י שם אלקים. והענין כי שמש ומגן הוי\"ה אלקים ששם אלקים הוא המגן ונרתק על שם הוי\"ה המהוה מאין ליש שהנרתק הוא כסוי והעלם שלא יהי' גילוי שם הוי\"ה רק ע\"י לבוש והנרתק המסתיר עליו וכמשל אור וזיו השמש המאיר דרך מסך ופרגוד כמ\"ש במ\"א ע\"פ והבדילה הפרכת כו' ומחמת נרתק ומגן זה נעשו הנבראים בחי' יש ודבר נפרד ובהתרבות הלבושים ע\"י ק\"ך צירופי אלקים נמשך למטה בעשייה החשך וההסתר ביותר ועל כן ירדה הנשמה למטה להיות עובד אלקים דהיינו לעבוד ולתקן את בחי' החשך וההסתר הנמשך משם אלקים לאהפכא חשוכא לנהורא וזהו אשר ברא אלקים לעשות ופי' במדרש לעשות לתקן. (והיינו לתקן) ההסתר הנמשך משם אלקים והוא ע\"י בטול היש לאין שעי\"ז אתהפכא חשוכא לנהורא. והיינו ע\"י מס\"נ בתפלה וע\"י ⟦יח,א⟧תומ\"צ. וזהו צחוק עשה לי אלהים שעיקר הצחוק ותענוג העליון נמשך ע\"י שם אלקים כמשל הצחוק שעושים השרים שהוא מדבר חדש כמו מלחמת הארי עם חיה אחרת שמההתחדשות נמשך הצחוק והתענוג כך בחי' בטול היש לאין זהו ההתחדשות שהנברא שנעשה יש ודבר נפרד יוכל לבטל א\"ע. משא\"כ אם לא היה שם אלקים מסתיר לא היה נמשך בחי' צחוק ותענוג זה כלל א\"כ עיקר הצחוק והתענוג עשה לנו השם אלקים המסתיר ומעלים שבסבתו נמשך התענוג והיינו ע\"י בטול היש לאין."],[26,"והנה עיקר הצחוק והתענוג מתגלה כשנשלם הבירור והתקון דשם אלקים וכמו במע\"ב כתיב וירא אלקים את כל אשר עשה והנה טוב מאד ויכולו השמים שבגמר כל המלאכה נתגלה התענוג משא\"כ בעוד שלא נגמרה המלאכה אין התענוג מתגלה כ\"א הוא עוסק לגמור המלאכה. כך עד\"ז עכשיו העסק הוא להיות עובד אלקים לאהפכא חשוכא לנהורא ובגמר ושלימות הבירורים אזי כתיב ותחדש פני אדמה ישמח ה' במעשיו ויהיה גילוי הצחוק והתענוג ולכן נק' יצחק ע\"ש העתיד שלעתיד יהיה גילוי צחוק ותענוג זה:"],[26,"<b>והנה<\/b> ביצחק כתיב והנה יצחק מצחק את רבקה אשתו. פי' שכל הצחוק ותענוג עליון דיצחק הנ\"ל הוא נמשך ע\"י רבקה אשתו. כי הנה עיקר בחי' אתהפכא חשוכא לנהורא הוא שייך בנה\"ב שבאדם שהיא צריכה בירור ותקון לעשות לתקן משא\"כ הנשמה עצמה א\"צ תקון. ונה\"ב שרשה מחיות המרכבה פני שור וכו' וכמו שיש כח בהמרכבה להיות והחיות נושאות את הכסא כך יש כח בנה\"ב להיות בה וע\"י עליות לנה\"א והיינו אחר הבירור של נה\"ב משום ששרשה גבוה מאד נעלה מלפני מלך כו':"],[26,"<b>ובזה<\/b> יובן ענין בחי' רבקה שהוא מלשון רבקות של שלש שלש בקר או של ארבע ארבע דהפי' הוא חבור וקשור של שלש או ארבע בהמות יחדיו נק' רבקה וכך הוא בענין חיות המרכבה כשהן כלולים ומתייחדים יחד להיות והחיות נושאות הן בחי' רבקה של שלש שלש בקר שהוא התכללות חג\"ת פני ארי' מבחי' חסד."],[26,"ופני שור מבחי' גבורה כו'. ולפעמים הן של ארבע ארבע שהוא בחי' פני אדם שבחיות המרכבה שהן ד' בחי' חגת\"מ. ועד\"ז ארז\"ל האבות הן הן המרכבה שהן ג' בחי' חג\"ת ודוד הוא רגלא רביעאה כו'. וז\"ש במרכבת יחזקאל חוברות אשה אל אחותה שהן בבחי' חבור והתכללות שעי\"ז דוקא והחיות נושאות כו' משום שע\"י ההתכללות וחבור המדות יחדיו עי\"ז מתעלים וממשיכים מבחי' עליונה מאד ששם כל המדות כלולים יחדיו (עמ\"ש בפ' נח בענין זה). ועד\"ז יובן בעבודת ה' באדם כשיש בחי' התכללות המדות אהוי\"ר והתעוררות רחמים על נפשו שירדה פלאים זהו נק' בחי' רבקה של שלש שלש בקר שמדות נה\"ב מתבררים מק\"נ ועולים לה'. וזהו והנה רבקה יוצאת שיוצאת מק\"נ ואתהפכא חשוכא לנהורא ולפעמים היא של ארבע ארבע בהתכללות מדת מל' שהוא בחי' בטול וקבלת עול ועבודת עבד כי העבודה והיראה הן שני מצות כו'. וזהו שיצחק מצחק את רבקה אשתו דהיינו שבחי' יצחק שהוא התענוג שיתגלה לע\"ל הרי הוא נמשך את רבקה אשתו (שהוא בחי' בירור דשם ב\"ן בגימ' בהמה דהיינו ע\"י בירור נה\"ב כשעולה למעלה מעלה להיות בבחי' רבקה כי למטה הוא ענפין מתפרדין אבל ע\"י הברור אז נעשה התכללות כו') ולכן עי\"ז דוקא ותרד העינה ותמלא כדה דהיינו שע\"י בחי' בירור ובטול נפש הבהמית דוקא הנה ע\"י העלאה זו נמשך להיות ירידה והמשכה בחי' ותמלא כדה היינו כ\"ד ספרין דאורייתא. כי הנה כל התורה נתלבשה בענינים גשמיים כמו מצות ⟦יח,ב⟧תרומות ומעשרות בצמח וזרע הארץ ומצות קרבנות בבע\"ח וכן בכל המצות שכ\"ז הוא נלקח מק\"נ וע\"י המצות מתבררים ונמשך עי\"ז גילוי א\"ס ב\"ה אשר אנכי מצוך."],[26,"וזהו הנה אנכי נצב על עין המים דהיינו בבחי' ותרד העינה ותמלא כדה נמשך ממש בחי' אנכי שהוא סדכ\"ס שממנו נמשך המעיין כו'. ולכן כדי שיהי' המשכה זו גילוי אוא\"ס ב\"ה בדברים גשמיים שמק\"נ הוא דוקא ע\"י בירור נה\"ב תחלה שהיא ג\"כ מק\"נ שאז אחר בירור והעלאה זו יוכל להיות המשכה וירידה זו (ועמ\"ש כיוצא בזה ע\"פ וספרתם לכם כו' וע\"פ זכור את יום השבת). וע\"כ לא נתנה תורה למלאכים משום כלום יצה\"ר יש ביניהם ואין שייך אצלם בירור ק\"נ ואתהפכא חשוכא לנהורא ולכן א\"א להיות ג\"כ אצלם המשכה זו מבחי' אשר אנכי מצוך ואע\"פ שבודאי נמשך גילוי אלקות למלאכים הוא מבחי' ונהר יוצא מעדן להשקות את הגן דבזה כתיב היושבת בגנים חברים שהם המלאכים מקשיבים לקולך. אבל גילוי בחי' ותרד העינה ותמלא כדה לא נמשך להם כ\"א למטה דוקא. ולכן ארז\"ל עתידים צדיקים שיאמרו (המלאכים) לפניהם קדוש:"],[26,"<b>וזהו<\/b> מים רבים לא יוכלו לכבות את האהבה. פי' מים רבים הוא ההתבוננות שהאדם משיג ומתבונן בגדולת ה' ביחו\"ע ויחו\"ת בפסוק שמע ישראל ובשכמל\"ו שמזה נמשך ואהבת בכל לבבך כו' ואהבה זו גדלה מאד להיות נפשו צמאה לה' בבחי' בכל מאדך בלי גבול."],[26,"ולא יוכל להשקיט ולכבות צמאון האהבה זו ע\"י המים רבים עצמן שהיא ההתבוננות הנ\"ל שמשיג ביחו\"ע ויחו\"ת כי אם רץ לבך שוב לאחד הוא דוקא ע\"י עסק התורה ומצות מעשיות שזהו בחי' אשר אנכי ממש מצוך. משא\"כ בידיעה והתבוננות לבד הוא רק ידיעת מציאותו ולא בחי' אשר אנכי ממש מצוך שהוא כמו בחי' תפיסא במהו\"ע כביכול ע\"י המצות מעשיות דרמ\"ח פקודין אינון רמ\"ח אברי' דמלכא. יתר על כן אפילו ההשגות שבג\"ע שהיא השגת מהות זיו השכינה ממש ולא מציאותו לבד עכ\"ז עז\"נ מים רבים הנמשכים מנהר היוצא מעדן כו' לא יוכלו לכבות את האהבה דבחי' רבקה בכל לבבך ומאדך הנ\"ל וכמ\"ש מי לי בשמים וגו' כי הגלוי שבג\"ע נקרא רק זיו והארה בלבד ונק' לקבל פרס לשון פרוסה כמ\"ש במ\"א. אבל האהבה הנ\"ל היא למהו\"ע ית' וזה שלא ע\"מ לקבל פרס כו' וזהו ונהרות לא ישטפוה כי בעבר הנהר ישבו אבותיכם שבחי' אה\"ר הנ\"ל היא מגעת למעלה אפילו מבחי' הנהר הנ\"ל שהוא מקור כל הנהרות כו' וא\"כ ודאי ונהרות לא ישטפוה:"],[26,"<b>אך<\/b> אם יתן איש את כל הון ביתו באהבה בוז יבוזו לו. פי' אם הוא לשון כאשר שיש אם שאינו משמש בלשון ספק אלא בלשון ודאי. כמו אם כסף תלוה. ואם יהיה היובל שאין זה לשון ספק אלא שבודאי יהיה הדבר ויבא."],[26,"ולשון אם כאן אינו אלא לשון כאשר. פי' כאשר כסף תלוה את העני לא תהיה לו כנושה וכן כאשר יהיה היובל. וכמו כן אם יתן איש פי' כאשר יתן איש זה הקב\"ה שיתן בודאי והיינו לעתיד שיתן הוא לשון עתיד שלעתיד לבא יתן את כל הון ביתו שבזמן הזה אינו בא לידי גילוי כ\"א לעתיד דוקא. אך הגם שאין זה בגלוי עכשיו מ\"מ נמשך הוא ממש בחי' זו ע\"י תורה כ\"ד ספרים דאורייתא ומצות מעשיות שהם בחי' והיו הדברים האלה אשר אנכי מי שאנכי ממש נמשך עי\"ז."],[26,"וזהו מצוך ל' צוותא וחבור. וזהו בא\"י אמ\"ה אק\"ב אתה היינו מהו\"ע ית' ברוך ונמשך בבחי' שם הוי' המתלבש בע\"ס יו\"ד בחכמה כו' עד שנמשך להיות מלך העולם בבחי' מל' מקור דבי\"ע והוא אשר קדשנו אשר לשון ענג כמו באשרי כי אשרוני והוא בחי' תענוג וצחוק העליון שיתגלה לע\"ל בפו\"מ כשיתן הון ביתו כו' הוא נמשך עכשיו ממש כי היום לעשותם ולמחר לקבל ⟦יח,ג⟧שכרם."],[26,"וענין פי' ברכה זו שצ\"ל הוא עד\"מ אם רוצה אדם להאיר למרחוקאו במקום חשך ואפילה צריך להדליק אבוקה גדולה ולהוסיף על האור בכדי שיגיע אורו גם למרחוק וכך כדי שיגיע האור והגילוי בעשי' הגשמי' צריך להוסיף אור האבוקה וזהו הברכה כו'. ולכן ארז\"ל חייב אדם לברך מאה ברכות בכ\"י. וכמ\"ש בזוהר ר\"פ חיי שרה דקכ\"ג ע\"א. שהוא המשכה מאתר עלאה סדכ\"ס כו'."],[26,"והנה ע\"ז ארז\"ל יפה שעה א' בתשובה ומעש\"ט בעוה\"ז מכל חיי העוה\"ב כי ג\"ע הוא רק זיו השכינה ולכן לא יוכל לכבות את האהבה אבל המשכה זו היא מבחי' מהו\"ע ולא זיו לבד ולכן נק' הון ביתו. דהנה כתיב בחכמה יבנה בית. פי' אותיות התורה נק' בתים כמ\"ש בס\"י שני אבנים בונות שתי בתים. ולכך נק' ת\"ח בנאים שעוסקים בבנינו ש\"ע."],[26,"והנה בחי' חכמה הוא חכים ולא בחכמה ידיעא שהוא למעלה מבחי' ונהר יוצא כמש\"ל ובתבונה יתכונן הוא מ\"ש ולתבונתו אין חקר ובדעת חדרים ימלאון כל הון יקר ונעים והוא בחי' תענוג עליון הגנוז ומלובש בהתורה כמ\"ש אני תורתך שעשעתי."],[26,"וזהו בחי' הון ביתו שנמשך ע\"י הדעת כי דעת ל' חבור כמו והאדם ידע והיינו שמחבר וממשיך בחי' תענוג עליון ממקור התענוגים בחו\"ב דאורייתא מחכמה נפקת. והוא ע\"ד מ\"ש בספר הבהיר דהע\"ה היה מחבר תורה שלמעלה בהקב\"ה וגילוי זה יהיה בפו\"מ לע\"ל שיתן איש אתכל הון ביתו הון יקר ונעים."],[26,"וכמארז\"ל עתיד הקב\"ה להנחיל לכל צדיק ש\"י עולמות וזהו בחי' ההון יקר כי יקר ג\"כ גימטריא יש ולכן נאמר אם יתן אי\"ש א' י\"ש שהמשכת ש\"י עולמות נמשכים מן אלופו של עולם וכמ\"ש אאלפך חכמה אאלפך בינה. ונאמר קנה חכמה קנה בינה ב\"פ קנה גימטריא י\"ש שכ\"ז נמשך מבחי' האלף אאלפך כו':"],[26,"<b>והנה<\/b> בחי' גילוי זה הוא מרוה צמאון האה\"ר הנ\"ל וזהו בוז יבוזו לו ל' ביזה ושלל וכמו אדם הבוזז וחוטף דבר יקר הערך כמו ביזת אוצרות יקרים שבוזז וחוטף משום שמא אין ראוי שיתנו לו דרך נתינה ע\"כ בוזז וחוטף לגודל תשוקתו לזה."],[26,"וכך הוא בהתגלות אוצרו הטוב שהוא בחי' סדכ\"ס אשר עין לא ראתה אלקים זולתך. ונק' הון ביתו ע\"כ כאשר יומשך ויתן גילוי אוצרות אלו אזי בוז יבוזו עד\"מ. ובחי' זו עכשיו היא שמחת הנפש בעסק התורה ומצות אחר הצמאון ואה\"ר בק\"ש אשר יעורר האדם בנפשו להיות מי לי בשמים כו' ומים רבים לא יוכלו לכבות את האהבה. זאת ישים אל לבו כי הדברים האלה הן ד\"ת ומצות הם הם בחי' גילוי הון יקר הנ\"ל."],[26,"וכמ\"ש יראת ה' היא אוצרו ולזאת ישמח לבו בשמחה ובטוב לבב מרוב כל. וזהו ותרד העינה ותמלא כדה ותעל. שע\"י כ\"ד ספרים דאורייתא עם היות שזהו בחי' שוב וירידה שנתלבשו בעשיה גשמית הנה עי\"ז אדרבה ותעל גם למעלה מאה\"ר הנ\"ל דבחי' רבקה כו' והגם שמים רבים לא יוכלו לכבות את האהבה היינו מים רבים דייקא שנמשכו מבחי' הנהר אבל כ\"ד ספרים דאורייתא הם נמשכים מבחי' ותרד העינה שהמעיין נמשך מבחי' סדכ\"ס ממש כמ\"ש הנה אנכי נצב על עין המים ולכן עי\"ז ירוו צמאון האה\"ר ולכן אדרבה המעיין הוא נראה קטן יותר מהנהר היינו משום שהוא קרוב יותר לבחי' אנכי סדכ\"ס ע\"כ יש בו הבטול יותר דכל הקרוב קרוב קמי' כו' וכמאמר אין זולתך לחיי עוה\"ב אפס בלתך כו'. אבל באמת בודאי הרי מקור מוצא המים הוא מהמעיין וממנו נמשך להנהר כמ\"ש המשלח מעינים בנחלים."],[26,"וגם מי מעיין נק' מים חיים כו'. ובוז יבוזו כמאמר שיננא חטוף ואכול חטוף ובריך דהיינו כמ\"ש לכו לחמו בלחמי וכמ\"ש פי פערתי ואשאפה כו'. עמא פזיזא כו'. ולכן נרמז ג\"כ נסוך המים בחג בלשון ⟦יח,ד⟧בוז יבוזו כמ\"ש בזוהר דהיינו כי בקרבנות דיום שני וששי ושביעי נרמז נסוך המים כמארז\"ל נאמר בשני ונסכיהם כו'."],[26,"ושני וששי ושביעי הם אותיות בוז. והיינו משום שזהו ג\"כ ע\"ד ביזה הנ\"ל להשקיט רשפי אש האהבה שבמזבח שהוא ע\"י נסוך המים מהמעיין כמ\"ש ושאבתם מים בששון כו' ולכן נסוך זה דוקא אחר עשי\"ת שהיא תגבורת האהבה בבחי' תשובה ועמך לא חפצתי כו' ע\"ד והנה רבקה יוצאת כנ\"ל."],[26,"ועי\"ז אח\"כ דוקא נמשך בחי' ותרד העינה ותמלא כדה וכמש\"ל ולכן היה בזה שמחה רבה ועצומה כו'. וגם כי זהו כמו בחי' הון ביתו ממש שהוא גנוז באותיות התורה שהרי לא נתפרש בתורה בפי' מצות ניסוך המים רק שחז\"ל גילו לנו זה שהוא מרומז בתורה המ\"ם ביום שני. והיו\"ד ביום ששי. והמ\"ם בשביעי. וזהו הון ביתו הגנוז ומוטמן כו':"],[26,"<b>ועכ\"ז<\/b> יובן מ\"ש נשאו נהרות קולם ישאו נהרות דכים ופי' בזוהר פ' וארא (דף כ\"ג ע\"א) אינון נהרות כמד\"א ונהר יוצא מעדן וגו' והיינו בחי' בינה שע\"י ההתבוננות בגדולת א\"ס ב\"ה נולד' רשפי אש האהבה לדבקה בה'. וזהו נשאו נהרות קולם והוא ההעלאה מלמטה למעלה. וכן בתרגום קלהון בשירתא הרי קול זה הוא בחי' השיר שהוא העלאה כנודע מענין השיר שהלוים אומרים ואח\"כ נמשך עי\"ז המשכה מלמעלה למטה."],[26,"וכמש\"ל שע\"י והנה רבקה יצאת בבחי' העלאה עי\"ז אח\"כ ותרד העינה ותמלא כדה כנ\"ל וכמ\"ש אם ישים אליו לבו רוחו ונשמתו אליו יאסף. וזהו ישאו נהרות דכים ותרגומו יקבלון נהרותא אגר שבחיהון שהשכר הוא ההמשכה מאוא\"ס המלובש בתורה חכים ולא בחכמה ידיעא שהיא למעלה מבחי' הבינה וההשגה. והוא ע\"ד השולח מעינים בנחלים. וכדפי' בזוהר פ' חוקת (דף קפ\"א ע\"א) ונק' דכים לשון צלילות ובהירות כמו מר דרור ומתרגמינן מירא דכיא. וזה מורה על הלכות התורה כמ\"ש במ\"א בענין מרדכי וכן הוא ל' טהרה כמו על איל קמצא דכן דהיינו המשכת ח\"ע בתורה הוא לברר הטהור מן הטמא."],[26,"ונק' דכיין ומסאבין. וגם דכים דך ים היינו כד הנמשך מים החכ' כמ\"ש ותמלא כדה כו'. וגם דכים ל' עומק ושפלות כדפרש\"י שהוא בחי' השוב ובטול שאחר הרצוא. וכתיב ואת דכא ושפל רוח וכמ\"ש במ\"א ע\"פ ונשב בגיא כו' וכמ\"ש ג\"כ אי זה בית אשר תבנו לי כו' ואל זה אביט אל עני ונכה רוח כו'."],[26,"והדר מפרש מהו מעלת השכר הזה מקולות מים רבים אדירים כו' אדיר במרום כו'. ופי' כמ\"ש בפע\"ח שער היוכ\"פ פ\"ג כי יש קולות עליונים שמהן ניזונים או\"א כו' ע\"ש. ועמ\"ש ע\"פ וכל העם רואים את הקולות כו' וזהו עדותיך נאמנו מאד לביתך נאוה קודש. עד\"מ בחכמה יבנה בית דקאי על תיבות ואותיות התורה שנמשכו ונבנו ע\"י ח\"ע."],[26,"ועדותיך נאמנו. עדות לשון דעת היא כמ\"ש ובדעת חדרים ימלאו כל הון יקר הנק' הון ביתו. וזהו לביתך נאוה קדש. שהוא המשכה מבחי' קדש העליון אור א\"ס ב\"ה. ה' לאורך ימים הוא כמארז\"ל על אלף השביעי יום שכולו ארוך."],[26,"והענין הוא כי פי' כולו ארוך היינו שגם בתחלתו הוא ארוך. ולכאורה אין לשון אריכות נופל רק בסיום וסוף ולא בתחלה. ואיך כולו ארוך גם בתחלתו. אך הכוונה שיהיה גילוי אור א\"ס ב\"ה המלובש בסתר עליון שנק' אריך אנפין כמ\"ש ארך אפים כו'. ונק' אריך אנפין היינו שיכול לימשך גם למטה בעשי' כי קמיה ית' שוה ומשוה רוחניות וגשמיות ולכן יהיה הגילוי למטה ביחו\"ת כמו ביחו\"ע (ועמ\"ש ע\"פ ועתה יגדל נא כו' כאשר דברת לאמר ה' ארך אפים כו') וע\"כ כולו ארוך בתחלה כמו בסוף שהוא גילוי בחי' שאין לו תחלה ואין לו תכלה ועד\"ז הוא מארז\"ל כסא ⟦יט,א⟧דמלכא משיחא מחזיק רכ\"א לוגין שאין לו פי' ע\"פ פשוטו כלל מהו ענין רכ\"א לוגין דוקא. אלא הכוונה שהכוס הוא הכלי לגילוי אוא\"ס ב\"ה ויהיה הגילוי בו מבחי' ארך אפים כו' כנ\"ל:"],[27,"ביאור על הנ\"ל"],[27,"<b>להבין<\/b> ביאור הדברים ע\"פ אם יתן איש את כל הון ביתו באהבה כו'. הנה אם הוא לשון כאשר. שיש אם שאין משמשין בלשון ספק. אלא בלשון ודאי כמו אם כסף תלוה. ואם יהי' היובל כו' שאין זה לשון ספק כלל אלא שבודאי יהיה הדבר ויבא ולשון אם אינו אלא לשון כאשר. פי' כאשר כסף תלוה את העני לא תהיה לו כנושה וכן כאשר יהיה היובל כו'. וכמו\"כ אם יתן איש כו'. פי' כאשר יתן איש כו' שיתן בודאי. והיינו לעתיד (שיתן הוא לשון עתיד) שלע\"ל יתן איש את כל הון ביתו. שבזה\"ז אינו בא לידי גילוי להיות בבחי' זו שיתן כל הון ביתו. כ\"א לעתיד דוקא. והענין כי הנה הון ביתו היינו כמו האוצרות והמטמונים שמונחים בתוך הבית. והוא ע\"ד מ\"ש ובדעת חדרים ימלאון כל הון יקר ונעים."],[27,"והנה כתיב בחכמה יבנה בית ובתבונה יתכונן ובדעת חדרים ימלאון. פי' בחכמה הוא רק עצם בנין הבית לבד שהן אותיות התורה שנק' בתים כנודע. ובתבונה יתכונן פי' עיקר קיום והעמדת תבנית ותוכן הבית ברבוי חדריו ומוצאיו ומובאיו הוא ע\"י הבינה דייקא. אבל בדעת ימלאון כל החדרים בהון יקר כו'. ולהבין את כל זה צריך להקדים הקדמה אחת בביאור ענין סדר השתלשלות די\"ס דאצי' איך הוא סדרם ואופנם. ומצינו בזה בדברי המקובלים (בע\"ח ובפרדס) שני אופנים אשר לכאורה הם כמעט הפכים. האופן הא' שבחי' השתלשלות הם זה תחת זה. דהיינו שבחי' בינה נאצלה מבחי' חכמה ובחי' דעת מבחי' בינה. וג' אלו הן ג\"ר. ומהם נאצלו חג\"ת ג\"כ ע\"ד הנ\"ל."],[27,"והנה ציור גשמי הלז הוא עד\"מ מבשרי אחזה כו'. כמו עשר כחות הנפש שמתלבשים בתוך אברי הגוף שראשית הגילוי הוא בחכמה שהיא בחי' הברקת השכל בבחי' נקודה כו'. ונק' חכמה כח מ\"ה כו' לפי שעדיין אינה מושגת ונק' בחי' י' נקודה כו' וממנה נמשכת בחי' בינה התפשטות ההשגה באורך ורוחב."],[27,"והוא בחי' ה' כו' והן הם אב ואם המולידות את המדות אהוי\"ר כי לפי שכלו והתבוננותו בדבר הוא מוליד אהבה לדבר ההוא או יראה ממנו כו'. וכמו\"כ למעלה בעולם האצי' בסדר השתלשלות הי\"ס בחי' ח\"ע דאצי' היא ראשית הגילוי והיא בחי' י' של שם הוי' שעדיין אינה בבחי' גילוי והחכמה מאין תמצא ולכן התלבשות אור א\"ס בחכמה דוקא ומבחי' חכמה נמשכה בחי' בינה דאצי' שהוא בחי' גילוי ההתפשטות באורך ורוחב הנק' ה'."],[27,"ונק' אם הבנים. והאופן הב' של סדר ההשתלשלות שהם בציור ג' קווין חח\"ן בקו ימין כו'. נמצא לפי סדר זה בחי' חב\"ד אין נמשכות זו מזו. וגם המדות כולן אין עיקר המשכתן מן הג\"ר מאחר שחו\"ב עומדות בב' קווין מקבילות כו'."],[27,"והנה עיקר ההפרש שבין ב' הבחי' בסדר ההשתלשלות הנ\"ל הוא בב' אופנים. הא' שלפי סדר הא' שחב\"ד הם זו תחת זו נמצא שהדעת עומד למטה מחו\"ב. ולמעלה מחו\"ג כי הוא הממשיך הארת החו\"ב לחו\"ג. משא\"כ לפי סדר הב' שהם בג' קווין נמצא שהדעת הוא בקו האמצעי ואינו עומד תחת חו\"ב רק תחת הכתר והוא ממשיך הארת הכתר לחו\"ב ולחו\"ג כמשי\"ת."],[27,"והב' שלפי סדר הא' עיקר הולדת ומציאו' המדות הוא מחו\"ב ע\"י הדעת הממשיך כנ\"ל. משא\"כ לפי סדר הב' הן נמשכות מבחי' הכתר ע\"י הדעת הממשיך בהן הארת הכתר דוקא. ⟦יט,ב⟧והענין הוא דשניהם אמת."],[27,"ויובן זה ע\"פ מה שנודע שיש ב' בחי' דעת. דעת עליון ודעת תחתון. דעת העליון הוא הנמשך מבחי' הכתר ומחבר ומייחד לחו\"ב וחו\"ג ע\"י הארת הכתר ודעת התחתון הוא הדעת המתפשט בתוך המדות להמשיך בהן הארת חו\"ב. וגם הנה נודע שיש ב' בחי' מדות. הא' מדות שעיקר מציאותן הוא מחו\"ב עד\"מ באדם למטה כשהמדות הן רק לפי השכל שהשכל הוא המולידן וקטן ששכלו קצר כו'. והב' הוא בחי' המדות שמקורן ושרשן למעלה מן השכל רק שיוצאין ונמשכין דרך השכל וכמ\"ש בר\"מ דז\"א בעתיקא אחיד ותליא כו' וכמ\"ש באריכות במ\"א:"],[27,"<b>ומעתה<\/b> יובנו ויבוארו ב' הבחי' בסדר ההשתלשלות על נכון. כי הנה הסדר הב' שהן בג' קווין כו' היינו בענין המדות שאין עיקר מציאותן מחו\"ב כ\"א מבחי' הכתר שמאיר בהן וכמאמר דז\"א בעתיקא אחיד ותליא הנ\"ל והיינו ע\"י בחינת דעת העליון הנ\"ל שהוא מבחי' הכתר ומחבר ומייחד בחינת חו\"ב כו' שנמצא בחינת הדעת עומד בין חו\"ב ותחת הכתר כו'. משא\"כ סדר הא' היינו בבחינת המדות שמציאותן הוא רק מן השכל והיינו ע\"י בחינת דעת התחתון המתפשט בתוך המדות ומאיר בהן הארת חו\"ב כו':"],[27,"<b>ולהבין<\/b> כל הדברים הנ\"ל בתוספת ביאור צריך להבין תחלה בחי' הדעת מהו. ומתחלה נבאר בחי' הדעת התחתון וממנו יובן בחי' דעת העליון. דהנה כבר נתבאר למעלה כי עיקר הולדת המדות הוא מחו\"ב."],[27,"וצריך להבין בחי' דעת מהו משמש. אך הענין הוא דהדעת בכל מקום הוא מבחי' הפנימית. וכמו\"כ כאן בחי' הדעת המתפשט בתוך המדות הוא פנימי' המדות שהוא תכלית הבירור שלהן כי הדעת היינו התקשרות ומחמת התקשרות בחי' חו\"ב בתוך המדות מברר ומבדיל בין טו\"ר שלא תהיינה המדות מעורבות טו\"ר כי המדות בטבען כתולדותן יכולות להיות מעורבות טו\"ר."],[27,"ולכן יניקת החיצוני' הן מן המדות כמו אברהם שיצא ממנו ישמעאל כו'. וכמו\"כ בעבודת ה' מבחי' האהבה וההתפעלות כרשפי אש על ידי ההתבוננות בגדולת ה' בשעת התפלה יוכל לבא אח\"כ לידי כעס. ומוכרח להיות שגם בשעת התפלה היה קצת תערובת זר. שאם היתה בבחי' אלקות לבד שהוא גילוי אור ה' על נפשו בשעת התפלה. מאין בא אח\"כ לידי כעס וכדומה שהוא בחי' יניקת החיצוני'. כנודע שאין יניקת החיצונים רק מבחי' אחוריים דשם אלקים שהוא ענין בחי' ההסתר כו' (וצ\"ע בתניא פכ\"ח וצ\"ל דמ\"ש כאן קצת תערובת זר היינו מצד התלבשות הנה\"ב והמדות שבה הן הם המעורבות טו\"ר. ולפי שהנפש האלקי' מלובשת בה כו'. וההוכחה היא שגם בשעת התפלה לא יצאה מנרתקה ומהתלבשותה לגמרי מכל וכל כו'. והיינו ממש כמש\"ש פכ\"ח שהקליפה מתאמצת כו'. וגם מן הראיי' שיתבאר מעובדא דר\"ח ב\"ת משמע ג\"כ כמ\"ש דהתם ג\"כ קס\"ד שטעה בנפשו מחמת טבעיות נפשו הבהמית שאפשר שסייעה בעבודתו כמשי\"ת):"],[27,"<b>ובזה<\/b> יובן מעשה דר' יוסי בן קיסמא עם ר' חנינא בן תרדיון שאמר תמה אני אם לא ישרפו אותך כו'. והשיבו מן השמים ירחמו וא\"ל אני אומר לך דברי טעם כו'."],[27,"וא\"ל ר\"ח מה אני לחיי עוה\"ב. וא\"ל כלום מעשה כו'. והשיבו מעות פורים וכו' וחלקתים לעניים. ע\"כ. ולכאורה מאד תמוה שאלתו מה הוא לעוה\"ב. אם הוא מוסר נפשו על קדוה\"ש שהי' מקהיל קהלו' ברבים לא יהי' לו עדיין חלק לעוה\"ב."],[27,"וגם מה שאל ר' יוסי כלום מעשה בא לידך. מהו התשובה על שאלתו כו'. אך הענין שהי' ר' חנינא בן תרדיון מסופק בעצמו ענין מסירת נפשו בשביל עסק התורה אם הוא באמיתות לש\"ש בלבד אף שהי' צדיק מופלג ולומד לשמה באמת מ\"מ לפי שיש בנ\"א שמצד ⟦יט,ג⟧טבעו ומזגו ומדותיו להמשיך חשק ותשוקת כל לבבו אל למוד החכמות."],[27,"ולהיות תמיד מחשבתו ולבו ושכלו דבוק בהן. והראי' מהפילסופים מהאומות הקדמונים שהיו שרים גדולים לא יחסר להם כל מעדני עולם. היו עוזבים כל תענוגי' ועוסקים בכל לבבם ותשוקת נפשם בלמוד החכמות. כל היום והלילה אין מחשבתו פנויה."],[27,"ולהבין ולהעמיק בענין החכמות ותערב לנפשו ותתענג בהם כ\"כ כמו זולתו בכל תענוגי העולם. וזה אינו להם מצד אמונתם שהם היו גוים עובדי כוכבים שאין להם שום הכרח ואמונה שיגרום להם סבת עסקם בחכמותיהם בתכונה ותשבורת ופילסופיא חכמת החיצוני' תענוג נפלא כ\"א מצד מזג טבעם מאד תכריח בחשק נפלא שנולד בטבע כזה."],[27,"ויש מהם נולד במזג אחר שלא יתאווה ויחשוק לחכמות אף כי יבינם אין לו תענוג להשים מחשבתו בהם אפי' רגע אחת רק אחר שרירות לבו רק רע כל היום לזאת תכלה נפשו."],[27,"וסבת זה הוא מצד המרות. יש שגובר בו מרה הלבנה שאין ביכלתו לצמצם מחשבתו בדבר א' אף שהוא שכלי ולא יתענג בו כלל. ויש שגובר בו מרה שחורה בתולדתו תשתוקק נפשו מאד אל החכמה כל חפציה לא ישוו בה כאש' כ\"ז מבואר בח\"פ להרמב\"ם ע\"ש פ\"ח."],[27,"ולכן גם בישראל ימצא טבעיים מחולקים כמותם. אך שתמשיך נפשו לדבר הנהוג בישראל כמו ענין למוד התורה שבע\"פ. יחשוק נפשו ולבו להגות בה יום ולילה לא ישבות. ולפיכך ר\"ח ב\"ת היה ירא שמא גם מצד טבעו גופני' גורם לו מסירת נפשו בעד החכמה אף שבודאי אינו אלא מעט מזעיר מ\"מ אין זה לה' לבדו כו'."],[27,"ושאל מר' יוסי היאך הוא משיג בו. אם הוא מנוחלי העוה\"ב שאין בלבו אלא אחד כו'. והשיבו זה לא יבורר כ\"א אם בא מעשה לידך. פי' נסיון שהחילוק בו שאם הוא מצד טבע הגוף אף שיחשוק חשק נפלא עכ\"פ לא יגיע למס\"נ כו' ואמר לו שמעות פורים כו' שהוא ענין פיזור ממון שזה אות ומופת שאין במס\"נ שלו אפילו שרש המרה כו'. שמדת המרה שחורה הנ\"ל גורמת מדת הקמצנות."],[27,"והמרה הלבנה הפיזור כו' לכן השיבו א\"כ מחלקך יהא חלקי שמזה מובן שמס\"נ על התורה הוא רק לפי שאין בלבו אלא אחד ואין בו תערובת טבעית כלל. ומכ\"ז מובן שיוכל להיות במדות הנפש בחי' תערובת שאפי' במדה שנראה ודאי טוב גמור יוכל להיות שיש בזה עדיין קצת תערובת כו'. ולכן כדי שיהי' בירור המדות לתכליתן הוא ע\"י בחי' הדעת. והיינו שהוא ממשיך פנימי' המדות כי עיקר תערובת טו\"ר זה שייך בחיצוני' הלב משא\"כ בבחי' פנימי' הלב כו' (עיין מש\"ל בסוף ד\"ה להבין ענין הברכות כו'). והנה כ\"ז בבחי' דעת התחתון המתפשט במדות אהוי\"ר. שהדעת הזה הוא תחת הבינה ואהבה שנולדה מהבינה והדעת נק' אהבת עולם. ובזוהר נק' אהבה זוטא. ומתוך זה נוכל להבין ג\"כ בבחי' דעת העליון. כי הנה יש ב' מיני מדות. הא' המדות הנולדי' מהשכל וכשהם נולדים ונמשכים מהשכל ע\"י הדעת אז הם בבחי' פנימיות ובבירור יותר מכל סיג."],[27,"והב' הם המדות שלמעלה מהשכל. ונק' אהבה רבה שיש בכל נפש. ולמעלה הוא בחי' מדות שבכתר חו\"ג דא\"א שהם למעלה מהשכל שהוא חו\"ב רק שנמשכים דרך מעבר בחו\"ב. והם נמשכים ע\"י הדעת שעומד בקו האמצעי. מכוון תחת הכתר. משא\"כ חו\"ב הם חח\"ן מימין בג\"ה משמאל לכן ע\"י הדעת זה נמשכים המדות דכתר שהם מדות שלמעלה מהשכל להיות נמשכין בז\"א. ולמטה הוא הגילוי במדות שבלב כו' ובחי' אה\"ר זו ישנה ג\"כ בכל א' וכמ\"ש בתניא (ס\"פ מ\"ו) ע\"פ בהמות הייתי עמך בהמות לשון רבים כו' דעת העליון הכולל חו\"ג כו' ע\"ש. וזהו ענין רבקה שהוא בחי' קשר וחבור של שלש או ארבע בקר יחד ⟦יט,ד⟧להיותה בחי' אה\"ר שהוא המדות שלמעלה מהשכל שהם בחינת התכללות כל המדות יחד ואין בהם התחלקות כלל (וכנ\"ל שדעת כולל חו\"ג שהן תרין עטרין הנמשכים מכתפין דאריך) כי בהמדות שעיקר התהוותן הוא מהשכל שייך התחלקו' המדרגה כי אותו השכל שמוליד אהבה הוא אינו אותה ההשכלה המוליד יראה ואותו השכל שמוליד יראה אינו המוליד אהבה. ולכן המדות הנולדים מהן הן בחי' ענפין מתפרדין זמ\"ז משא\"כ בלמעלה מהשכל אין שייך התחלקות כלל והוא ע\"ד ההפרש בין עולם העקודים לעולם הנקודים. שבעקודי' כל הע\"ס עקודי' בכלי' א' ואין בהם התחלקות כלל. משא\"כ בנקודים הם י' נקודות מחולקי'. והיינו משום כי נקודים הוא מבחינת חכמה (כי בענין טנת\"א הנקודות בחינת חכמה כו') ושם שייך התחלקות אבל העקודים הוא מבחי' כתר דשם הוא למעלה מההתחלקות. ולכן בחי' המדות שלמעלה מהשכל הנק' אה\"ר שיש בכל נפש זה נק' בחי' רבקה שהוא קשר וחבור כמה בהמות דר\"ל התכללות המדות יחדו ממש. וז\"ש ותרד העינה יש לפרשו כפשוטו ל' ירידה ממש כי החכ' נק' מעיין. כי והחכמה מאין תמצא מבחי' כתר כמו המעיין הנובע מתחת לארץ. ונהר הוא בחי' בינה. והנה לגבי רבקה שהם המדות שבכתר א\"כ ההמשכה בחו\"ב נק' ותרד העינה (ועמ\"ש בפי' ויוציאנו ה' אלקינו ממצרים. או\"א שהלבישו לזרועות דא\"א כו') ותמלא כדה היינו כ\"ד ספרין דאורייתא. דאוריי' מחכמה נפקת. ובעבודה הוא שע\"י האה\"ר ממשיכים התגלות אור א\"ס בחכמה ובתורה דמחכמה נפקת. ותעל כי באמת ירידה זו עלייה היא כי פי' אורייתא מחכמה נפקת היינו שהתגלותה היא מחכמה אבל שרשה למעלה מהחכמה כי תרי\"ג מצות דאורייתא עם ז' מצות דרבנן הם תר\"ך עמודי אור שהם בחי' כתר וא\"כ התורה נמשכת מחכ' שבכתר שהיא גבוה מבחי' המדות שבכתר הנק' רבקה של שלש בקר כנ\"ל (ועמ\"ש במ\"א בענין תנופת שתי הלחם ע\"ג שני הכבשים):"],[27,"<b>וזהו<\/b> מים רבים לא יוכלו לכבות את האהבה. והיינו להיות שאהבה זו היא בחי' אה\"ר ששרשה למעלה מהשכל ע\"כ לא ישקיטו המים רבים והנהרות שהן השגות אלקות הנמשכים מחו\"ב דאצי' את האהבה זו כיון ששרשה למעלה מכל ההשגות ונמשכה מבחי' דעת עליון הממשיך בחי' מדות שבכתר כו'. אך אם יתן איש את כל הון ביתו בוז יבוזו לשון ביזה ושלל כי ביתו קאי על אותיות התורה דכתיב בחכמה יבנה בית."],[27,"והון ביתו היינו מ\"ש ובדעת חדרים ימלאון כל הון יקר ונעים והיינו בחי' דעת העליון שממשיך גילוי בחי' הכתר שלמעלה מהחכמה. ודעת זה מחבר חו\"ב שהם תושב\"כ ותושבע\"פ וממשיך בהן אור הכתר דהיינו להיות גילוי רצון העליון איך לעשות הסוכה והציצית והתפילין. ולכן גם בחי' אה\"ר הנ\"ל תתרוה צמאונה ע\"י גילוי זה כיון שהוא ג\"כ המשכת דעת עליון ולא עוד אלא שהוא המשכה מבחי' גבוה יותר הרבה מהמשכת המדות שלמעלה מהשכל כי המדות הם בחי' ז\"ת דא\"א. אבל הון ביתו הוא התורה זהו בחי' ג\"ר דא\"א (ועמ\"ש בדרוש השופר שהכתר הוא ממוצע בין המאציל לנאצלים שיש בו מבחי' תחתונה שבמאציל והוא בחי' ג\"ר דא\"א. ויש בו בחי' שרש הנאצלים והוא מז\"ת ע\"ש. וא\"כ מובן איך שבחי' זו דהון ביתו הנמשך ע\"י התורה שהוא מבחי' ג\"ר גבוה לאין קץ גם מבחי' המדות שלמעלה מהשכל שהן בחי' ז\"ת כו'. וזהו ותרד העינה כו' ותעל שהיא עלייה גדולה למעלה מבחי' רבקה. וביאור הענין שדעת זה שנמשך ע\"י התורה דהיינו מ\"ש הון ביתו גבוה מבחי' דעת הממשיך אה\"ר יובן עם מ\"ש בלק\"ת פ' שמות ע\"פ כי סר לראות שבחי' דעת הכולל תרין עטרין עם היותן מדות דכתר הוא למטה מבחינת דעת הכולל תרין אחסנתוי דאו\"א כו' שממשיך ב\"פ קדמאין שהם בחי' חב\"ד שבחו\"ג דא\"א. ועמ\"ש בפ' ראה אנכי נותן בענין יום יום יעמס לנו כו' ע\"ש. ויובן שייכות ש\"י עולמות לדעת זה. וגם דעת זה שרשו עוד גבוה יותר דהיינו מתקון ואמת כו'. וז\"ש תורת אמת כו'). ובכ\"ז יובן מארז\"ל דחייב אדם לברך מאה ברכות בכל יום. דצ\"ל מספר מאה דוקא. אלא כי פי' א\"ת מה אלא מאה כי מה היינו בחי' מל' ממכ\"ע וצריך להמשיך מבחי' סוכ\"ע בממכ\"ע. והוא ע\"י הכתר שהוא הממוצע בין המאציל לנאצלים. ולכן צ\"ל מאה ברכות דוקא להמשיך מע\"ס דא\"א הכלולים מעשר דהיינו שיהי' ההמשכה גם מג\"ר דא\"א כנ\"ל. וזהו ונאם הגבר הוקם ע\"ל שהעי\"ן מורה על ז\"ת. והלמ\"ד על ג\"ר. (ובזה יובן משארז\"ל שהיו מתים ק' אנשים בכל יום עד שתקן דוד מאה ברכות. וצ\"ל השייכות שע\"י המאה ברכות פסקו מלמות). אך הענין כי הנה ע\"י גילוי זה דסוכ\"ע יהיה תח\"ה לע\"ל. והנה ענין תחיית המתים שיהיה גוף עם קרביים ומעיים וחי וקים לעולם בלי אכילה ושתיה. ואיך הוא זה אלא ע\"י שיהי' גילוי סוכ\"ע דקמיה שוה רוחניות וגשמיות ממש. ע\"כ גם הגוף יוכל לחיות מזה."],[27,"ועד\"מ באדם יש ב' מיני המשכות. הא' בבחי' פנימיות השכל במוח. ומדות בלב. כח המעשה ביד כו'. והב' בחי' מקיף והוא הרצון והמחשבה שישנו אפילו ברגל שמיד כשרוצה להניע רגלו תתנענע רגלו כו'. ואע\"פ שהרגל אינו כלי לגילוי המחשבה מ\"מ פועל בו המחשבה וזהו בחי' מקיף. ועד\"ז גם הגוף הגשמי יקבל חיות וקיום למזון מאור א\"ס ב\"ה ממש וד\"ל:"],[28,"<b>ויחפרו<\/b> עבדי יצחק בנחל כו'. באר חפרוה שרים וגו'. דהנה איתא בגמ' ע\"פ והנהר הרביעי הוא פרת הוא דמעיקרא שממנו נפרדו לארבעה ראשים דהיינו ג' יצאו ממנו והרביעי הוא בעצמו ואמרו כל הנהרות למטה מפרת וכל מעיינות שבעולם נובעים מסולמא דפרת פי' מתחת לקרקע נוקב והולך עד שבחפירה מועטת ימצא באר מים חיים."],[28,"ולכאורה תמוה מפני מה יקרא באר מים חיים כיון שעיקר נביעתו הוא מנהר פרת. והענין דהנה כתיב ונהר יוצא מעדן להשקות את הגן כו' ג\"ן סדרי דאורייתא פי' כידוע שבתחלה צריך לקבל עומ\"ש בשלימות דהיינו להאמין באמונה שלימה באחדות ה' שהוא המהווה כל העולמות וכולא קמיה כלא חשיב וכולא חד כו' וכאשר יתבונן האדם בק\"ש וישים ללבו היטיב ענין האחדות ויקבל עליו באמת עול מל' כי יעקב חבל נחלתו חפצם לדבקה בו בכל לבבם ומאמינים באחד וחפצים בו אבל אין מקום שישרה בו בחי' אחד לאחר שקבל עליו."],[28,"ואין לו מקום אלא בתורה שהיינו שמיד אחר קבלת מ\"ש ילמוד בעיון מחשבתו ושכלו ודבורו בתורה שבע\"פ וקודם למודו יתבונן באחדות ה' כו' ועי\"ז יגרום לו העסק בתורה בכל עומק מחשבתו ולבבו וכו' וזהו נק' ונהר יוצא מעדן פי' מעדן מעם הקב\"ה שנק' עדן ונהר הוא לשון המשכה פי' כאשר יומשך אלהות מלמעל' למטה בקבל' מ\"ש המשכה זאת משקה את הגן היא התורה שהיא ד' אמות של הלכה במקום קדשי קדשים אורייתא היכלא דמלכא שבה שורה אחדות ה' כו' כאשר יתקיים בו בחי' נהר יוצא מעדן בתפלתו ושעור למודו מיד אחר התפלה אבל אח\"כ צריך לעסוק בכל מחשבתו כו' בעניני עולם השפל ושוכח כל התבוננותו בקבלת מ\"ש מפני גשמיות גופו על מעוט דעת שלו ויתרחק מאד מבחינה שהיה לו דעת בתפלתו ועבודתו בתורה כו' לכך נתן לנו מצות לעשותם כל היום כי ענין המצות מעשיות הם הגבה למעלה מעלה בפנימיותם ושרשם אך שנתלבשו בכמה לבושים בהשתלשלות העולמות ⟦כ,ב⟧כו' ומ\"מ רומזים על מדרגה הגבוה שבשרש' כמו מצות ציצי' שענינה למעלה בעולמות עליונים ונתלבשה מצותה בשמונה חוטין של צמר וה' קשרים כו' ולכן המצות לא תצטרך להם עבודת האדם לתקנם ולכוון אל אמתתם כי מצות א\"צ כוונה לפי שהן בעצמם מתוקנים ונשתלשלו ממעלה למטה כו' והעושה המצוה המשכת אלהות שגורם אינה מצד עבודתו רק מחמת המצות עצמן כו'. משא\"כ בתורה ותפלה שהיא עבודת הלב תלויה דוקא בכוונת האדם כו' ועיקר הכוונה הצריכה בעשיי' המצות הוא שיתבונן בתחילה איך שהוא מאד רחוק מה' ע\"י טרדתו כל היום בהבלי חפצי העוה\"ז וגשמיות חומרו ועוונותיו מסך מבדיל לבלתי התקרב אל ה' אפי' מעט ויתבונן בזה היטב הדק וישבור לבו בהתבוננ' זה ויכנע לבבו מפני שמ\"מ חפץ הוא להתקרב אל ה' בתורתו כו' ויכוון במצוה שנזדמנה לידו בעשותו אותה. שהוא כמו באר מ\"ח שנובע מתחת הקרקע מנהר א' שאע\"פ שהנהר אינו נק' מ\"ח אבל המים היוצאים ממנו ונוקב והולך עובי עפר הקרקע נק' מים חיים מפני שמתברר ומתלבן ע\"י דחקם לצאת בעפר החומרי וכן ממש עשיית המצוות כשהי' לו בתחלה בתפלתו ועבודתו בחי' נהר יוצא מעדן הנ\"ל רק שנכסה ונעלם בתוכו ע\"י גשמיות תשוקת גופו כל היום."],[28,"וכשעושה המצוה שנובעת מנהר הנ\"ל פי' מפני שזוכר שכבר קבל ע\"ע מ\"ש בכל לבבו ולכך עושה מצותיו ליכנס בעול מלכותו אע\"פ שעכשיו אין לו בחי' נהר הנ\"ל סומך לבו על שכבר גמר בלבו לעבוד ה' באמת זהו כמו באר מ\"ח מפני שמאד ערב לו זאת המעט בעבודת ה' מפני שהתבונן שמאד מאד רחוק הוא מה'."],[28,"ועושה המצוה הוא ע\"ד הנ\"ל שמאד מתוק וערב לו לעשות המצוה כו' כמו הבאר כשחופרין בקרקע ומוצאים מים הם מ\"ח מפני שעברו עובי העפר כן עשיית המצות עשייתו אותה נובעת מנהר הנ\"ל כו'."],[28,"וזהו שהיה האריז\"ל שמח מאד בעשיית המצות ולכך זכה לרה\"ק ולא שמח בעבודתו כו' כי המצות בפני עצמם קדושתם כו' כנ\"ל ועשיותה באמהתבוננות שפלות התקרבותו אל ה' שזו היא מדת ענוה באמת שנאמר על מרע\"ה כי עיקר השפלו' בפני כל אדם שאמרו א\"א להיו' כ\"א עד\"ז שרואה בחבירו שהוא יותר קרוב לה' כו' וזהו נפש שבעה תבוס נופת שאפילו הדבש מר לו אבל נפש רעבה כל מר מתוק פי' באר מ\"ח הנ\"ל ע\"י חפירותו בעפר גופו כשיוצא מעט מים מתוקים ערבים לו מאד מפני שגופו רעבה בעבודת ה' וזהו באר חפרוה שרים:"],[29,"<b>ראה ריח בני כריח שדה אשר ברכו ה'.<\/b> להבין דהא יצחק הבין שהוא עשו ואיך היה חשוב בעיניו כ\"כ. גם באמת אינו מובן איך היה עשו בעיני יצחק. כי פעם אמר הכתוב כי ציד בפיו שהי' מרמהו בשאלות איך מעשרין את התבן כו' ופעם אמר הכתוב הקל קול יעקב והיינו לפי שאמ' כי הקרה ה' אלהיך כו' וידע שעשו אין ש\"ש שגור בפיו. אך הענין כי הנה עשו סוספיתא דדהבא פסולת הגבו' דיצחק שהוא בחי' מעלת הזהב על הכסף ומפסולת שלו יצא עשו ורישא דעשו בעטפוי דיצחק."],[29,"ולהבין ענין רישא הנה יש י\"א סממני הקטרת הצרי והצפורן כו' והם כנגד יו\"ד כתרין דמסאבותא שהוא החיות שבקדושה המחי' את זלע\"ז כמו שיש בקדושה י\"ס כך יש ממש בקליפה הארה מי\"ס דקדושה. אך בקדושה עשר ולא תשע ולא י\"א ובקליפה הוא י\"א סממני הקטורת."],[29,"והענין כי ע\"י החיות שנמשך בקדושה הנה כתיב וצבא השמים לך משתחוים שהם בטלים מחמת שמשיגים החיות שנמשך עליהם מקדושתו ית' משא\"כ הקליפות הם מגביהים א\"ע כנשר כו' בחוצפה והיינו לפי שהחיות הנמשך אליהם הוא אצלם בסוד ⟦כ,ג⟧גלות ולפיכך הגם שנמשך אליהם מחיות דקדושה אינם בטלים ואדרבה מגביהים א\"ע כנשר כו' והחיות שנמשך להם הוא נבלע בתוכם. אך כיצד הם חיים וקיימים מקדושה מאחר שהחיות נבלע בתוכם הנה זהו ענין לבונה שבי\"א סממני הקטורת שהוא אור המקיף עליהם מלמעלה ואינו נבלע בתוכם."],[29,"ולפי שהוא אור המקיף מלמעלה מן הדעת שלהם ואינם מרגישים בו והחיות שנמשך להם בפנימית נבלע כנ\"ל לפיכך הם מתגאים ומגביהים א\"ע בחוצפה כנ\"ל. ובחי' לבונה הוא המחבר י\"ס דקדושה להאיר לע\"ס דמסאבותא והוא רישא דעשו דהיינו בחי' המקיף מלמעלה הוא נכלל בעטפוי דיצחק ממש בקדושה ולכן מצד בחינת המקיף עשו שואל איך מעשרין את התבן ומצד הפנימיות אין ש\"ש שגור בפיו:"],[29,"<b>והנה<\/b> נודע כי החיות בעשר כתרין דמסאבותא הוא מפני כי חיל בלע ויקיאנו ועת אשר שלט האדם באדם לרע לו והוא מפני הנצוצות שנפלו בהם בתחלת בריאת העולם בשבה\"כ וימלך וימת כו' וגם מחמת חטא עה\"ד כמ\"ש בס' הגלגולים ולפיכך נמשך להם החיות בם שהוא בסוד גלות כמארז\"ל לא גלו ישראל אלא כדי להוסיף עליהם גרי' וכן בעשו היו ניצוצות כמו ר\"מ ואונקלוס ושמעי' ואבטליון ועובדיה ומהם הי' ציד בפיו והי' רוצה יצחק להוציא ממנו בעצמו שלא ע\"י יעקב כי הרי גם עכשיו חיל בלע ויקיאנו רק שהוא ע\"י יעקב שהוא בחי' ז\"א שכל האורות שלמעלה נכללים בו והוא מתלבש ביצי' ביומין דחול בחי' עבדו זקן ביתו להעלות משם ולברר כנ\"ל. אך יצחק רצה שיהי' זה שלא ע\"י ז\"א רק שיהי' התגלות האורות העליונים בעשו עצמו והוא ענין תוס' ורבוי האור כי הרי לברר הטוב מן הרע צריך להאיר שם אור רב כדי שיע\"ז יקלוט וילקט כל הניצוצו' הנשפעים שמה."],[29,"וזהו ויתן לך האלקים מטל השמים הוא טלא דעתיקא דנטיף לז\"א בחי' שמים. ומשמני הארץ שמן הוא חכמה ואבא יסד ברתא הנקרא ארץ ורצה להמשיך בחי' הטל והשמן דלעילא שעי\"ז יהי' העלאת הניצוצים כמו שאנו רואים עד\"מ כשהשמש זורח על הארץ כחום היום שואב לחלוחית הארץ ואד יעלה מן הארץ וכן בנר לפני האבוקה הגדולה שואבת אור הנרות כך ע\"י הארה עליונה הבאה בתוס' ורבוי מלמעלה שואב ולוקט כל הניצוצין שנפלו למטה. אך הארה זו צריך להיות בתוס' ורבוי דייקא בחי' ברכה שהיא למעלה מסדר ההשתלשלות שלפי סדר ההשתלשלות לא הי' עשו כדאי לו."],[29,"וזהו ואברככה לפני ה'. לפני הוי' דוקא והרצון שהי' ליצחק להמשיך לעשו עצמו שלא ע\"י יעקב הוא מפני שראה אותו מלמעלה למטה ע\"י בחי' לבונה שהוא בחי' המקיף ע\"כ רצה להמשיך בו בחי' גלוי המקיף בתוס' ורבוי אור. אך מ\"מ טעה בזה שאין עשו כדאי בבחי' זו כ\"א ע\"י יעקב שלפי שאם הי' החיות נמשך אל עשו יבלע ח\"ו כמקדם או שלא יהיה מבחי' עשו כלום אבל שיהא לאהפכא חשוכא לנהורא ומרירו למיתקא א\"א כ\"א ע\"י יעקב ז\"א דקדושה שע\"י יתברר מעשו ויוכלל בקדושה ולכן הסכים יצחק ג\"כ לברכת יעקב אח\"כ ולעשו אמר הנה משמני הארץ כו' משמני מקצת שמני (וליעקב א' ומשמני בתוס' וא\"ו) דהיינו מתמצית הנשאר משמן שנמשך אל הארץ שם יהיה מושבך בחי' פנימי' ומטל השמים של יעקב יומשך לך ג\"כ אבל אינו אלא מעל דהיינו בחי' מקיף בלבד (משא\"כ ביעקב ויתן לך) ובתנאי ואת אחיך תעבוד שתהי' בטל אל בחי' יעקב שע\"י יהי' עליי' דוקא כנ\"ל:"],[29,"<b>ועתה<\/b> יבואר הכתוב ראה ריח בני כו'. כי הנה יצחק רצה להמשיך בחי' מקיף ולבונה כנ\"ל וכל המשכה הוא ע\"י העלאת מ\"ן כנודע. והנה להמשכת מ\"ד של פנימי' די בהעלאת מ\"ן בבחי' פנימי' ⟦כ,ד⟧אבל להמשכ' מ\"ד של מקיף צ\"ל העלאת מ\"ן ג\"כ בבחי' מקיף."],[29,"והנה ריח הוא העלאת מ\"ן שהוא בחי' אור חוזר. והוא מהגבורות כמו שרואים שתפוח מתוק אין בו ריח. רק החמוץ וכל הדברים החריפים יש בהם ריח חזק. והוא לפי שהעלאת מ\"ן הוא בירורים מניצוצות שנפלו בשבה\"כ. ולכן בכל המצות לא נאמר ריח ניחוח כמו בקרבנות שהוא ע\"י שמעלין נפש הבהמה ומתהפך ועולה ונכלל באש שלמעלה."],[29,"והנה הריח משיב את הנפש דהיינו מה שהיה בתחלה בבחי' הסתלקות המוחין חוזר ומאיר כאדם שהוא נרדם וע\"י הריח הוא חוזר ומקיץ. דהיינו ע\"י השינה היה השכל בהעלם. ואח\"כ כשניער משנתו הנה השכל מאיר בו בגילוי והכל נעשה ע\"י הריח שהוא אור החוזר ממטה למעלה. וזהו ענין נח\"ר לפני שאמרתי ונעשה רצוני. והנה עשו לא היה בו בחי' גילוי פנימי' כי הפנימי' שלו נבלע כנ\"ל רק שהוא בחי' המקיף ולבונה. וזהו וירח את ריח בגדיו הוא בחי' המקיפים שיהיה מזה ריח הוא העלאת מ\"ן להמשיך המקיף מטל השמים:"],[29,"<b>כריח<\/b> שדה אשר ברכו ה'. הנה השדה הוא בחי' מל' דאצי' שיש בה ג\"כ בחי' העלאת מ\"ן ויש בזה ב' בחי' הא' היא העלאת מ\"ן בטבעה ומאליה וממילא כמ\"ש למען יזמרך כבוד ולא ידם. קארי תדיר לנהורא עלאה ולא שכיך כו' והוא העלאת מ\"ן לפנימי' דהיינו לעורר המשכת הקו. ויש העלאת מ\"ן שצריך סיוע מלמעלה שאין כח בה להעלות מ\"ן מעצמה. והוא בחי' מקיף שהוא בחי' גילוי אור א\"ס ב\"ה בעצמו (שהקו מאיר לתוך מקום החלל עצמו) והנה העלאת מ\"ן של בחי' פנימי' הוא בחי' בארה של מרים שהוא מעיין הנובע מאליו משא\"כ העלאת מ\"ן של המקיף כתיב באר חפרוה שרים. ויכרו שם עבדי יצחק באר. עבדי יצחק הן המשכות מבחי' יצחק שהוא עיקר האבות מבחי' בוצינא דקרדוניתא מקור הגבורות כמ\"ש כי אתה אבינו. ולכן כתיב ויריבו רעי גרר לאמר לנו המים שבחי' המקיף נמשך גם אליהם מלמעלה שאינו נבלע כמו בחי' פנימי' שלהם כנ\"ל. וזהו אשר ברכו הוי\"ה שהוא ע\"י סיוע מלמעלה כנ\"ל:"],[29,"<b>והנה<\/b> כ\"ז הוא הבנת הפסוק לפי דעתו של יצחק שהבין שעשו היה לפניו. אך באמת היה זה יעקב. ואיך יבואר בחי' זו על יעקב:"],[29,"<b>הנה<\/b> איתא במדרש וירח את ריח בגדיו. בוגדיו בחי' בעלי תשובה שהוא בחי' מקיף דמשכין ליה בחילא יתיר. שבזוהר אמר ע\"פ ואברהם זקן בא בימים כו'. זכאין אינון מארי דתיובתא דמשכין כו'. פי' למעלה מכדי שתוכל הנפש שאת שאין לו בחי' כלי להכיל."],[29,"וכמעשה דר\"א בן דורדייא. משא\"כ באברהם כתיב בא בימים. בחי' כלי ולבוש כו'. והעלאת מ\"ן כזה שהוא בחי' מקיף הוא מפני שמתבונן בגדולת א\"ס ב\"ה בעצמו ובכבודו. כי אני הוי\"ה לא שניתי כתיב רק הודו על ארץ ושמים. וירם קרן לעמו כו'. ונק' בחי' בע\"ת אף מי שאין עבירות בידו. רק צועק על הפירוד כו'. והוא בחי' ריח שהיא העלאת מ\"ן לבחי' מקיף להמשיך בחי' מקיף דלעילא מטל השמים כו':"],[29,"<b>אך<\/b> להבין כ\"ז והלא יעקב הוא בחי' קדושה ובלא\"ה נמשכים בו כל האורות עליונים א\"א ואו\"א כנ\"ל. אך הברכה היא בתוס' ורבוי המשכה מלמעלה מסדר ההשתלשלו' שאינו לפי ערך ההשתלשלו' כדי להיות ורב דגן ותירוש אלו הלכות ואגדות שנתלבשו בלבושים גשמיים זרעים בחסד כו' וכן כל התורה ספורי מעשיות כו' וכן נביאים שופטים מעשה דשמשון ופלגש בגבעה וכן כל מעשה המלכים וספורי מעשיות שבגמ' דרבב\"ח ודומיהן הכל מרומז בהן סודות התורה, ועד\"ז ג\"כ מעשה המצות שע\"י סוכה ולולב וציצית ותפילין גשמיים יהיה המשכת אוא\"ס ב\"ה שלמע' מעלה מהשתלשלו' שלפי ערך ⟦כא,א⟧וסדר השתלשלות בעשי' החיות מצומצם מאד ובכדי שיאיר אור רב מאא\"ס ב\"ה בעצמו ובכבודו הוא ע\"י יצחק דייקא שהוא שרש הגבורות בוצינא דקרדוניתא שהוא קו המדה שמודד להיות חכם כו' ומשם נמשך תוס' אור וגילוי גם בעשי' הגשמי'."],[29,"וזהו ויתן לך האלקים גם בבחי' צמצום וקאי ויתן על בחי' הוי\"ה האמור למעלה בפ' אשר ברכו ה' ואף גם זאת בלי דעתו של יצחק רק בא אחיך במרמה שא\"א להתלבש בבחי' הדעת וכענין שאמרו לאו בזכותא תליא מילתא ⟦כא,ב⟧אלא במזלא תליא מילתא כי ענין בזכותא הוא לפ\"ע ההשתלשלות שכך ראוי לו משא\"כ במזלא הוא למעלה מלפ\"ע אף שאינו ראוי כו' והיה צריך לזה לתקן חטא עה\"ד שהיה ג\"כ במרמה ופתוי של נחש שע\"י נתגשמו העולמות ונעשה עירוב גשמיות ברוחניות ולתקן זה עשה מהפוך אל הפוך והמשיך רוחניות ואורות העליונים שיהיה נמשך גם לגשמיות. משא\"כ אלו לא קבל יעקב הברכות היה נמשך מן התורה רק ברוחניות לבד כמו שהוא למעלה וכדה על שכמה כו':"],[30,"⟦כא,א⟧<b>ושבתי בשלום אל בית אבי והיה הוי' לי לאלקים והאבן הזאת אשר שמתי מצבה יהיה בית אלקים כו'.<\/b> וצריך להבין השייכות של האבן עם שם הוי' שכשהוי' יהיה לאלקים אז דוקא יהיה האבן בית אלקים כו'. גם צריך להבין כי לשון האבן הזאת הוא לשון נקיבה ומלת יהי' הוא לשון זכר."],[30,"ולהבין את כל הנ\"ל צריך להקדים ולבאר מ\"ש לעיל מניה ויפגע במקום ויקח מאבני המקום וישם מראשותיו וגו' וישם אותה מצבה כו' וצריך להבין ענין האבנים מה הן. וגם מה שהיו תחלה אבנים הרבה כמ\"ש ויקח מאבני המקום וגו'."],[30,"ויעקב עשה מהן אבן אחת כו'. אך הנה בריש הפרשה כתיב ויצא יעקב מבאר שבע וילך חרנה. פי' יעקב הוא בחי' יו\"ד עקב שהוא בחי' המשכת חכמה עילאה שהוא בחי' י' למטה מטה גם בבחי' עקביים."],[30,"וזהו ויצא יעקב מבאר שבע וילך חרנה שבחי' יעקב הוא הממשיך מבחי' באר שבע שהוא למעלה מעלה איהו וחיוהי וגרמוהי חד עד השתלשלות למטה מטה למדרגה היותר תחתונה שהוא בחי' חרן וכאשר יבואר לקמן בעז\"ה."],[30,"וכמ\"ש צוה ישועות יעקב. ישועות הם ש\"ע נהורין עילאין ובחי' יעקב מחבר וממשיך אותן למטה בבחי' עקביים ג\"כ. וגם ישועות הוא מלשון שעה כמ\"ש וישע ה' אל הבל וגו' שהוא בחי' ירידת והמשכת אורו ית' למטה מטה כו'. אך בהשתלשלות אור ה' כ\"כ בצמצומים רבים עד שבא גם למטה בבחי' חרן נעשה עלמא דפרודא לגמרי וכמ\"ש ונהר יוצא מעדן שהוא בחי' חכמה עילאה להשקות את הגן כו'."],[30,"ומשם יפרד שכשנמשך משם בהשתלשלות רבות וצמצומים רבים נעשים בחי' נפרדים בתכלית. ויעקב אע\"ה רצה להעלותם למעלה מעלה שיהי' גם למטה בחי' יחוד ובטול ממש כמו שהוא למעלה חיוהי וגרמוהי חד כו'."],[30,"ולזאת נאמר ויקח מאבני המקום כו'. כי הנה נודע שאבנים נקראו אותיות וכמ\"ש בס\"י שני אבנים בונות שתי בתים שלש אבנים בונות ששה בתים כו' להיות כמו שמאבנים הרבה נעשה בית אחד שיכולים לדור בתוכו כמו\"כ מאותיות הרבה נעשו תיבות שבהם התלבשו' השכל וגם כמו שהאבנים הם בחי' דומם שהוא מדרגה היותר תחתונה מכל הד' יסודות דצח\"מ כמו כן האותיות לגבי השכל המלובש בהם הם בחי' דומם בתכלי' שאינם מערך השכל כלל. נמצא מובן מכל הנ\"ל שאבנים נקראו אותיות וכמו\"כ הוא למעלה. דהנה כתיב בדבר ה' שמים נעשו כו'."],[30,"וכמ\"ש מלכותך מלכות כל עולמים. פי' שחיות כל העולמות שהם עולמות עד אין קץ וכמ\"ש היש מספר לגדודיו. הנה עכ\"ז מקור ושרש חיותם אינו אלא מבחי' מלכותו שהוא בחי' דבר ה' כו' המחיה ומהוה אותם מאין ליש תמיד. להיות שהם נבראים בע\"ג שיש גבול להשגתן ומהארץ לרקיע מהלך ת\"ק שנה כו'."],[30,"ואינם כלל בערך לגבי אור ה' שהוא בבחי' א\"ס המתגלה בעולמות עליונים. ולזאת אין יכולים לקבל חיותם רק מבחי' דבר ה' שהם אותיות שנבראו בהם שמים וארץ כו' שהם בחי' דומם לגבי אור א\"ס ב\"ה וכמ\"ש קדוש ה' ⟦כא,ב⟧צבאות וכמארז\"ל אות הוא בצבאות שלו ואף שהם אלף אלפין כמ\"ש אלף אלפין ישמשונה ורבו רבבן קדמוהי וגו' וכמ\"ש היש מספר לגדודיו. עכ\"ז מאחר שהם בעלי גבול חיותם אינו אלא מבחי' אות א' בלבד שהוא בחי' דומם לגמרי לגבי שם הוי' שהוא בבחי' א\"ס כו' כנ\"ל."],[30,"והנה השתלשלות כל העולמות ברבוי רבבות מדרגות תלוי הכל לפי אופן צירופי האותיות שבבחינת דבר ה' להתהוות נבראים פרטיים בעלי גבול ונפרדים כו'. ויעקב אע\"ה רצה להעלותם למעלה. לזאת ויקח מאבני המקום שהם אותיות הרבה ועשה מהן אבן אחת שהוא אות היו\"ד שזהו וישם מראשותיו כו' שכמו שלמטה באדם יש שכל ומדות והאותיות הם המלבישים לבחי' שכל ומדות שמתלבשים בהם. כמו\"כ למעלה יש בחי' חב\"ד וז\"ת רק שם הוא חכים ולא בחכמה ידיעא מבין ולא בבינה ידיעא ולאו מכל מדות אלין ששם הוא בבחי' יחוד ובטול בתכלית."],[30,"וכמ\"ש לך ה' הגדולה כו' וחיוהי וגרמוהי חד כו'. ובחי' דבר ה' הם האותיות שבהם מתלבשים חב\"ד ומדות שהם ע\"ס עליונות. ובחי' אות היו\"ד שהיא נקודה קטנה מרמז על היות שבו מתלבש בחי' חכמה שהוא בחי' אין ובטול בתכלית."],[30,"ואות הה\"א שהיא בחי' התפשטות אורך ורוחב מרמז על שהוא בחי' לבוש לבחי' בינה וכו'. וכמו\"כ שאר האותיות שבהם מתלבשים בחי' מדות העליונות. וזהו שיעקב עשה מכל האבנים אבן אחת שהוא אות היו\"ד להעלותן לבחי' חכמה עילאה."],[30,"ואזי אח\"כ וישם אותה מצבה הוא בחי' אות הוא\"ו שעשה והמשיך מבחי' י' לבחי' ו' להיות התלבשות בחי' חכמה עילאה למטה בבחי' תומ\"צ וכנודע תמונת אות הוא\"ו שעל ראשו נקודת היו\"ד ואח\"כ הולך ומתמשך למטה כמו כן אורייתא מחכמה עילאה נפקת ונמשך ומתפשט למטה בדברים גשמיים כו'."],[30,"וזהו ויצוק שמן על ראשה פי' שמן הוא בחי' חכמה עילאה וכמ\"ש שמן משחת קדש. להיות גלוי בחי' חכמה עילאה ממש למטה בבחי' מצבה הנ\"ל שהוא בחי' תורה ומצות שמלובשים למטה בדברים גשמיים המחליף פרה בחמור כו' כשר פסול כו' עכ\"ז יהיה בהם גילוי בחי' חכמה עילאה ממש כמו שהוא למעלה."],[30,"וכמארז\"ל מה להלן באימה וביראה אף כאן באימה וביראה. פי' מה להלן בשעת מתן תורה על הר סיני שהיו באימה וביראה שאז הי' בחי' גילוי בתכלית ששמעו מפי עצמות המאציל אנכי ה' אלקיך כו'. אף כאן היינו אף כמו שהתורה מלובשת למטה בדברים גשמיים יהי' ע\"י גילוי חכמה עילאה ממש כמו שהי' אז וכמ\"ש ואשים דברי בפיך כו'."],[30,"ולהיות גילוי כזה למטה הוצרך יעקב מתחלה להעלותן למעלה מעלה לבחי' סוכ\"ע. וכמ\"ש וירימה מצבה להיות כי נעוץ סופן בתחלתן ועי\"ז נעוץ תחלתן בסופן כו' שמדרגה היותר גבוה יותר יכולה לירד ולהתפשט מטה מטה כידוע:"],[30,"<b>וזהו<\/b> ושבתי בשלום אל בית אבי והי' הוי' לי לאלקים. שכל זה יהיה ע\"י העלאות והמשכות שממטה למעלה ומלמעלה למטה שהוא בחי' וישם מראשתיו כו' ואח\"כ ויצק עליה שמן כו' כנ\"ל כי הנה אבי ⟦כא,ג⟧קאי על יצחק וכמ\"ש כי אתה אבינו שלע\"ל יאמרו על יצחק כי אתה אבינו כו'."],[30,"והנה יצחק הוא מלשון צחוק ותענוג וכמ\"ש צחק עשה לי כו' כל השמע יצחק לי והוא לשון עתיד שיתגלה בחי' התענוג העליון שלמעלה והוא ע\"י בחי' הבירורי' שלמטה בבחי' אתכפיא ואתהפכא מחשוכא לנהורא ע\"י העלאות והמשכות כנ\"ל."],[30,"וכמו התענוג והצחוק שלמטה שאינו אלא מאיזו שינוי והתחדשות כמו למשל צפור המדברת וכדומה שאין דרכה וטבעה לדבר משא\"כ מאדם המדבר אין מקבלים תענוג כלל לפי שדרכו בתמידות לדבר. וכמו\"כ ממש למעלה. הנה בחי' יעקב הוא י' עקב שהוא בחי' ירידת והשתלשלות אלקות עד למטה מטה גם בבחי' עקביי' שהם עולמות הנפרדים לגמרי ובעלי גבול כו'."],[30,"וכמ\"ש ויצא יעקב מבאר שבע וילך חרנה שנמשך ונשתלשל בהשתלשלות וצמצומים כ\"כ להתהוות יש מאין בעלי גבול ועלמין דפרודי שהם בחי' נבראי' נפרדים שהם בחי' יש ונפרד בפ\"ע שנק' חר\"ן והוא מלשון נחר גרוני כו'. והיינו שהחיות אלקות הנמשך ומתלבש בהם שנק' בחי' גרון שהוא קול כנודע מכוסה ומוסתר בהם לגמרי עד שהם עלמין דפרודי וחשך לגמרי כאלו הם יש ונפרד בפ\"ע ואזי נק' חרן לשון נחר גרוני כו'. וכמ\"ש נאלמתי דומיה כו'."],[30,"והנה תכלית המכוון בירידת והשתלשלות אור ה' כ\"כ למקום חשך ועלמין דפרודי. היינו בכדי שיהי' אתכפיא ואתהפכא מחשוכא לנהורא כו' להפוך את כל המדות רעות שהם האהבה ורשפי אש של הבלי עולם או הכעס כו' להפכם שיהיו רק לה' לבדו ולהיות בבחי' בטול הרצון לה' לבד ולא בבחי' יש ונפרד בפ\"ע כו'. ונק' בחי' זאת בחי' תשובה שהוא בחילא יתיר כו' דהיינו המדות רעות שהם ברשפי אש להפכם ולהשיבם לה' לבד כנ\"ל (וזהו במקום שבעלי תשובה עומדין צדיקי' גמורים אין יכולים לעמוד). ועי\"ז נעשה תענוג גדול למעלה והוא מבחי' אתכפיא ואתהפכא מחשוכא לנהורא שלמטה. וזהו יפה שעה אחת בתשובה כו' להיות שע\"י בחי' תשובה דוקא נעשה התענוג למעלה כ\"כ שהוא ממש כמשל צפור המדברת כנ\"ל ואזי נעשה מבחי' חר\"ן רנ\"ה וכנודע על ענין חמץ ומצה שמאות החי\"ת של חמ\"ץ נעשה ה\"א כמ\"ש בזהר פ' פנחס ע\"פ גער חי\"ת קנה כו' ונעשה בחי' מצה. כמו\"כ מחרן נעשה רנה כמ\"ש באבוד רשעים רנה שהוא בחי' התענוג שנעשה למעלה מבחי' אתכפיא ואתהפכא כנ\"ל."],[30,"והנה בחי' התענוג הזה יתגלה לעתיד דוקא שאז ואת רוח הטומאה אעביר כו' שלא יהיה עוד בחי' חשך ובירורי' כמו שהוא עתה בעליות וירידות אלא כמ\"ש בחריש ובקציר תשבות כמבואר במ\"א."],[30,"ויהיה בחי' גילוי אור ה' למטה בבחי' יחוד וביטול בתכלית כמו שהוא למעלה בעולמות עליונים דאיהו וחיוהי וגרמוהי חד כו' שעתה הוא מאין ליש כו' משא\"כ לעתיד יהיה מיש לאין בבחי' ביטול ואתהפכא כו'."],[30,"ואזי יתגלה בחי' ענג העליון שהוא בבחי' א\"ס והוא בחי' יום הז' יום שכולו שבת ומנוחה לחיי העולמים שהוא בחי' גילוי ענג העליון כנודע שנעשה מהבירורים שלמטה בשיתא אלפי שנין כו'. וזהו ושבתי כו' אל בית אבי שהוא בחי' חזרה והשבה של בחי' יעקב מבחי' חר\"ן כנ\"ל לבחי' רנה שנק' בית אבי שהוא בחי' יצחק שהוא בחי' הצחוק והתענוג העליון שיתגלה לעתיד מבחי' אתכפיא ואתהפכא הנ\"ל:"],[30,"<b>וזהו<\/b> שיאמרו לעתיד על יצחק דוקא כי אתה אבינו להיות כי זהו תכלית המכוון בירידת והשתלשלות העולמות כדי שעי\"ז יהיה צחוק ותענוג למעלה כנ\"ל. וזהו ושבתי בשלום כו'. כי בחי' ענג הנ\"ל שיתגלה לעתיד הוא דוקא ע\"י בחי' העלאות והמשכות שהם בחי' הבירורים למטה בבחי' אתכפייא ואתהפכא כנ\"ל שנקרא בחי' שלום. להיות כי שלום הוא המחבר שני הפכים וכמ\"ש עושה ⟦כא,ד⟧שלום במרומיו. שמיכאל שר של מים וגבריאל שר של אש כו'."],[30,"והנה כתיב שלום שלום לרחוק ולקרוב והיינו ב' בחי' שלום שלום מלמטה למעלה והיינו לרחוק שנעשה קרוב שהוא בחי' העלאה ממטה למעלה. ושלום מלמעלה למטה היינו בחי' ירידת והמשכת אלקות למטה בבחי' תורה ומצות כמבואר לעיל במ\"ש ויצק שמן כו'."],[30,"וע\"י ב' בחי' שלום הנ\"ל שהם בחי' אתהפכא מחשוכא לנהורא שלא יהיו בבחי' עלמין דפרודי רק בבחי' יחוד וביטול כמו שהוא למעלה בעולמות עליוני' ממש ואזי אשוב אל בית אבי שיתגלה ממילא בחי' הענג העליון שהוא בבחי' א\"ס ממש למעלה מעלה מהשתלשלות העולמות במדרגות רבות מעלה ומטה וחשך ואור. משא\"כ לגבי עצמותו ומהותו ית' קטן וגדול שוים ממש בלי שינוי וכחשכה כאורה ממש."],[30,"ואז והיה הוי' לי לאלקים כו'. כי הנה כתיב כי שמש ומגן הוי' אלקים שכמו שהמגן הוא נרתק להשמש ומכסה ומסתיר על אור השמש כמו\"כ שם אלקים הוא בחי' נרתק לשם הוי' ומכסה ומסתיר עליו להיות נבראים בעלי גבול ונפרדים בפ\"ע משא\"כ שם הוי' הוא בחי' המשכת אור ה' למטה כו'."],[30,"והנה כ\"ז הוא בבחי' השתלשלות מעלה ומטה וחשך ואור אבל לעתיד שיתגלה בחי' ענג העליון שהוא למעלה מעלה מבחי' ההשתלשלות והוא למעלה מעלה מבחי' שם הוי' ושם אלקים ואזי מה שעתה הוא בחי' שם הוי' יהיה אז בחי' אלקים לגבי בחי' ענג העליון הנ\"ל ואזי והאבן הזאת אשר שמתי מצבה כנ\"ל יהיה בית אלקים שיהיה בית וכלי לבחי' אלקים דלעתיד שהוא בחי' הוי' עתה. וכל אשר תתן לי הוא לשון עתיד היינו כל עליות שיהיו לעתיד הכל עשר אעשרנו לך בבחי' מעשר כנודע וד\"ל:"],[30,"קיצור (א) <b>הנה<\/b> יעקב המשיך היו\"ד ח\"ע לבחי' עקביי' וזהו ענין יציאת יעקב מבאר שבע יסוד אי' לבחי' חרן כדי להעלות בירורי נוגה והיינו מה שלקח מאבני המקום שהם בחי' אותיות דבר ה' המלובשים בדצ\"ח ועשה מהם אבן אחת הוא בחי' יו\"ד שזהו וישם מראשותיו (ע' זהר ח\"א דע\"ב ופ' ויצא קנ\"א ופ' ויחי רל\"א ובמ\"ש ע\"פ אבן ישראל) ואח\"כ וישם אותה מצבה המשכת בחי' ו' שנמשך מהיו\"ד והוא ענין אורייתא מח\"נ ויצק עליה שמן להיות מה להלן באימה ויראה אף כאן באימה ויראה: (ב) ועי\"ז ושבתי בשלום אל בית אבי בחי' יצחק כי אתה אבינו והוא הצחוק והתענוג שיהיה לע\"ל מבירורים אלו והיינו ע\"י אתכפיא ואתהפכא נתברר מבחי' חר\"ן ונהפך החי\"ת לה\"א להיות רנ\"ה בחי' תענוג (ועד\"ז בענין יצ\"מ מיצר הגרון ע\"ד בחי' חרן נחר גרוני כו' וימררו חיי אבותינו וכשנעשה יצ\"מ הוא בחי' מצה משא\"כ חמץ כענין ההפרש בין חרן לרנה): (ג) וגילוי ענג זה ע\"י ב' בחי' שלום לרחוק ולקרוב ואז שם הוי' יהיה רק בבחי' אלקי' לגבי גילוי ההוא ולפיכך האבן הזאת שהיא בחי' המל' המקבלת משם הוי' יהיה בחי' בית אלקים (וגם י\"ל כיון דלע\"ל יאמרו ליצחק כי אתה אבינו ע\"כ שייך בחי' זו בשם אלקים וז\"ש צחוק עשה לי אלקים):"],[31,"ביאור על הנ\"ל"],[31,"<b>והיה הוי\"ה לי לאלקים והאבן הזאת אשר שמתי מצבה יהיה בית אלקים.<\/b> להבין ענין תפלה ובקשה זו שהוי\"ה יהי' בבחי' אלקים והאבן בבחי' בית אלקים. וכדי להבין איך תהיה האבן במדרגה גדולה כ\"כ להיות מכון ומשכן להשראת קדושה עליונה עד שיהיה חל שם שמים על האבן שתהיה נק' בשם בית אלקים. הנה צריך להבין ענין הפרשה כולה ויצא יעקב כו' והענין דכתיב ⟦כב,א⟧צוה ישועות יעקב בחי' יעקב נקרא ישועות וביאור מלת ישועות הנה שרש התיבה הוא ש\"ע ושאר אותיות הם נוספות בתיבה כלומר שע\"י בחינת יעקב מתגלין ש\"ע נהורין עילאין וגם ש\"ע הוא מלשון וישע ה' אל הבל שהוא לשון הפנה דהיינו שכל פינות והמשכות עליונות פונות ונמשכות ע\"י בחי' יעקב יו\"ד עקב."],[31,"וענין נהורין והמשכות הללו היינו גילוי ההארות והמשכות מאור א\"ס עצמו שכשמו כן הוא אין לו סוף כו'. ואינו בגדר עלמין כלל וכולא קמיה כלא ממש חשיב ולית מחשב' תפיסא ביה ואין ערוך אליו כו'. כי מלכותך מלכות כ\"ע והודו וזיוו על ארץ ושמים כו' זיו והארה בעלמא המתלבש' ומתפשטת בתוך עלמין להוות' ולהחיותם להיות חיים וקיימים מאין ליש בבחי' העלם והסתר אור א\"ס ב\"ה עצמו שלא יבטלו העולמות במציאות ויחזרו להיות אין ואפס כמו שהיו דהיינו ע\"י כמה צמצומים והתלבשות שונות בירידת המדרגות כדרך וסדר ההשתלשלות אבל אור א\"ס ב\"ה בעצמו ובכבודו רם ונשא כו' והוא למעלה מעלה מבחינת ההשתלשלות וע\"י בחי' יעקב יו\"ד עקב נמשך אא\"ס ב\"ה שלמעלה מבחי' ההשתלשלות שיאיר למטה בגילוי הנפש אלקות שבכל א' מישראל להיות גילוי אור א\"ס ב\"ה ממש על נפשו."],[31,"והיינו ע\"י שלקח מאבני המקום וישם מראשותיו. אבנים הן אותיות כמ\"ש בס\"י שני אבנים בונות שתי בתים. והטעם שנקראו אותיות בשם אבנים הוא כי כמו שע\"י כמה אבנים נבנה בית לשבת אדם כו' כך ע\"י כמה צירופי אותיות נעשי' תיבות ומכמה צירופי תיבות נעשה ענין שלם שמתוכו מובן ומושג איזה השכלה והשגה והרי השכל שורה ומתלבש באותיות הללו וכתפארת אדם לשבת בית ע\"י צירופי אבנים ועוד טעם אחר כי כמו שהאבנים הם דומם ואין להם ערך ויחוס לאדם הדר בבית שנבנה מהאבנים כך האותיות הן בחי' דומם לגבי השכל השורה ומתלבש בהם ואין להם ערך ויחוס אליו ולכן בטלים הם לגבי השכל (ועמ\"ש בפ' בראשית בד\"ה להבין בתוספת ביאור ענין וייצר) ולכן נק' הוי' צבאות אות הוא בצבא דילי' שכל העולמות והברואי' נתהוו מבחי' אותיות שבעשרה מאמרות שנברא בהם העולם יהי אור יהי רקיע כו'. וכל צבא השמים העליונים אלף אלפין ורבוא רבבן ולגדודיו אין מספר הם בטלים לגבי אור א\"ס ב\"ה כבטול האותיות שהן בחי' דומם לגבי השכל מאחר שהם בחי' גבול ת\"ק שנה כו' ונבראים ומחודשים מאין ליש הרי אין ערוך אליו ית' וכנודע ענין הערך במספר שמספר א' לגבי אלף אלפים כו' יש לו איזה ערך ויחוס משא\"כ אליו ית' שהוא א\"ס ב\"ה אין ערוך כלל ולכן נק' אות הוא בצבא דילי' שכל הצבאות אינן אלא בחי' אות א' לגבי אור א\"ס ב\"ה."],[31,"והנה באבני המקום שהם בחי' אותיות כתיב וישם מראשותיו שהגביה והעלה אותם למעלה מעלה מבחי' ההשתלשל' דהיינו לבחי' סוכ\"ע כי לפי שהאותיות הן בחי' דומם לכך יש להם כח ויכולת לעלות למעלה מעלה כנודע שנעוץ תחלתן בסופן דייקא וסוכ\"ע הוא כמשל העיגול שממטה נעשה מעלה. וכמ\"ש ומתחת זרועות עולם."],[31,"והנה כתיב ויקח מאבני המקום ולא כל אבני לפי שלא כל האותיות יש להן כח זה אלא אות היו\"ד שהוא בחי' כלי לחכמה וחכמה הוא כח מ\"ה בחי' בטול ולכך שורה שם ומתגלה אור א\"ס ב\"ה הסוכ\"ע כי הוי' בחכמה כו' ואין אור א\"ס ב\"ה שורה ומתגלה אלא במי שבטל כו'. וזהו האבן אשר שם מראשותיו (ועמ\"ש ע\"פ מאמר הרע\"מ פ' כי תשא בענין אבנא למשקל בה דא י') ואח\"כ וישם אותה מצבה וכתרגומו ושוי יתה קמא שהוא כמ\"ש קמה אלמתיוגם נצבה שמה שהיתה האבן מונחת למטה בארץ אח\"כ הקים אותה והגביה אותה עוד ממטה למעלה והיינו עליי' אחר עליי' לבחי' ומקורות י\"ג מדות רחמים עליונים שהן בחי' יודי\"ן ווי\"ן כי מקום יניקת השערה והגומא שלה הוא בחי' י' ⟦כב,ב⟧והשערה עצמה שהיא המשכה היא בחי' ו' וזהו וישם מראשותיו וישם אתה מצבה שמתחלה כאשר שם מראשותיו היא בחי' יו\"ד ואח\"כ נעשה מצבה הוא בחי' וא\"ו וכל בחי' הללו הם בחי' העלאה ממטה למעלה והיינו התעלות חכמה שבנפש לאור א\"ס ב\"ה השורה ומתגלה בה כי הנפש היא בחי' נברא ומחודש מאין ליש בבחי' אותיו' כו' וצריך להעלות' ממטה למעלה לאור א\"ס ב\"ה הסוכ\"ע וישוב אל ה' וירחמהו מבחי' י\"ג מדות הרחמים והעלאה זו היא בבחי' חכמה דוקא כ\"ח מ\"ה:"],[31,"הגה\"ה"],[31,"<b>לכאורה<\/b> אינו מובן כי היודי\"ן שבת\"ד הוא גבוה מהוי\"ו כמ\"ש לעיל כי מקום יניקת השערה והגומא שלה הוא בחי' יו\"ד דהיינו מקום יניקתה ממו\"ס שהוא הגבה מאד נעלה מהשערות עצמן שהן בחי' ו'."],[31,"והרי בחי' וישם אתה מצבה משמע שהוא עלייה אחר עלייה למעלה מבחי' מראשותיו שהוא בחי' יו\"ד. וזהו תרתי דסתרי. אך פי' מראשותיו הוא בחי' חכמה דאצילות ואח\"כ וישם אתה מצבה שנעשית בחי' ו' הוא בחי' אבא יונק ממזלא שבחי' השערות דת\"ד שהן ווי\"ן גבוה מהיו\"ד דח\"ע. אח\"כ ויצק שמן על ראשה היינו המשכה ממו\"ס ממש לתוך המזלות כו' ומזה ממש נמשך הגלוי למטה בהלכו' שבתורה שבע\"פ ששרשן מנימין דמו\"ס וע\"ז נאמר סלסלה ותרוממך כו':"],[31,"<b>אך<\/b> אין זה תכלית המכוון רק שאח\"כ ויצק שמן על ראשה שמן היינו המשכת חכמה עילאה שהיא התורה ורצונו ית' שנמשכו ע\"י בחי' יעקב יו\"ד עקב כמ\"ש ויקם עדות ביעקב ותורה שם בישראל להיות בעסק התורה שלמטה בגשמיות המחליף פרה בחמור כו' גילוי המשכת חכמה עילאה שכל פרטי הלכות שנפרדו הם יסודתם בהררי קדש עליון חכמה עילאה שכך חייבה חכמתו ורצונו ית'."],[31,"ואי לזאת יהי' עסק התורה ג\"כ עד\"ז להמשיך חכמה עילא' בנפשו ועי\"ז נעשה אתכפייא סט\"א ואתהפכא כו'. ולכן ארז\"ל מה להלן באימה וביראה אף כאן באימה כו' שתפול על האדם אימה ופחד בעסקו בתורה כמו בשעת קבלתו בהר סיני."],[31,"והנה שם בהר סיני כל העם ראו את הקולות ואת הלפידים וכו' פנים בפנים דבר ה' עמכם כו'. והאיך ימשיך כל אדם יראה זו עליו בכל זמן אלא כאשר ישים האדם אל לבו שהתורה שהוא לומד היא המשכת חכמה עילאה ושם שורה ומתגלה אור א\"ס ב\"ה שלמעלה מעלה מגדר ההשתלשלות וקמיה כחשיכה כאורה מעלה ומטה רוחניות וגשמיות שוין א\"כ אין כאן הסתר פנים כלל ע\"כ מה להלן כו' הכל שוה."],[31,"והנה להבין תכלית ירידת יעקב יו\"ד עקב להיות הש\"ע נהורין בגילוי למטה וליקח מאבני המקום להעלותם למעלה ולהמשיך אח\"כ בחי' שמן הוא בחי' חכמה עילאה מלמעלה למטה. וירידה זו הוא מ\"ש ויצא יעקב מבאר שבע. באר הוא מקור ומעיין הנובע ז' מדות עליונות לך ה' הגדולה והגבורה כו' שהן בחי' לך בחי' ביטול. וילך חרנה חר\"ן (ע\"ה) בגימ' גרו\"ן רק בחי' גרו\"ן היינו כשהקול יוצא כדרכו בלי עכוב ובלי מונע אבל חר\"ן אותיות נחר היינו מ\"ש יגעתי בקראי נחר גרוני. והיינו כשגובר בו יסוד האש כי הקול כלול אש רוח ומים. רוח הוא עיקר התפשטות הבל הלב ומים היינו לחלוחית הריאה ואש הוא המחלק את הקול להיות ההפסק להתחלק בה' מוצאות הפה כלי הדבור."],[31,"וכשגובר יסוד האש ביותר הוא המפסיק את הקול עד שאינו יכול לצאת במשך ההעברה כדרכה. וכך הוא בחי' חרן היינו בחי' המפסיק את הקול שהוא ההמשכה מחיות ואור א\"ס ב\"ה שלא להיות ההמשכה כדרכה בקדושה דוקא אלא שיש גם לקליפות וס\"א יניקה ואחיזה בהמשכה זו ואזי נק' בבחי' נאלמתי דומיה שנפסק הקול וההמשכה ונעשה בחי' נפרד ובחי' זו ⟦כב,ג⟧הוא בין בהנהגת העולמות שהוא ענין גלות ישראל ושעבוד מצרים ובבל מחמת תגבורת האש ותוקף הדין ובין בכל נפש מישראל בעבודת ה' שעסק התורה שלו הוא בבחי' נפרד ולא בבחי' ביטול לאור א\"ס ב\"ה להיות גילוי חכמתו כו' מחמת תגבורת האש וחמימות שמצד גופו ונפש הבהמית אשר נמשך אחריהם. אך הנה תכלית ירידה זו של בחי' יעקב מאגרא רמה מבאר שבע מקו' מדות העליונות שהן ביטול אליו ית' לך ה' הגדולה כו' לבירא עמיקתא מקום החרן המפסיק ומעכב את קול ההמשכה להיות בחי' נפרד. הוא כדי להיות אתכפיא ואתהפכא ואזי נעשה מחרן רנה כי החי\"ת נפסק ונעשה ה\"א. כמ\"ש בזהר ע\"פ גער חית קנה שמחמץ נעשה מצה."],[31,"וזהו ושבתי בשלום אל בית אבי ושבתי מחר\"ן. אל בית אבי זהו בחי' יצחק ויצחק נק' ע\"ש צחק עשה לי אלקים והוא בחי' רנ\"ה שנעשה מחר\"ן וכתיב כל השומע יצחק לי יצחק הוא לשון עתיד דהיינו בביאת המשיח ב\"ב שאז אהפוך אל עמים וגו' דכד אתכפייא ואתהפכא אזי נעשה בחי' צחוק וחדוה כמו עד\"מ צחוק המלך והשרי' מענין התהפכות דבר רחוק וזר כמו מצפור מדברת שזהו דבר חידוש משא\"כ מאדם המדבר שדרכו בכך לא שייך צחוק."],[31,"ולכן ארז\"ל במקום שבע\"ת עומדין כו' משום דאתהפכא חשוכא כו'. וגם ארז\"ל אם ישראל עושין תשובה נגאלין כו' שזהו תכלית ביאת המשיח להיו' הצחוק והחדוה כד אתכפייא סט\"א ואתהפכא חשוכא לנהורא. וזהו מארז\"ל שלעתיד יאמרו על יצחק כי אתה אבינו שתכלית ירידת הנשמה בגוף בעוה\"ז ותכלית ירידת ישראל בגלות ושעבוד ודוחק פרנסה הוא כדי שיעלו ויבאו ויגיעו לבחי' יצחק הוא הצחוק והחדוה כו':"],[31,"<b>אך<\/b> כיצד ישוב מבחי' חרן לבחי' יצחק הנ\"ל הנה לזה אמר הכתוב בשלום כי שלום הוא המחבר ומקשר ב' הפכים כמ\"ש עושה שלום במרומיו בין מיכאל כו' שלום שלום לרחוק שנעשה קרוב כו' ובשלום ב' שלום ממטה למעלה וממעלה למטה כמ\"ש במ\"א."],[31,"והנה כשיתגלה הצחוק העליון לעתיד כד אתכפיא ואתהפכא דהיינו שלא יהיה שליטה ויניקה לקליפות וסט\"א כלל וכמ\"ש ואת רוח הטומאה אעביר מן הארץ. אזי יזדכך חומריות העולם וגסותו שלא יהיה בבחי' יש ודבר נפרד בפ\"ע רק הכל יוכלל בבחי' אין כי זהו תכלית בריאת העולמות מאין ליש כדי לאהפכא מבחי' יש לבחי' אין ואזי והיה הוי' לי לאלקים. כי הנה אלקי' היינו ההעלם והצמצו' להיות העולמות נבראים מאין ליש והוי\"ה היינו בחינת פנימיות אור א\"ס ב\"ה המחי' ומהוה כו' וכמ\"ש כי שמש ומגן הוי\"ה אלקים שאלקי' נעשה בחי' מגן לשם הוי\"ה שהוא בבחי' השמש כו'. אך כל זה הוא בבחינת ההשתלשלות וירידת המדרגות שהוא בבחי' זיו והארה שמאור א\"ס ב\"ה להוות ולהחיות נבראים כסדר ירידת השתלשלות המדרגות מדרגה אחר מדרגה. שמדרגות עליונים מקבלים אור היותר עליון ורוחני כו' וכל מה שלמטה מטה מתצמצם ומתלבש כו'. אבל לע\"ל כשיתגלה הצחוק העליון שהוא מבחי' אתהפכא כו' יהיה גילוי אא\"ס ב\"ה בעצמו ובכבודו שלמעלה מעלה מבחינת השתלשלות כי עין בעין יראו כו' וראו כל בשר כו' ובאו במערות צורים ובמחילות עפר מפני פחד ה' וגו'."],[31,"ואז יהי' בחי' הוי\"ה שהוא אור א\"ס ב\"ה הנמשך ומתפשט להתלבש בתוך עלמין בסדר ההשתלשלות. נחשב בחי' אלקים דהיינו בחי' צמצום שבאמת אין זה אלא זיו והארה מצומצמת לגבי אור א\"ס ב\"ה בעצמו ובכבודו שלפניו מעלה ומטה שוין וכחשיכה כאורה."],[31,"והאבן הזאת אשר שמתי מצבה הוא בחינת יו\"ד כלי החכמה שמבחי' אותיות בחי' דומם דהיינו בחי' התהוות מאין ליש רק לפי אשר שמתי מצבה שהגבהתי והעליתי כו' לכך יהי' לה כח ויכולת להיות בית אלקים שיהיה בחי' אלקים זה שהוא אוא\"ס ב\"ה שבתוך ⟦כב,ד⟧עלמין שורה ומתגלה בבחי' אותיות הללו והאותיות תהיינה בבחי' משכן ומכון לשבתו ית'."],[31,"וכל זה הוא ע\"י בחי' יעקב יו\"ד עקב צוה ישועות יעקב גילוי הש\"ע נהורין שבהן וע\"י נזכה לכל בחי' האלו. וכל אשר תתן לי עשר אעשרנו לך. הענין הוא כי הנה נודע שיהיה עילוי אחר עילוי לאין קץ ימות המשיח ותחה\"מ כמה שמיטין ויובלות כו' וכל עילוי גדול מחבירו. אך קודם העילוי שאחר העילוי צריך להיו' נשאר מעילוי הראשון בבחי' אתעדל\"ת לאתעדל\"ע שבעילוי הב' ואתעדל\"ת זו הנשארת מן העילוי הראשון נק' בחי' מעשר."],[31,"וז\"ש וכל אשר תתן לי לעתיד דהיינו כל העליות שיהיה עד אין קץ עשר אעשרנו ויהי' הרבה מעשרות לכל עילוי בחי' מעשר בפ\"ע ותמיד עשר אעשרנו עד שיגיע לך לבחי' אור א\"ס ב\"ה עצמו וכמו שהוא ית' א\"ס כך יהיו עליות עד א\"ס והכל ע\"י בחי' יעקב יו\"ד עקב כו' כנ\"ל וד\"ל:(ובענין מ\"ש בפי' עשר אעשרנו ואתעדל\"ת זו כו' נק' בחי' מעשר כו'. נראה כי הכתר הוא הממוצע בין עולם העליון לעולם התחתון שהוא סוף בחי' עליונה ומקור וראש לבחי' תחתונה כמו מלכות דאצי' כתר לבריאה ומלכות דבריאה כתר ליצירה כו'. ולכן הנה להיות עליית העולמות שיתעלה העשייה בקדוש' היצירה ממש הוא ע\"י אמצעות הכתר דעשייה שהוא בחי' מעשר מע\"ס דעשיי'. והענין כי כתר הוא לשון שתיקה כמו כתר לי זעיר. ושתיקה הוא בחינת בטול וע\"ז נאמר יונת אלם כו'. והוא בחינת בעמדם תרפינה כנפיהן. וע\"י בטול זה יוכל להתעלות אח\"כ ליצירה כי א\"א להיות עליי' ממהות למהות כי אם שיוכלל תחלה בבחי' אין ממש וזהו ענין העמוד שבין ג\"ע התחתון לג\"ע העליון כו' וכמו צמיחת התבואה מזרע הנזרע בארץ הוא ע\"י שמתחלה מתבטל מהות הזרע ונעשה בחי' אין רק שנשאר כחו בכח הצומח ועי\"ז אח\"כ נעשה הגידול נפלא יותר מהיש שהי' תחלה כו'. ועד\"ז עליי' יצירה בבריאה צ\"ל תחלה בבחינת בטול ואין והוא בחי' כתר דיצירה כו' וזהו ענין אשר שם שמות בארץ בחי' וחד חרוב ומה שהוא בבחי' אלף השביעי ולא בבחי' עשירית היינו כי היכל ק\"ק שהוא היכל השביעי כולל ג\"ר אבל עיקר העליי' ע\"י הכתר כו'. וע\"ד זה יש עליות אין קץ. ומ\"ש עשר אעשרנו ב' עישורין היינו כי הכתר כלול מב' פרצופין עתיק וא\"א כו' שהוא בחי' תחתונה שבמאציל ושרש הנאצלים כו' וב' בחי' אלו יחד נק' חומש כמ\"ש ונתתם חמישית לפרעה כמ\"ש במ\"א):"],[32,"<b>וללבן שתי בנות וגו'.<\/b> הנה לאה ורחל הם אותיות המחשבה ואותיות הדבור. שהם עלמא דאתכסיא ועלמא דאתגליא (עיין לקמן בד\"ה בכ\"ה בכסליו בפי' ושם ה' קטנה רחל) וזהו ענין בארצות החיים. ב' ארצות. שבזמן שבהמ\"ק היה קיים היו שני הבחינות מאירים בא\"י. והעיקר היה בחי' רחל (שנקראת עקרת הבית) כי המחשבה מתלבשת בתוך הדבור והדבור היה מתגלה. ולפי שרחל שהוא בחי' הדבור הוא עלמא דאתגליא לכך היה אז בא\"י גילוי אלקותו ית' שהיו חכמים גדולים בעלי רוה\"ק ונביאים (וכמו שפרש\"י גבי יונה ויחזקאל שאין הנבואה שורה אלא בא\"י) ובפרט בהמ\"ק והשראת השכינה בקה\"ק ואורים ותומים ועבודת הקרבנות שהי' יורד אש שלמעלה. משא\"כ אחר חורבן בהמ\"ק שגלו ישראל וגלתה עמהם השכינה. שהיא בחי' רחל שהיא בבחי' גלות בע' שרי' ואינה מאירה כלל מערך הגלוי שהיתה מאירה בזמן הבית שהי' הדבור מתגלה משא\"כ עכשיו כתיב כרחל לפני גוזזי' נאלמה. והעבודה היא בדרך בירורים כו' (וכמ\"ש ע\"פ במדבר סיני) ומ\"מ נשאר מאיר בא\"י בחי' לאה והיא מדרגה יותר גבוה מבחי' רחל ⟦כג,א⟧וכמשל המחשבה שהיא רוחניות ונעלית מן הדבור (שהיא אינה בגלות כי רחל נק' מ\"ם פתוחה שיש ממנה פתח ומבוא ליניקת החיצונים בזמן הגלות משא\"כ מבחי' מ\"ם סתומה. ושם הוא שרש לאה עיין בזהר ר\"פ תרומה דף קכ\"ו ב' ודף קכ\"ז) אך לפי שהוא עלמא דאתכסיא והעלם לכך אין הגילוי אלקות עכשיו בא\"י מערך הגילוי שהי' בזמן בהמ\"ק קיים. ומ\"מ הצדיקים הגדולים אשר בארץ יכולים להשיג עכשיו בא\"י השגות עליונות יותר אפי' ממה שהשיגו צדיקים כמותם בזמן הבית (מאחר שההשגה היא בבחי' מחשבה עליונה כמו שהיא עדיין למעלה מהתלבשות בעולם הדבור) וכמו האר\"י ז\"ל שהשיג השגות עצומות מה שלא השיגו צדיקים גדולים בדורות הקדמונים. ולהבין מ\"ש כי שנואה לאה כו'. הרי יעקב השיג ודאי בעלמ' דאתכסי'. אך הענין כי יעקב נק' בריח התיכון המבריח מן הקצה אל הקצה. פי' שהוא הממשיך אור א\"ס ב\"ה מן הקצה עליונה (היינו הקו הבוקע החלל כמ\"ש במ\"א) מבחי' כתר למטה ולכן נאמר בו תוספת וי\"ו ואלקי יעקב. וכן והנורא שמייחד ומחבר חו\"ג ע\"י המשכת והארת האין והיינו ע\"י בחי' בטול. וכל ההמשכו' שלו הוא עד הקצה התחתונה. דהיינו בבחי' מלכות עלמא דאתגלייא. וזהו ויאהב (יעקב) גם את רחל מלאה שכל תשוקתו היה להיות גילוי אור א\"ס ב\"ה למטה בעלמא דאתגלייא שעי\"ז יוכלו הכל לקבל משא\"כ מבחי' עלמא דאתכסייא כו' ולכן כתיב וישק יעקב לרחל על דרך שנקוד על וישקהו דהיינו שבחי' חב\"ד שהוא זיווג נשיקין ואתדבקו' רוחא ברוחא עד\"מ הנשיקין שבאין מפנימית האהבה (עמ\"ש במ\"א ע\"פ ישקני מנשיקות וע\"פ אמצאך בחוץ אשקך) וגם בחי' זו המשיך ברחל. וז\"ש אעבדך שבע שנים ברחל בתך הקטנה כי לבן הוא בחי' לובן העליון מקור החסדים שכולו רחמים פשוטים דלית שמאלא בהאי עתיקא רק שלמטה נשפל בלבן גשמי ומ\"מ כתיב כלו הפך לבן טהור הוא אפי' הנגע כו' ועל לבן כתיב וישכם לבן בבקר שבכ\"י מתגבר ונמשך אור החסד עליון."],[32,"וינשק לבניו ובנותיו שנמשך בכל פרצופי האצי' זכרים ונקבות. ואח\"כ ולבן שב למקומו למעלה מעלה ויעקב הלך לדרכו להמשיך בחינת לובן העליון הנ\"ל למטה מטה ברחל בתו הקטנה בחי' דבור כו'. ולכן היתה רחל עקרה כי ההולדה מבחי' הדבור הוא להיות הגילוי בבי\"ע וא\"א להיות הולדה וגילוי בבי\"ע שהרי הנבראים הם נפרדים וא\"א להתגלות להם בחי' לובן העליון הנ\"ל. (ומש\"ל דרחל נק' עלמא דאתגלייא מ\"מ להיות הגילוי ע\"ד בחי' לידה הוא קשה ביותר כו' ויש חילוק גדול בין שארי השפעות לבחי' לידה שהוא גילוי עליון יותר ועמ\"ש בזוהר פ' פנחס דרמ\"ט) אבל לאה שהיא המחשבה ילדה ששה בנים שהם הספי' שבאצי' עצמו ששם היה שרש השבטים ולכן נק' שבטי יה. יהודה הפעם אודה בחי' בטול והודאההרי הוא נמשך ומסתעף מן המחשבה דוקא. וכן ראובן ושמעון ראיה ושמיעה הוא ג\"כ למעלה מבחי' הדבור אלא מן המחשבה הן נמשכים כו' (כמ\"ש במ\"א ע\"פ יהודה אתה כו') וגם לוי שהוא בחי' התקשרות כמ\"ש הפעם ילוה כו' נמשך ונולד ג\"כ מן המחשבה כנראה בחוש במי שהוא בעל מחשבה שאינו מרגיש כלל בעסקים החולפים לפניו מחמת גודל התקשרות שיש לו בהמחשבה. וכמ\"ש במדרש בעובדא דר' חייא רבה. וכן גבי רבא (בפ' אר\"ע) דהוה מעיין בשמעתי' כו'. ולכן יצא ממנו משה שהיה כבד פה וכבד לשון דהיינו שלגודל התקשרותו בבחי' בטול ונחנו מה לא היה יכול להיות משפיע כו' שהיא בחי' הדבור כו' ועיקר ההפרש בין התקשרות דלוי שהוא בחי' בטול ובין הודיה דיהודה שהוא ג\"כ בחי' בטול הוא כי יהודה הוא בחי' הבטול בגילוי כענין מודים ⟦כג,ב⟧שכורע ומשתחוה ולכן יצאו ממנו מלכי בית דוד שבטולם הוא בחי' הבטול שבהתגלות וחיצוניות. אבל לוי שהוא בחי' ההתקשרות והבטול בפנימיותו ועצמותו הגם שבחיצוניות אינו נגלה כלל וכענין בטול דצבא השמים לך משתחוים שההשתחואה של המלאכים אינו ענין השתחואה גשמיות אלא שמשתחוה ובטל בהשגתו ברוחניות ולכן יצא ממנו משה (ועמ\"ש במ\"א ההפרש בין משה ואליהו שהוא גם כן עד\"ז) ואח\"כ ותעמוד מלדת שלא היה יכול להיות בחי' גילוי עוד. (ועמ\"ש ע\"פ טובה הארץ מאד מאד דענין דור המדבר שהיה מבחי' לאה עולם המחשבה וטענו למה צריכים לירד בבחי' עולם הדבור שהוא בחי' מל' ארץ תתאה לקיים המצות בדבור ובמעשה הלא זה אפשר לקיים גם ע\"י התומ\"צ ברוחניות דהיינו ע\"י המחשבה כו' אך באמת היו בטעות גדול דע\"י דבור ומעשה דוקא נמשך גילוי אוא\"ס ב\"ה ביתר שאת לאין קץ כי נעוץ סופן בתחלתן כו' ומרבע\"ה התפלל תקט\"ו תפלות ליכנס לארץ כו'. ועפ\"ז יובן עוד ענין ויאהב יעקב את רחל דוקא שהיא בחי' דבור ומעשה כי שנואה לאה ההפך מכוונת דור המדבר. ואמנם צריך ביאור מ\"ש לאה הפעם ילוה אישי אלי דוקא דודאי לא עלה על דעתה לאפוקי מבחי' דבור ומעשה. אלא הענין כי באמת צ\"ל ב' הבחי' מודו\"מ דהא בלא הא לא סגי ועמ\"ש במ\"א בענין לויתן ושור הבר שהוא ג\"כ ענין ב' בחי' הנ\"ל לויתן לשון התקשרות בחי' בטול דנוני ימא כמו הפעם ילוה כו' ולאה רצתה שיהיה העיקר ע\"י בחינה זו ע\"ד שאמרו בחסידים הראשונים שהיו שוהין ט' שעות בכל יום בתפלה שהוא כענין בטול והתקשרות הנ\"ל דמחשבה כו'. ואימתי תורתן נעשית אלא מתוך שחסידים הן כו' הרי רוב עסקם היה עד\"ז )(ומבואר ענין זה לקמן בד\"ה ששים המה מלכות כו' אחת היא יונתי כו') ואמנם יעקב ידע שזה אי אפשר רק לבני עלייה שהן מועטים אבל כל ישראל עיקר רוב העסק הוא ע\"י דבור ומעשה ולכן היה באהל רחל עיקר קביעותו שהוא בחי' דומ\"ע ומ\"מ צ\"ל ג\"כ מחשבה שמזה נמשך ראיה ושמיעה לאסתכלא ביקרא דמלכא כו' וכל האומר אין לי אלא תורה כו' אלא צ\"ל רו\"ש רק כי אז נעוץ סופן כו':"],[33,"<b>אם לא תדעי לך היפה בנשים צאי לך בעקבי הצאן ורעי את גדיותיך על משכנות הרועים.<\/b> הנה כתיב ורחל היתה יפת תואר ויפת מראה. פי' יפת תואר בציור האברים לפי תכונתם במדתם. ויפת מראה בזיו והוד קלסתר הפנים."],[33,"והנה רחל הוא כנ\"י שנק' בשם רחל ע\"ש הפסוק כרחל לפני גוזזיה נאלמה. והענין כי הנה כתיב נעשה אדם בצלמנו כו'. ופי' בצלמנו כמ\"ש ועל דמות הכסא דמות כמראה אדם. והוא בחי' לך הוי\"ה הגדולה והגבורה כו' וכך הוא בנפש האדם ז' מדות אהוי\"ר כו'. אך אין ערוך מדת הנפש שהיא בעלת גבול לגבי מדותיו ית' שהוא א\"ס ולמדותיו א\"ס וכדי שיאיר על נפשו אור האהבה מאור א\"ס ב\"ה צ\"ל בבחי' בטול הנפש במציאות אליו ית' שהוא להיות בחי' עפר ודומם לגבי אור א\"ס ב\"ה."],[33,"וכמאמר ונפשי כעפר לכל תהיה והוא בחי' עפר אשר בקרקע המשכן וע\"י זה תהיה נפשו מכון ומשכן לאור באור א\"ס ב\"ה להיות בבחי' בצלמנו בציור האברים אהוי\"ר כו' מחשבה דו\"מ כו' וזהו בחינת יפת תאר שיתארו בם כל המדות בשלימותן וביופין כמו שהם למעלה כו'."],[33,"וזהו ורחל היתה יפת תאר שבחי' יפת תאר זה הוא ע\"י בחי' רחל שהוא כמ\"ש וכרחל לפני גוזזיה כו'. אך כ\"ז הוא בחי' חיצוניות שהם אהוי\"ר כו' ומחשבה דבור ומעשה כו' אבל בחי' פנימית הוא בחי' רעותא דלבא שהוא ⟦כג,ג⟧בחי' הארה מפנימית אוא\"ס ב\"ה דלית מחשבה תפיסא ביה כו' ובהארה זו שמשם לכנס\"י נק' יפת מראה שהוא זיו הקלסתר פנים שלכן נק' בשם פנים שהפנימיות מתגלה בו כמו צהבו פניו כו' והוא ענין מ\"ש יאר ה' פניו כו'."],[33,"וכדי שתהא כנ\"י מקבלת בחי' והארה זו הוא ג\"כ מחמת בחי' רחל. והוא בחי' ובכל מאדך כו' שע\"י זה נמשכה ההארה העליונה ההיא מריש כל דרגין עד סוף כל דרגין כו' וכמ\"ש ומתחת זרועות עולם. וזהו היפה בנשים. פי' בחי' יפת תאר ויפ\"מ הנ\"ל. וז\"ש אם לא תדעי לך. פי' שלא נמשך בחי' היפה בנשים הנ\"ל בבחי' דעת שלימה (וכעין מ\"ש במ\"א שיש נשמות שנק' זרע אדם שיש בהן בחי' דעת חזק והן נשמות דאצי' וכמו נשמת רשב\"י. ויש שנק' זרע בהמה שאין בו בחינת דעת והיינו כמו נשמות שלנו דבי\"ע ואין הפירוש שאינו יודע ומבין רק שלא נמשך מזה התפעלות אמיתית ואינו נזון מן ההתבוננות כו' וזהו אם לא תדעי לך ופי' לך מובן ממ\"ש ע\"פ עיני כל). אך זאת העצה היעוצה צאי לך בעקבי הצאן. צאן מלשון צאי כלומר דבר היוצא דהיינו בחי' היוצא מלמעלה מסדר ההשתלשלות והוא בחי' צאן לבן לובן העליון וכל העבודה שעבד יעקב ללבן שש שנים בצאנך הם בחי' שיתא סדרי משנה כו' שהם בחי' צאן שיצאו ונמשכו מענג העליון אק\"ב אשר הוא בחי' ענג כמ\"ש במ\"א ותורה שבע\"פ נק' פרט מלשון פרט ועוללות שנמשכו שלא כסדר ההשתלשלות מעילה לעילה רק בדרך פרט ועוללות."],[33,"וזהו ויפרוץ האיש מאד מאד ויהי לו צאן רבות שהמשיך בחי' צאן רבות ע\"י בחי' מאד מאד. כי בחי' ובכל מאדך כו' הוא בחי' מאד שלך כל חד לפום שיעורא דיליה משא\"כ מאד סתם אבל מאד מאד הוא בחי' מאד לגבי כל הבחי' מאד. ופי' הפסוק ויפרץ האיש מאד מאד לפי שפרץ והרבה למעלה ממדרגה למדרגה עד רום המעלות לפיכך הרבה להמשיך בחי' צאן מבחי' רבה וגבה מאד נעלה מאא\"ס ב\"ה ממש. (ועיין מ\"ש בפ' שלח בפי' טובה הארץ מאד מאד) ועי\"ז המשיך ג\"כ בחי' שפחות ועבדים. והנה יעקב אבינו ע\"ה לפי שהיה בחי' מרכבה המשיך בחי' צאן ע\"י עבודתו וע\"י עובדא דמקלות (וכן עד\"ז חפירת הבארות שהם המשכות אוא\"ס ב\"ה במקלות ובארות) כי לפי שהיה במעלה ומדרגה העליונה מאד מאד היה יכול להמשיך אוא\"ס ב\"ה במעשה של עצמו שיהיו כל מעשיו משכן ומכון להשראת אוא\"ס ב\"ה אבל אנו אין לנו כח זה אלא במה שמוכן כבר להיות שם המשכת אוא\"ס ב\"ה דהיינו בבחי' תומ\"צ הניתן לנו ונק' בעקבי הצאן בחי' עקביים סוף דרגין דהיינו תומ\"צ המלובשים בענינים גשמיים שעל ידם ורעי את גדיותיך המה המזלות מלשון גד גדי וסינוק לא."],[33,"וכמו העורכים לגד שלחן כי כל הדברים שבעוה\"ז הם תחת המזלות מזל מחכים מזל מעשיר כו'. וכן ממגד תבואות שמש כתיב מזל השמש משפיע תבואות דהיינו תורה ומצות המלובשים בעניינים גשמיים הנתונים תחת המזלות. רעי ופרנס אותם מענג העליון על משכנות הרועים פי' רועים הם ז' רועים אברהם יעקב משה כו' ונק' רועים ע\"ש שממשיכין בחי' עונג העליון לכנס\"י."],[33,"והנה האבות הן הן המרכבה. אבל אנו אין לנו כח זה אלא במשכנות הרועים בחי' כלים מכלים שונים ויין מלכות רב בחי' חסד דרועא ימינא הוא כלי לבחי' אברהם אוהבי דהיינו מצות צדקה וחסד. וכן שיתא סדרי משנה זרעים בחסד ונק' משכנות הרועים שם תרעה את גדיותיך ועי\"ז תזכה להגיע ולבא למדרגה גדולה מזו להיות על משכנות הרועים ולמעלה מבחי' משכנות דהיינו למקום הרועים עצמן:"],[33,"⟦כג,ד⟧(ובכ\"ז יובן הפסוק עבדתיך ארבע עשרה שנה בשתי בנותיך ושש שנים בצאנך. כי הנה כתיב וללבן שתי בנות שם ה' גדולה לאה ששרשה מבחי' ה' עלאה דשם הוי\"ה. ושם ה' קטנה רחל כו'. ונק' שכינתא עלאה ושכינתא תתאה. והם בחי' מקור נשמות דאצי'. כי בנשמות דאצילות יש ג\"כ ב' מדרגות. הא' הנק' אחים למקום. ויש שנק' בנים. אך הנה ברחל כתיב ורחל באה עם הצאן אשר לאביה שהם נשמות דבי\"ע שנק' זרע בהמה. וזהו אם לא תדעי לך היפה בנשים דקאי על נשמות דבי\"ע שנק' בהמה וצאן שלא יוכלו להמשיך בנפשם בחי' היפה כו' להיות יפת תאר ויפת מראה מחמת פחיתות נשמתם והסתר הגוף ונה\"ב וכמ\"ש במ\"א ע\"פ וראית בשביה אשת יפת תאר כו' שבחי' זו דיפ\"ת הוא בגלות ושביה בנה\"ב. אזי זאת העצה בחי' שש שנים בצאנך שהם שיתא סדרי משנה שהתורה נק' עוז ותושיה שנותנת כח בנה\"א ומתשת כח הנה\"ב ועי\"ז יוכלו ג\"כ לבא לבחי' ורחל היתה יפ\"ת כו' וכמ\"ש לך אמר לבי בקשו פני לבקש גילוי פנימית הלב וכיצד יבקש ויחפש אחריה את פניך ה' אבקש דהיינו ע\"י עסק התומ\"צ דאורייתא מחכמה נפקת שהיא בחי' הארת פנימית הוי' חכמת אדם תאיר פניו ועי\"ז יאר הוי' פניו אתנו סלה. וכמ\"ש במ\"א ע\"פ בחדש השלישי לצאת בנ\"י מארץ מצרים כו' וזהו ההילוך מלמטה למעלה. משא\"כ בנשמות עליונות ההילוך מלמעלה למטה תחלה ואהבת כו' ואח\"כ והיו הדברים כו' וזהו ענין ארבע עשרה שנה שהם שבעה מדות עליונות שהן בחי' שבעה ושבעה מוצקות כו' כמ\"ש לקמן ע\"פ כי עמך מקור חיים. וזהו אם לא תדעי כו' ע\"ד ההילוך מלמעלה למטה אזי צאי כו' וכמ\"ש ע\"פ והתהלכתי בתוככם כו' שיש שני בחי' הילוך בעבודת ה'. הא' לנשמות הצדיקים הגדולים שהילוכם ודרכם בקדש הוא כפי סדר ההמשכה מלמעלה למטה וכמ\"ש בפרשת שמע ישראל מתחלה ואהבת את הוי' שהוא בחי' אהוי\"ר ונמשך ע\"י ההתבוננות שמע ישראל כו' ואח\"כ והיו הדברים כו' ודברת בם כו' שהוא מצות ת\"ת ואח\"כ וקשרתם לאות שהוא מעשה המצות. וזהו כסדר ההמשכה של שם הוי' ב\"ה. י\"ה הן בחי' דחילו ורחימו. ו' הוא בחי' תורה. ה' בחי' מצות. אמנם יש ג\"כ בחי' ב' והוא ההילוך מלמטה למעלה דהיינו לנשמות שאין כחן יפה להוליד אהוי\"ר מרוח בינתם כ\"א ע\"י הקדמת עסק התורה והמצות תחלה שמזה דוקא יקבלו הכח לבא לאהוי\"ר כו'. ועז\"נ אם לא תדעי לך. שלא תוכל להמשיך ולהאיר בנפשך גילוי אהוי\"ר מבחי' היפה בנשים הוא בחי' יפ\"ת ויפ\"מ המבואר למעלה אזי צאי לך בעקבי הצאן תחלה והוא כסדר ההילוך מלמטה למעלה):"],[34,"<b>וישכם לבן בבקר וינשק לבניו ולבנותיו ויברך אתהם כו'.<\/b> הנה כתיב לך ה' הגדולה והגבורה כו'. בלשון נקבה שהם בחי' מקבלים מאור א\"ס ב\"ה כי באור א\"ס ב\"ה בעצמו לא שייך לשון גדולה שבמקום גדולתו כו'."],[34,"והנה גדולה היא מדת אברהם וכמ\"ש ואגדלה שמך. וזהו שאומרים אלקי אברהם כו' ושבחו של הקב\"ה הוא שכך ענוותנותו ית' כו' שנמשך ונתפשט אור א\"ס ב\"ה כ\"כ עד שיהיה שורה ומתגלה במדת אברהם אוהבי כו'."],[34,"והנה האבות הן הן המרכבה שהיו כל ימיהם בבחי' בטול כו' ועי\"כ זכו להשראת השכינה אור א\"ס ב\"ה בגילוי ממש שיהיה אור א\"ס ומדותיו הם המתגלים בנפשם אברהם אוהבי ופחד יצחק כו'."],[34,"והן הן מדות גדולותיו וגבורותיו של הקב\"ה עצמו שנמשך ונשתלשל למטה על ידיהם להיות גילוי אור א\"ס ב\"ה בכלל נפשות ישראל בבחי' גילוי ממש ולא במחשבה ⟦כד,א⟧בעלמא שכל ישראל מאמינים בני מאמינים כו' כי המחשבה היא ברשותו של אדם אל כל אשר יחפוץ יטנו והחפץ ימלא את לבו ומחשבתו להטותה פעמים כך ופעמים כך."],[34,"וצריך שיהיה החפץ והרצון תקוע במקום נאמן והוא ע\"י הדעת והכרה בבחי' הרגשה כאלו רואה כו' וכמארז\"ל על אברהם אבינו ע\"ה שהכיר את בוראו כו'. אך המשכת גילוי זה מבחי' מעלת ומדרגת האבות עצמם כו' כי האבות היו בבחי' מרכבה דאצי' דאיהו וגרמוהי חד ולא כל נפש תוכל שאת גילוי זה. אבל להיות גילוי זה נמשך ונשתלשל בבי\"ע ששם מושרשות נפשות כלל ישראל הוא ע\"י בחי' ומדרגת השבטים כי שבט הוא לשון המשכה כמו כוכבא דשביט וגם לשון שבט וענף מן האילן הגדול שהם בבחי' מרכבה לעלמא דאתגליא בבחי' (הים) עמד על י\"ב בקר הם בחי' י\"ב שבטים כנגד ארבע חיות המרכבה פני אדם כו' וכל א' כלול מג' אבות הרי י\"ב ומשם נמשך השפעת והמשכת גילוי אלקותו ית' בכלל הנפשות של ישראל שבחי' ומדרגת השבטים יכולים כל ישראל שאת בנפשם. וזהו שאמר הנביא על הגלות (ונתקן בתקון חצות) למה תתענו ה' מדרכך תקשיח לבנו מיראתך שוב למען עבדיך שבטי נחלתך. פי' מדרכך מדת אברהם שנאמר עליו (בראשית יא) הלוך ונסוע הנגבה כו' ומיראתך מדת יצחק כו' וקובל הנביא למה תתענו ותקשיח לבנו ממדת אברהם ויצחק להיות רחוקים מאור פני ה' שיתגלה עלינו ולהיות בגלות אדום הם ענייני עוה\"ז כו' על כל פנים שוב למען עבדיך שבטי נחלתך כלומר שעם היות שבחי' מעלות ומדרגת האבות עצמם אינו שורה ומתגלה בנפש האדם בגלות אבל ע\"י השתלשלו' בחי' ומעלת השבטים יוכל להיות גילוי זה בכל נפש מישראל:"],[34,"<b>והנה<\/b> מדתו של יעקב אבינו ע\"ה היא בחי' הרחמים העליונים שאפילו על כל עולמות שייך ונופל בחינת הרחמנות כו' כמ\"ש במ\"א ומדרגות השבטים יוצאי ירך יעקב הם במדריגה שלמטה הימנו דהיינו לעורר רחמים רבים על ניצוץ אלקות השורה בנפשו ע\"י התבוננותו בגדולת א\"ס ב\"ה איך שהוא רם ונשא וכולא קמיה כלא חשיבי ובטול כל הנבראים במקורם ובכללם גם נפשו כשהיתה במקור חוצבה חלק אלוה ממעל ממש שהיתה בטלה באור א\"ס ממש ואיך ירדה פלאים מטה מטה מאיגרא רמא כו' ולפי רבוי ואריכות ההתבוננות כך תגדל הרחמנות ביתר שאת. ועד\"ז נתקן כל סדר התפלה ובפסוד\"ז שכמה פסוקים המספרים בשבחו ש\"מ בעילוי אחר עילוי שמזה תגדל הרחמנות על ירידת הניצוץ וריחוקו מאור א\"ס ב\"ה כנ\"ל."],[34,"והנה ע\"י שמתעורר בחי' הרחמנות באתעדל\"ת אתעדל\"ע כמו למשל השבט וענף של אילן שכופפין אותו כו' אזי נמשך כל האילן. כך הוא ע\"י אתעדל\"ת זו שמבחי' ומדרגת השבטים גורם אתעדל\"ע בחי' רחמים רבים להיות נמשך גילוי אור א\"ס ב\"ה ובחי' מעלות ומדרגות האבות בבחי' גילוי ממש בנפשו דהיינו בחי' דעת והרגשה כאילו רואה כו'. וכמאמר אבינו אב הרחמן רחם נא עלינו ותן בלבנו בינה ⟦כד,ב⟧כו' שכדי להיות לבבנו מכון וכסא להשראת בינה ודעת בבחי' הרגשה בלב הוא ע\"י הרחמנות כי הרחמנות והדעת תלוי זה בזה. וכמארז\"ל (ברכות לג.) כל מי שאין בו דעה כו':"],[34,"<b>אך<\/b> הנה גם לבחי' אתעדל\"ע שיהי' תלוי באתעדל\"ת זו צ\"ל בחי' המשכה מלמעלה והמשכה זו היא ממקור הרחמים עליונים שלמעלה מעלה מסדר ההשתלשלות ששם מקור ושרש הרחמים מה שאינו מושג ונתפס בסדר השתלשלות כלל וכמאמר אלקי עולם ברחמיך הרבים ברחמיך דייקא כו' וכמ\"ש במ\"א וזהו וישכם לבן בבקר פי' לבן דקדושה הוא בחי' לובן העליון דהיינו בחי' אור עצמותו ומהותו של אא\"ס ב\"ה כמשל מראה וגוון לבן שאינו דומה לכל המראות וגוונים שהגוונים שלהם נתהוו ע\"י צבע משא\"כ מראה וגוון לבן הוא עצמות הדבר ומהותו שלא נשתנה ולא נתהוה ע\"י צבע."],[34,"וכן הוא עד\"מ אור א\"ס ב\"ה בעצמו ובכבודו דלית בי' בחינת גוונין כלל דלית מחשבה תפיסא בי' ואני ה' לא שניתי כתיב. ולכן כתיב והחליף את משכורתי עשרת מנים אם כה יאמר נקדים כו'. שכל הבחי' עקודים ונקודים נתהוו ונשתלשלו ממנו ובירידתם והשתלשלם הם נקראים בשם עקודים ונקודים משא\"כ בראשיתם ומקורם הם בטלים ונכללים ואינם עולים בשם כלל ולכן יכול הוא להפך מבחי' עקודים לבחי' נקודים ומנקודים לעקודים ואין זה שינוי לפניו ית' כב\"י מאחר שהם בטלים במציאות ואינם עולים בשם כלל לא שייך שם שינוי כלל (וזלע\"ז לבן דקליפה מחליף משכורתו ממש ברמאות). והנה בחינת לבן דקדושה כנ\"ל שם הוא מקור הרחמים העליונים מה שלמעלה מעלה מסדר ההשתלשלות ואתערותא דילי' בבוקר דאברהם בחי' חסד כמ\"ש (בראשית כב) וישכם אברהם בבקר להמשיך רחמים להיות אתעדל\"ע תלוי באתעדל\"ת המשכת הרחמים היא בבחי' חסד דאברהם. וכמאמר אהבת עולם אהבתנו כו' אבינו אב הרחמן כו'. וזהו וינשק לבניו הם הם בחי' השבטים (שהם בני בניו ובני בנים הרי הם כבנים) בחי' המשכת אתעדל\"ע כנ\"ל ובנותיו הן הן לאה ורחל עלמא דאתכסייא ועלמא דאתגלייא שלכל בחי' הללו נמשך בחי' לבן העליון בבחינת נשיקין ואתדבקות רוחא ברוחא. לכל המשפיעים שהם בחי' בניו והמקבלי' שהם בחי' בנותיו שיהי' נשפע ונמשך בהם בחי' רחמים עליונים להיות אתעדל\"ע תלוי באתעדל\"ת. ויברך אתהם כו'. ענין הברכה כמ\"ש (שם א) ויברך אתם אלקים ויאמר להם כו' ומלאו את הארץ וכבשה כו'. דהיינו שיהי' תוספת ברכה והמשכה למטה עד דאתהפכא חשוכא לנהורא. וכמ\"ש (שם יב) ונברכו בך כל משפחות האדמה ובזרעך שיהיו נברכים ונכללים כל בחי' הניצוצים שנפלו בשבה\"כ בקדושתו של זרע יעקב. וילך וישב לבן למקומו שזמן הארת בחי' זו היא בבוקר זמן תפלת השחר אבל אחר התפלה מסתלק הארה זו ולכך צריך להתפלל בכל יום שבכל יום חוזר ונמשך הארה זו וחזר ונסתלק אחר התפלה. ויעקב הלך לדרכו בחי' יעקב יו\"ד עקב הלך ונמשך בחי' תורה ומצות דתורה אקרי דרך (קדושין ב:) וד\"ל:"],[35,"⟦כד,א⟧<b>וישלח יעקב מלאכים לפניו אל עשו אחיו כו'.<\/b> הנה ידוע שיעקב שרשו הוא מבחי' שם מ\"ה דעולם התקון ושרשו של עשו הוא מבחי' עולם התהו. והאורות דתהו הם גדולים מאד ולא יכלו להתלבש בתוך הכלים. ונסתלקו מהכלים והן בחינת מקיפים והכלים ⟦כד,ב⟧נשברו ונפלו למטה לכן הי' עשו שלמטה רשע אבל מצד שרש שרשו במקיפים דתהו הרי האורות דתהו הם למעלה מהאורות דתקון וכמשי\"ת לקמן בעז\"ה ע\"פ ויקח מן הבא בידו מנחה כו'. וכמשנ\"ת ג\"כ בפ' תולדות ע\"פ ראה ריח בני כו'."],[35,"והנה יעקב חשב שעשו נתברר כבר ⟦כד,ג⟧וחזר לשרשו הנעלה בחי' המקיפים דתהו שלפני התקון. לכך שלח יעקב מלאכים לפניו לפניו ממש דהיינו אל בחי' שלמעלה ממנו במדרגה אל עשו אחיו שעירה שהוא בחי' מלכין קדמאין דתהו בחי' מקיפים כנ\"ל כדי להמשיך בחי' המקיפים דתהו אליו למטה בתקון שהוא בחי' האו\"פ ויאיר המקיף בפנימי ויתייחדו יחד."],[35,"ולכן צוה אותם כה תאמרון לאדני לעשו כו' עם לבן גרתי ויהי לי שור וחמור כו' דהיינו שהודיעו שכבר נגמר ונשלם כל סדר התקון דאצי' בתכלית השלימות כי כל הבחי' ומדרגות שבעולם האצי' בחי' שור וחמור צאן ועבד ושפחה כו'. כולם נתבררו ונתקנו ע\"י שם מ\"ה."],[35,"וזהו ויהי לי כו'. וכ\"ז בא מפני שעם לבן גרתי. פי' בחי' לובן העליון שמשם הי' עיקר כח השפע ליעקב בעל עולם האצילות לברר ולתקן הכל וכיון שכן שנגמר ונשלם מלאכת התקון בשלימות מעתה ראוי ויוכל להיות השראת והמשכת המקיפים דתהו שאם לא היה נגמר התקון בשלימות לא היה יכול להיות המשכת המקיפים כמ\"ש בזוהר דלית ברכתא שריא באתר ריקניא כו' אלא באתר שלים כו' אבל עכשיו שנגמר התקון בתכלית ה\"ז אתר שלים שראוי להיות בו המשכת המקיפים עליונים לכן ואשלחה להגיד לאדני למצא חן בעיניך. דהיינו שתשפיע ותאיר את המקיף שלך אלי בעולם התקון וזהו מציאת החן. והיינו מפני כי ויהי לי שור וחמור צאן כו'. דאתהפכא חשוכא לנהורא בעולם התקון וה\"ז אתר שלים ממש א\"כ ראוי אני למצא חן בעיניך שהוא השראת הברכה דבחי' המקיפי' כו':"],[36,"<b>וישובו המלאכים אל יעקב לאמר באנו אל אחיך אל עשו וגם הולך לקראתך וארבע מאות איש עמו.<\/b> פי' תשובת המלאכים הוא כך שעם היות שמחמתך ראוי ונכון מאד שיומשך אליך מבחי' המקיף דתהו מאחר שנמצא בך השלימות של התקון אבל מה לעשות שהמניעה היא מצד עשו אחיך שהוא עדיין למטה בבחי' שבירה ולא נתברר עדיין כלל וא\"כ איך ישפיע לך משרשו המקיף דתהו הנ\"ל מאחר שהוא בעצמו עדיין למטה."],[36,"והראי' ע\"ז שהוא בשבירה הוא כי וגם הולך לקראתך וארבע מאות איש עמו. פי' ד' מאות איש הם דינים קשים של החיצונים הנמשכים מן ת' בתי דינין קשין דמשתכחין כמ\"ש באד\"ר."],[36,"וכנודע ששרש שרשם של ד' מאות איש הנ\"ל נתהווה מן ד' מאות שקל כסף שנתן אברהם אע\"ה לעפרון. שהד' מאות שקל הנ\"ל הם ת' עלמין דכסופין דירתי צדיקייא לעלמא דאתי דהיינו שהם בחי' אורות שפע ענג העליון הנמשכים מבחי' עתיקא קדישא שהוא בחי' ממוצע בין עצמיות הא\"ס לעולם האצי' כנודע שהכתר הוא ממוצע בין המאציל לנאצלים ומשם נמשכו השפעות ענג העליון לצדיקים לע\"ל. וזהו ענין ת' עלמין דכסופין והם ד' מאות שקל כסף הנ\"ל. ונק' עובר לסחר כי כתר נק' סוחר לשון (שבת יג.) סחור סחור שהוא בחי' המקיף לכל ההשתלשלות. ות' עלמין דכסופין הנ\"ל הם עובר לסוחר שהם באים ונמשכים מעצמות אא\"ס שלמעלה גם מהכתר ועוברין ונמשכין בהכתר ומשם נהרין לצדיקיא לע\"ל. וענין הנתינה לעפרון הי' בדרך ענין ירידת הבירורים כדי להוציאם אח\"כ ממנו בתוס' ברכה כו'. אך ביני לביני הן שירדו כ\"כ למטה מטה ונעשו בחי' ד' מאות איש לעשו. והוא בחי' ש\"ק כמ\"ש (ישעיה נ) אלביש שמים קדרות ושק אשים כסותם. וכן ארז\"ל (סנהדרין קא.) התורה חוגרת שק כו' דהיינו שנתהווה בחי' לבוש שק שהחיצונים יונקים ממנו ולע\"ל בגמר כל הבירורין כשיבולע המות לנצח (זכריה יג) ואת רוח הטומאה אעביר כו' אז יחזיר עפרון הד' מאות שקל כסף לשרשם אל הקדושה בשלימות. ומעתה ידע יעקב שא\"א שישפיע לו עשו משרשו את המקיף דתהו אשר הוא מבקש מאחר שהוא בעצמו למטה."],[36,"ואין עצה אלא רק שימשיך ⟦כד,ד⟧יעקב בעצמו את המקיף הנ\"ל. ולזאת כשידע שבעצמו צריך להמשיך המקיף הנ\"ל לכן הוצרך להעלות מ\"ן כנגדו כדי להמשיך עי\"ז את המקיף כי רוח אייתי רוח כו'. וזהו ענין המנחה ששלח יעקב לעשו הוא בחי' העלאת מ\"נ להמשיך מ\"ד דמקיף דתהו הנ\"ל. ולכך שלח גמלים אף שהם בהמות טמאות כי לגבי או\"מ הנ\"ל כחשכה כאורה כו'. וכמשי\"ת לקמן בעז\"ה בענין ויקח מן הבא בידו מנחה כו':"],[37,"<b>ויאמר יעקב אלהי אבי אברהם כו'.<\/b> פי' שהתפלל שיומשך אליו המקיפים דקדושה של האבות לעזור לו שיוכל להמשיך המקיף דתהו הנ\"ל שיתגלה למטה ועי\"ז ג\"כ הצילני נא מיד עשו כו' שלמטה."],[37,"ויחץ את העם כו' לשני מחנות כו'. הנה הטעם שחלק לשני מחנות דוקא. יובן ע\"פ הקדמה הידוע שעיקר ההפרש בין עולם התהו לעולם התקון. שבעולם התהו היו הספירות מפורדים זה תחת זה אבל בעולם התקון הם בציור קוין דהיינו ג' קוין ימין ושמאל ואמצע שהקו האמצעי הוא המחבר ומייחד ג\"כ ב' הקוין דימין ושמאל להיות מתכללים יחד כידוע דת\"ת הוא הממוצע בין חו\"ג ומחברם יחד ולכך ישראל שהם בבחי' התקון אומרים ג\"פ קדוש דוקא וכתיב בהם ג\"כ והייתם לי סגולה שהסגו\"ל הוא ג' נקודות בחינת ימין ושמאל ואמצע כו' אבל בעולם התהו שהיו בבחי' פירוד זת\"ז ולא נתייחדו יחד ה\"ז רק בחי' ב' קוין שהחסד הוא בפ\"ע והגבור' הוא בפ\"ע."],[37,"וכמ\"ש ביאור הדברים במ\"א שהענין הוא לפי שבתהו היו האורות מרובים והכלים מועטים ולכן מצד קוטן הכלי לפ\"ע האור ע\"כ אין הכלי יכולה להכיל ב' הפכים חו\"ג יחד עד\"מ באדם מי ששכלו קטן לא יכיל ב' הפכים כלל אלא אם יטה שכלו לזכות לא ימצא אז שום שכל לחוב ולא יסבול שום נטיה לחוב בלבו אלא רק טוב וחסד בלבד."],[37,"ובהיפוך כאשר יטה לחוב לא יסבול כלל נטיה לזכות ונמצא אינו אלא בקו א' תמיד פעמים בקו הימין לזכות ופעמים בקו השמאל לחוב והרי הקוין מפורדי' שכשהוא בבחי' חסד לא יוכל לסבול בחי' דין וכן להיפוך וזהו הנק' בחינת ב' קוין שהחסד הוא בפני עצמו והגבורה בפני עצמה. אבל בתקון שהת\"ת מכריע בין חו\"ג היינו שגם בשעת הדין יוכל להיות ג\"כ נטיה לזכות וכן להיפך לפי שבתקון האורות מועטים והכלים מרובים נמצא הכלי רחב לקבל גם ב' הפכים וכמו באדם שדעתו רחבה יוכל לסבול ב' הפכים יחד וישכנו במוחו ולבו שמצד זה יש סברא לזכות אע\"פ שמצד אחר יש סברא לחוב כו' והרי בתקון מתייחדים חו\"ג יחדו וזהו ענין ג' קוין. (ועמ\"ש מזה לקמן פ' יתרו בד\"ה להבין ביאור ענין האבות הן הן המרכבה) ואמנם בעובדא זו דיעקב ועשו שהיה יעקב צריך להמשיך לו המקיף דתהו שהוא בחי' האור דתהו שבלי גבול כו' לכך הוצרך להעלות מ\"ן לשם. וידוע שהמ\"ן צריך להיו' לפי אופן ההמשכה שרוצה להמשיך משום שלפי אופן ההעלא' כך היא ההמשכה."],[37,"והואיל וכן מאחר שבתהו היה רק ב' קוין כנ\"ל לכך הוצרך יעקב לעשות עצמו ג\"כ בדוגמא זו. וזהו ויחץ את העם כו' לשני מחנות להיות דוגמת עולם התהו שלשם היה זת\"ז ולא בציור ג' קוין כנ\"ל ועי\"ז יתקשר בעולם התהו להמשיך האו\"מ כו'."],[37,"ומזה הטעם עצמו יובן הטעם מה שהקריב יעקב המנחה עזים מאתים כו'. שענין מנחה זו היא העלא' מ\"ן להמשיך המקיף הנ\"ל והוא ע\"ד ענין הקרבנות שהם העלאת מ\"ן להמשיך מ\"ד כנודע ואעפ\"כ היתה מנחתו שלא ע\"ד אופן ומשפט הקרבנות שבתורה כו'. בהיות שמעשה הקרבנות הוא מבהמות טהורים ושחוטים דוקא. אך השחיטה כשירה בזר."],[37,"ולא מצינו קרבן בתורה בחי רק בשעיר דעזאזל וגם בקרבנות לא היו מקריבים רק החלב והדם. והמנחה הזאת ששלח יעקב לעשו היו בהמות טמאות ג\"כ כמ\"ש גמלים מניקות כו'. וגם שהן ⟦כה,א⟧חיין ולא שחוטין והענין הוא משום שהעלאת מ\"ן שהיא המנחה דיעקב הוא להמשיך מ\"ד מבחי' המקיף דעולם התוהו."],[37,"והמ\"ן והמ\"ד דעולם התהו הוא משונה ובאופן אחר מן המ\"ן ומ\"ד דעולם התקון שהוא ענין הקרבנות שבתורה שהתורה היא מבחי' עולם התקון דאצילות והיינו כי עולם התקון הוא בחי' אור פנימי שהאורות מתצמצמים ונתפסי' בתוך הכלי ומאחר שהאור יכול להתיישב בתוך הכלי זהו הוראה שכבר נתצמצם האור בצמצומים רבים וכמ\"ש בע\"ח שבתקון האורות מועטים כו'. לכן התורה שנמשכת משם היא ג\"כ בבחי' דקדוקים וצמצומים."],[37,"ולכן מפורש בתורה סדר העלאת מ\"ן דתקון הכל בדקדוקים שהוא משפט מעשה הקרבנות שיהיו מבהמות טהורים ומג' מיני בהמות לבד ושיהיו שחוטין דוקא ויש הרבה דברים שהקרבן נפסל בו וכן בענין ההקרבה איך ומה הרבה דקדוקין כו' כי כל התור' הוסדה בדרך זה בצמצומים ומדידות מפני שהיא מבחי' התקון שהאורות מצומצמים תוך הכלים ולכן מדקדק' ג\"כ בכמה מיני צמצומים ודקדוקים כו'. אבל יעקב העלה מ\"ן לבחי' המקיף דתהו כנ\"ל שהוא אור גדול בבחי' א\"ס שלכן לא יכול הכלי להכילו ונשאר בבחי' מקיף (לכך שלח המנחה שהוא העלאת מ\"ן לשם) אף בהמות טמאות גמלים מניקות כו'. וכולן היו חיין ולא שחוטין כו'. כי להיות האור בבחי' א\"ס לכן אין שם הצמצומים והדקדוקים כי א\"ס ב\"ה הוא כל יכול לסבול הכל אף טמאין ושיהיו חיין כו' שאין נמצא שם דקדוקים וצמצומים כלל."],[37,"וכמארז\"ל גבי חזיר שעתיד לחזור וליטהר היינו לע\"ל שיבולע המות לנצח ואז יתגלה עצמות א\"ס ויוכל גם חזיר להתעלות משא\"כ עתה. לכן יעקב ששלח המנחה לעשו שהוא העלאת מ\"ן למקיף דתהו שבבחי' א\"ס שלח ג\"כ דברים טמאים ולכך שלח ג\"כ גמלים מניקות כי אדרבה שרשן של גמלים הוא מאד נעלה כמ\"ש באליעזר עבד אברהם שלקח יו\"ד גמלים מגמלי אדניו וכל טוב אדניו בידו והוא ענין כגמול עלי אמו כו' וכ\"ז לא היה יכול לעשות רק יעקב וקודם מ\"ת אבל אנחנו כבר ניתן לנו התורה מבחי' התקון ומה שהוא טמא ואסור ע\"פ התורה הוא מרוחק ולא יוכל להתעלות כלל כו' והכרת תכרת הנפש באכלה חלב כו' וכיוצא:"],[38,"<b>ויקם בלילה הוא ויקח את שתי נשיו כו' ויעבר את מעבר יבק ויקחם ויעברם את הנחל כו'.<\/b> פי' יב\"ק הוא יחוד ברכה וקדושה. והענין דהנה כתיב בעבר הנהר ישבו אבותיכם מעולם ופי' הנהר הוא בחי' בינה כמ\"ש ונהר יצא מעדן כו' ושרש האבות הוא מעבר הנהר היינו מבחי' הכתר שהוא למעלה מהנהר הנ\"ל רק שמשם נמשכו האבות ונשפלו למטה בעבר השני של הנהר בז\"א דאצילות (וע' בזהר פ' אמור מ\"ש ע\"פ זה) ויעקב שרצה שימשיך לו המקיף דתהו הנ\"ל שלפני אצילות הוצרך מתחלה לעבור את הנהר הנ\"ל וזהו ויעבר את מעבר יבק כי בחינת יחוד ברכה וקדושה הוא הכל בחי' נהר הנ\"ל שעל ידו נמשכו כל השפעות ויחוד אורות עליונים כמ\"ש ונהר יצא מעדן להשקות את הגן כו'."],[38,"וכשעבר את הנהר והגיע לבחי' שלמעלה מהנהר הנ\"ל אז לא רחוק הוא מן המקיף דתהו הנ\"ל שלפני האצילות וזהו ויעבר את אשר לו כל מה שתיקן העלה הכל לשם. אך הוא בעצמו נשאר למטה עדיין כמ\"ש ויותר יעקב לבדו כי רצה לברר את עשו שהוא עדיין בשבירה כמו שהודיעוהו המלאכים כו' והוא ענין ויאבק איש עמו כנודע:"],[38,"<b>ולהבין<\/b> כללות ענין כוונת יעקב בהמשכת המקיף דתהו לעולם התקון וגם יובן זה בעבודת ה' הנה ידוע דיעקב הוא בחי' ת\"ת שמחבר ב' הפכים שהן חו\"ג כי ע\"י התכללות ב' הפכים יחד הוא עיקר הת\"ת (כמו בגוונים כשמורכבים ב' וג' גוונים יחד ⟦כה,ב⟧הוא עיקר היופי) והמשכת והתגלות אוא\"ס בקו האמצעי כו' לכך רצה ג\"כ לחבר ולייחד ג\"כ המקיף דתהו עם האו\"פ דתקון שהם ג\"כ ב' הפכים שיתחברו יחד ואז יהיה גילוי אוא\"ס (ועיין בזהר פ' תרומה דקע\"ה ע\"ב ע\"פ והבריח התיכון ושם דף קע\"ו ע\"א):"],[38,"<b>וביאור<\/b> הדברים הנה יש ב' בחי' בעבודת ה'. הא' האהבה ברשפי אש בתגבורת מאד לצאת מן הגוף וליפרד מן הפתילה כו' והוא בחי' אה\"ר שאין כלי הלב מכילה אותה כי לא יכיל הלב ההתפעלות העצומה. לכן לא יוכל לעמוד בכלי גופו וחפץ לצאת מנרתקה חומר הגוף. והב' בחי' התפעלות המתיישב בכלי הלב ועיקר ענינה הוא בחי' המשכת אלקות מלמעלמ\"ט דוקא בכלים מכלים שונים בתומ\"צ. וזהו ענין רצוא ושוב."],[38,"והנה בחי' עולם התהו הנ\"ל היה בבחי' רצוא לכן נסתלקו האורות מן הכלים כמו האה\"ר ליפרד מן הפתילה והכלים כו'. אבל התקון הוא בחי' שוב והוא בחי' תומ\"צ ובע\"כ אתה חי להיות בתוך הגוף להמשיך אא\"ס בכלים מכלים שונים."],[38,"וזה היה ההפרש ג\"כ באותן ד' שנכנסו לפרדס בן עזאי הציץ ומת. וב\"ז הציץ ונפגע. רק ר\"ע נכנס בשלום ויצא בשלום. כי בן עזאי היה בבחי' רצוא דאה\"ר הנ\"ל בבחי' כלות הנפש ולא רצה להיות נשפל בבחי' שוב לכך לא רצה לישא אשה ואמר אפשר לעולם שיתקיים ע\"י אחרים לכן הציץ ומת שנסתלק לגמרי מן הכלי כנ\"ל כי עזה כמות אהבה כו' אכן אין זה דרך התורה שהיא בבחי' תקון כי לשבת יצרה ובע\"כ אתה חי לכן ר\"ע שהיה מבחי' תקון נכנס בשלום ויצא בשלום שהיה המ\"ן ומ\"ד שלו דהיינו בחי' הרצוא ושוב במדה ומזיגה נכונה שלפ\"ע הרצוא כן היה השוב אח\"כ."],[38,"וזהו נכנס בשלום כו' הוא בחי' קו האמצעי המייחד ומחבר את הב' קוין ימין ושמאל שהם בחי' רו\"ש לכך היה העלאת מ\"ן שלו שהוא ענין שנכנס לפרדס במדה ומזיגה נכונה בבחי' רו\"ש ונכנס בשלום בבחי' מ\"ן ויצא בשלום בבחי' המשכת מ\"ד בחי' שוב. (ועמ\"ש פ' ויצא גבי בשלום ב' בחי' שלום ע\"ש בד\"ה והיה) משא\"כ בן עזאי ששרשו היה מבחי' תהו ששם הוא בחי' שני קוין כנ\"ל בענין ויחץ כו' לשני מחנות לכך לא הי' התחברות הרו\"ש במזיגה נכונה והציץ ומת כו' התגברות הרצוא כו' ולכן היה ר\"ע מקור כל התורה שבע\"פ כי סתם משנה ר\"מ וסתם ספרא ר' יהודה כו' וכולהו אליבא דר\"ע. והוא לפי שהתורה ג\"כ היא מבחי' התקון ויש בה התכללות ב' ההפכים דרו\"ש כמ\"ש מימינו אש דת למו כו' לכן היה גילוי התורה ע\"י ר\"ע שהיה בו בחי' זו כנ\"ל:"],[38,"<b>ועתה<\/b> יובן ענין כוונת יעקב לייחד ולחבר המקיף דתהו עם האו\"כ דתקון היינו שיהיה תמיד רו\"ש במזיגה אחת שלפ\"ע הרצוא כן השוב דהיינו שיהיה האה\"ר ברשפי אש ליפרד מן הפתילה כו'. ואעפ\"כ יהיה אח\"כ בחי' שוב לאחד. ובע\"כ אתה חי להמשיך אא\"ס למטה דוקא בתומ\"צ (כמ\"ש בתניא פ' נג). וה\"ז יחוד והתחברות המקיף דתהו עם כלים דתקון. וז\"ש ביעקב ויבא לו יין. ופי' בזוהר דארמי מיא לגו חמרא. כי יין הוא בחי' רצוא גבורות ורשפי אש ממטה למעלה. ויעקב ארמי מיא בחי' שוב."],[38,"ולכן ויבא לו יין כו' הוא בתרי טעמי שהוא התכללות הרו\"ש מים ויין כו' ולכן איתא דיעקב הוא שלימו דאבהן כי לא כאברהם שיצא ממנו ישמעאל. מפני שהיה אברהם מדת החסד הפשוט בלא מזיגה לכך נתפשט יותר מדאי עד שאמר לו ישמעאל כו' ויצחק היה בבחי' גבורה כו' אבל יעקב הוא שלימו דאבהן התכללות ההפכים רצוא ושוב כנ\"ל:"],[38,"⟦כה,ג⟧<b>ויקח<\/b> מן הבא בידו מנחה לעשו אחיו כו'. הנה כל הקרבנות נק' בשם מנחה כמ\"ש והבל הביא גם הוא מבכורות צאנו ומחלבהן וישע ה' אל הבל ואל מנחתו כו' (הגם שהיה קרבן מנחה בפ\"ע כמו מנחת סלת ומחבת כו'. אך כל התורה היא כלל ופרט וכן תפלה שכנגד קרבנות כל התפלות בכלל נק' מנחה ותפלת מנחה בפ\"ע היא פרט ועיין בתשו' אמונת שמואל סי' כ') הרי שהיו בכורות צאנו נק' בשם מנחה. ויובן זה ע\"פ הקדמה כי נודע כי אני הוי\"ה לא שניתי כתיב ולמת\"ב ואינו בגדר עלמין כלל ואעפ\"כ כי ממך הכל כתיב. אך הוא ע\"י זיו והארה הודו על ארץ ושמים כו' וגם הארה זו עצמה מעצמותו ית' לא היו העולמות יכולים לקבל חיות ושפע להיותן בבחי' גילוי עולמות כ\"א ע\"י השתלשלות דהיינו כשלשלת הארה והארה דהארה."],[38,"וכל מה שיורד ומשתלשל מטה מטה הוא הארה דהארה מהעליון ממנו כו'. וכל מיני מדרגות ברבוי התחלקות העולמות ועליות וירידות הכל הוא בבחי' זיו והארה אם רב ואם מעט. ויש בזה כמה מיני מדרגות זו למעלה מזו כמו עוה\"ב ותחה\"מ ואלף הז' יום שכולו שבת ומנוחה לחיי העולם שהוא עילוי אחר עילוי והכל הוא בזיו וההארה כו'."],[38,"והנה יש ב' מיני השתלשלות. השתלשלות האורות בכלים בבחי' פנימי' שהוא לפ\"ע הכלי שהכלי יכול להגבילו. ויש בבחי' מקיף דהיינו שאינו מוגבל בכלי. ויובן זה בעבודת ה' שבלב זו תפלה ברשפי אש שכאשר האהבה באה מהתבוננות כי הוא חייך וחיי החיים של כל העולמות נמשך מזה תשוקת הנפש כאשר תוכל שאת לפי מזגה ותכונתה. משא\"כ כשהאהבה באה מחמת שישים אל לבו ויעמיק בעומקא דלבא כי אני ה' לא שניתי כתיב ולמ\"ת כו'. אשר ע\"כ תכלה אליו נפש כל חי להבטל במציאות ולהתכלל באחד ממש."],[38,"ולכן כאשר ישים אל לבו ג\"כ ריחוקו מא\"ס ב\"ה אשר ירדה הנפש ותרד פלאים בעלמא דפרודא כו' תהי התגברות האהבה ביותר מאשר תוכל שאת עד שאין כח בנפש לכלוא את האה\"ר וזהו בחי' בכל מאדך בחילא יתיר כו':"],[38,"<b>והנה<\/b> כתיב פני אריה אל הימין ופני שור מהשמאל שבחי' פני השור הוא למטה ממדרגת האריה במרכבה שבחי' פני אריה הוא אל הימין כו' ואעפ\"כ למטה בעוה\"ז הרי השור הוא בהמה טהורה והארי הוא חיה טמאה."],[38,"והענין כי אדרבה מה שהוא למעלה במדרגה יותר גבוה אין לו התלבשות בכלי למטה להיות גילוי בחינתו כמו שהוא למעלה בקדושה וכמו אריה שהוא בחי' גבורה גבור כארי שהוא התגברות האור במאד מאד עד שא\"א להיות שורה ומתגלה קדושתו למטה בכלי שנכלל בקדושה וכמו בהמה טהורה אלא ע\"י דרך נפילת האור ברפ\"ח נצוצין שבשבה\"כ בג' קליפות הטמאות ואז הוא בחי' חיה טמאה שמקבל חיות מנפילות הנצוצים מארי דקדושה. אבל לא בהתגלות בחי' ארי' בדרך השתלשלות והתלבשות כבבהמה טהורה רק בחי' מקיף מלמעלה והוא בחי' לבונה כו' כמ\"ש במ\"א."],[38,"וזהו שעשו היה בכור שהוא מבחי' לפני מלך מלך כו' בהר שעיר בארץ אדום כו' ועשו היה מקור הז' מלכים שמלכו כו' וימת וימלוך וימת וימלוך כו' שהוא בחי' שליא המקפת על הולד שקדמה לולד."],[38,"והעיקר הוא הולד שנולד ובצאתו זורקין השליא כו' שאינו מקבל רק בחי' מקיף. לפיכך עליהם נאמר רם על כל גוים הוי\"ה ויעקב יו\"ד עקב הוי\"ה אלקינו ואהבת את ה' אלקיך כו' הגם שיו\"ד היא הארה מצומצמת הלא מצער היא ויכולה ליכנס בפנימי' ואין הכלי יכולה לקבל אלא ע\"י צמצום כמו יו\"ד כו' כדי שמזה יהיה לו רשפי אש והתלהבות בתפלה וכיוצא בה שמפני שהיא הארה מועטת יש כח ⟦כה,ד⟧בלב להיות מכילה."],[38,"והמשכת אלקות מלמעלה ג\"כ ע\"י התלבשות כלים אשר קדשנו במצותיו רמ\"ח אברין דמלכא. ובימי האבות שלא ניתנה תורה היו להם עובדות אחרים כמו בארות ומקלות כו'. משא\"כ עכו\"ם לפי שהוא רם ונשא עליהם דהיינו בחי' המקיף בלבד אינו נכנס תוך פנימיותם להיות בטל אליו רק הוא יש ונפרד בפ\"ע שאין לו שייכות כלל הגם דקרו ליה אלקא דאלקיא:"],[38,"<b>והנה<\/b> הקרבנות הם העלאת מ\"ן להיות ריח ניחוח דהיינו כמו ריח שהוא משיב את הנפש כך הקרבנות הם מעלים מ\"ן בבחי' ריח שיהיה ניחוח להוי\"ה גילוי המשכת והשראת שכינתו שיהא שורה ומתגלה בחי' אלקות בנפשו וזהו ניחוח לשון ירידה דהיינו שיהא ירידה והשתלשלות אלקות מעילה לעילה עד שיכנס ויתגלה בנפש האדם בתוכו ובפנימיותו ממש והטעם כי הנה ענין העלאת מ\"ן היינו כמו שמביאין למלך דבר חדש בכדי שיפנה אל בקשה הקטנה והנמוכה לגבי מעלת ומדרגת המלך. שע\"י דבר חדש הוא ממשיך לב המלך כמו ע\"י צפור המדברת הגם שבנ\"א מדברים בבינה יתירה אך מצד החידוש שהצפור תדבר עי\"ז ימשיך ויעורר לב מלכים אין חקר שיפנה לבקשת ההדיוט."],[38,"ולכן העלאת מ\"ן תלוי באתעדל\"ת דייקא נפשות ישראל המלובשים בגוף כו'. הגם שהמלאכים עומדים ברום עולם ותמיד מששת ימ\"ב בלי הפסק אומרים ביראה קדוש גם בדעת יותר ידברו שהשגתם גדולה ועצומה ומתענגים על ה' לאין קץ. משא\"כ למטה שיש מחשבות זרות רבות הטורדות ומפילות לב האדם וגם האהבה שמעורר חולפת ועוברת ויש לה הפסק וכו'. אך בשביל החדוש שבזה שהרי כח זה באדם למטה להיות מדבר הוא מאכילה ושתיה."],[38,"ומי שאינו אוכל ג' ימים נעשה חלוש ואין לו כח הדבור בשלימות וכן כמה מניעות שתלוי בגשמיות כמו מניעת הקור כו' הרי כח הדבור שלמטה שחיותו מדברים גשמיים דבר זה יקר מאד בעיני ה'. וכמשל צפור הנ\"ל. וכן כל הקרבנות כבשים ועזים הוא מהתלבשות בי\"ע כו'. ולכן כשעולה למעלה הוא דבר חדש מה שלא נראה כן בעולמות עליונים ולכן הם המעלים מ\"נ ולכן נק' בשם מנחה. מנחה ר\"ת מ\"ן מיין נוקבין. ח' חכמה ומזל הח' נוצר חסד ומשפיע בה' בה' בראם היא בחי' כנ\"י (גם לשון מנחה מל' ניחוח) והנה לע\"ל כתיב אז אהפך אל עמים שפה ברורה כו'. וכן דהע\"ה אמר הודיעו בעמים עלילותיו וכתיב הבו לה' משפחות עמים כו' ויאמרו בגוים כו'. ולהבין מה לנו להזכיר את עובדי כוכבים. אך הענין כי הנה כל הבירורין הוא מבחי' עמים ששם נפלו רפ\"ח הנצוצין והוא ע\"י בחי' לבונה שהוא המקיף שעליהם שהוא יתברר ויעלה למעלה בקדושה ויהיה עשו במדרגתו הגבוה לפני מלך מלך כו' מעולם התהו בקדושה כי יעקב י' עקב הוא בחי' פנימי' ויקם עדות ביעקב ותורה שם בישראל ואתם קרויים אדם אדם מ\"ה עולם התקון ולע\"ל יתברר גם עשו שמעולם התהו בחי' המקיף שיהי' בחי' מקיף דקדושה ויוכלל הכל ביעקב שיהי' ליעקב גם בחי' המקיף שהוא בחי' ומדרגה יותר עליונה שם ס\"ג שהוא גדול משם מ\"ה ואשת חיל כו':"],[38,"<b>והנה<\/b> כפי ההמשכה שלמעלה כך צ\"ל המ\"ן שמלמטה וכדי להמשיך בחי' המקיף עליון דקדושה צ\"ל העלאת מ\"ן בבחי' מקיף דהיינו למעלה מכדי שתוכל נפשו שאת וכנ\"ל. ובפרט כשרואה בנפשו הפחיתות מרבות מחשבות המעיקים וטורדים ומפילים אזי צריך הוא לצעוק אל ה' בצר לו למעלה מכדי שתוכל נפשו שאת."],[38,"ולכן כשראה יעקב את עשו למטה קם עליו הקריב מנחה היא העלא' לעשו אחיו שלמעלה מעולם התהו ששם הוא אחיו כי יעקב יש לו ב' בחי' רו\"ש. ⟦כו,א⟧שוב בבחי' י' עקב ורצוא בבחי' ביטול לגמרי כו' להמשיך בחי' המקיף עליון. ואזי יהי' עשו שלמטה ממילא בטל ואזי יקוים אז אהפך אל עמים כי מעשה אבות סימן לבנים שהם עשו הכנה לבניהם לע\"ל במעשיהם."],[38,"והנה העלאת מ\"ן של התקון גלוי וידוע לנו ע\"פ התורה פרים בני בקר שנים כו'. בפסח כך. ובשבועות כך כו' משא\"כ העלאת מ\"ן לעולם התהו אין אתנו יודע עד מה האיך ומה הם הקרבנות ואיזה שיעור רק יעקב אע\"ה ידע ענינם וכך שלח קרבנות עזים מאתים כו' שהם קרבנות אחרים אשר לא כתובים בתורה בקרבנות דתקון ושיעורים אחרים."],[38,"ולכן הקריב גם גמלים שהם טמאים בקרבנות דתקון. אך בקרבנות דתהו כתיב מי יתן טהור מטמא כו'. ששם כחשכה כאורה כו' קטן וגדול שם הוא כו' השוה ומשוה כו'. וזהו ענין ויחבקהו. שעשו חיבק את יעקב."],[38,"ובכ\"מ הזכר מחבק וכמ\"ש וימינו תחבקני שהמשפיע מחבק את המקבל ומקיפו מכל צד להגביהו למעלה כו'. והיינו לפי שעשו שרשו מבחי' מקיף מעולם התהו. אך הדרך שיגיע לזה הוא ע\"י כי והוא עבר לפניהם בחי' והוא כו' ואח\"כ וישתחו ארצה שבע פעמים בחי' נפ\"א ללקט נצוצין. עד גשתו עד אחיו. פי' עד שגשש ופגע באחיו דהיינו שליקט את הטוב שבעשו בחי' לבונה שעי\"ז הוא אחיו של יעקב שהמקיף והפנימי נלקחו ממקום א'."],[38,"ואזי וירץ עשו לקראתו. עשו הוא כח המלובש בעשו הגשמי רץ ממטה למעלה לקראתו וכמשל הנרות שבטלים לאבוקה כאשר נקרבו אורם לאור האבוקה כו'. ואחר שנברר בחי' הטוב שבו אזי ויחבקהו מלמעלה למטה שנכנס המקיף עליון ג\"כ ביעקב."],[38,"ונמצא שנכללו ביעקב כל הבחי' כנ\"ל. ועי\"ז וישקהו בחי' נשיקין ונקוד עליו בחי' נקודות הוא בחי' חכמה והיינו לפי שבשבירה היה הסתלקות חכמה ועתה אחר הבירור הנה נתגלה. ואח\"כ ויבכו הנה בכיה היא מפני שמחה או מרירות שע\"י כיווץ במוח דוחה המותרות בליחות הדמעות. וע\"י שמחה הוא כמ\"ש בזוהר שה\"ש גבי ר\"ע שזלגו עיניו כו'. והיינו לפי שהשמחה הוא התפשטות החיות כמ\"ש ושמועה טובה טובה תדשן עצם. וכמעשה דאספסיינוס כו' הוא הילוך הדם בעורקים וכן ברוח החיות שבו וכן בהמשכות מוחין חדשים כי יש בחי' עבור יניק' מוחין."],[38,"והנה כשיש כלי למטה לקבל השמחה אז היא מתפשטת ונותנת מוחין חדשים. וכן עי\"ז מתפשט רוח החיים לדשן עצם כנ\"ל. אבל כשהכלי שלמטה קטן מהכיל אזי מתקבץ במוח ודוחה המותרות בליחות הדמעות."],[38,"וענין זה היה ג\"כ גבי יעקב ועשו שהי' התגלות בחי' כתר למעלה מעלה כו' והיה רוב שמחה שנתקרבו כ\"כ מעלה מעלה עם מה שנפל למטה מטה בריחוק בשבה\"כ. עשו ויעקב כמו שני אחין שלא ראו זא\"ז זמן רב מאז היה שבה\"כ. וז\"ש לע\"ל בבכי יבאו שע\"י בחי' בכיה דוקא שהוא ע\"י התגלות מדרגות הגבוהות כו'. ובתחנונים אובילם אל נחלי מים:"],[39,"<b>ויאבק איש עמו כו'.<\/b> הנה נודע שמלחמה זו היא מלחמת הס\"מ בסטרא דקדושה. וכענין מלחמה לה' בעמלק וכנודע מן הפרדס שמה שנגע בכף ירך יעקב. דפגים אתר דנבואה עד דאתא שמואל ותקן הנצח כמ\"ש וגם נצח ישראל לא ישקר."]]);
